import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.9
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    caps = [int(resources[r]) for r in rnames]
    K = len(rnames)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        idx[x] = i
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = []
    req = []
    for i, j in enumerate(jobs):
        ps = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            q = idx[p]
            if q == i:
                return _infeasible(state, "precedence cycle: %s depends on itself" % ids[i])
            if q not in ps:
                ps.append(q)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s requires unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > caps[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s, capacity %d" % (ids[i], u, r, caps[ridx[r]]))
            if u > 0:
                rq.append((ridx[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        v = topo[k]
        k += 1
        for s in succs[v]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        rest = [ids[i] for i in range(n) if indeg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(rest[:6]))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rank = [0] * n
    for k, v in enumerate(topo):
        rank[v] = k
    for i in range(n):
        if dur[i] == 0:
            req[i] = []

    # lower bounds
    es = [0] * n
    for v in topo:
        t = rel[v]
        for p in preds[v]:
            f = es[p] + dur[p]
            if f > t:
                t = f
        es[v] = t
    tail = [0] * n
    for v in reversed(topo):
        m = 0
        for s in succs[v]:
            if tail[s] > m:
                m = tail[s]
        tail[v] = dur[v] + m
    LB = max(es[v] + tail[v] for v in range(n))
    for r in range(K):
        items = []
        for i in range(n):
            for rr, u in req[i]:
                if rr == r:
                    items.append((es[i], dur[i] * u, tail[i] - dur[i]))
        if not items or caps[r] <= 0:
            continue
        items.sort()
        tot = 0
        mt = 10 ** 9
        for a in range(len(items) - 1, -1, -1):
            tot += items[a][1]
            if items[a][2] < mt:
                mt = items[a][2]
            b = items[a][0] + -(-tot // caps[r]) + mt
            if b > LB:
                LB = b
    H = max(rel) + sum(dur) + 14

    def sgs(order):
        usage = [[0] * H for _ in range(K)]
        st = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            rq = req[j]
            if rq:
                d = dur[j]
                while True:
                    ok = True
                    for r, u in rq:
                        lim = caps[r] - u
                        ur = usage[r]
                        for tau in range(t, t + d):
                            if ur[tau] > lim:
                                t = tau + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for r, u in rq:
                    ur = usage[r]
                    for tau in range(t, t + d):
                        ur[tau] += u
            st[j] = t
        return st

    def mksp(st):
        return max(st[i] + dur[i] for i in range(n))

    def backward(st, T):
        order = sorted(range(n), key=lambda i: (-(st[i] + dur[i]), -rank[i]))
        usage = [[0] * (T + 1) for _ in range(K)]
        ns = [0] * n
        for j in order:
            d = dur[j]
            ub = T - d
            for s in succs[j]:
                v = ns[s] - d
                if v < ub:
                    ub = v
            t = ub
            rq = req[j]
            if rq:
                while True:
                    if t < rel[j]:
                        return None
                    ok = True
                    for r, u in rq:
                        lim = caps[r] - u
                        ur = usage[r]
                        for tau in range(t + d - 1, t - 1, -1):
                            if ur[tau] > lim:
                                t = tau - d
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for r, u in rq:
                    ur = usage[r]
                    for tau in range(t, t + d):
                        ur[tau] += u
            if t < rel[j]:
                return None
            ns[j] = t
        return ns

    def evaluate(order):
        st = sgs(order)
        ms = mksp(st)
        for _ in range(4):
            if ms <= LB:
                break
            bs = backward(st, ms)
            if bs is None:
                break
            o2 = sorted(range(n), key=lambda i: (bs[i], rank[i]))
            st2 = sgs(o2)
            ms2 = mksp(st2)
            if ms2 <= ms:
                improved = ms2 < ms
                st, ms = st2, ms2
                if not improved:
                    break
            else:
                break
        lst = sorted(range(n), key=lambda i: (st[i], rank[i]))
        return ms, st, lst

    def build(keyf):
        deg = [len(preds[i]) for i in range(n)]
        h = [(keyf(i), rank[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, v = heapq.heappop(h)
            out.append(v)
            for s in succs[v]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (keyf(s), rank[s], s))
        return out

    nsucc = [0] * n
    for v in range(n):
        seen = set()
        stack = list(succs[v])
        while stack:
            x = stack.pop()
            if x not in seen:
                seen.add(x)
                stack.extend(succs[x])
        nsucc[v] = len(seen)
    grpw = [dur[i] + sum(dur[s] for s in succs[i]) for i in range(n)]
    work = [dur[i] * sum(u / max(1, caps[r]) for r, u in req[i]) for i in range(n)]
    lft = [LB - tail[i] + dur[i] for i in range(n)]
    rules = [
        lambda i: (lft[i] - dur[i], es[i]),
        lambda i: (lft[i], es[i]),
        lambda i: (-tail[i], es[i]),
        lambda i: (es[i], -tail[i]),
        lambda i: (-nsucc[i], -tail[i]),
        lambda i: (-grpw[i], es[i]),
        lambda i: (-work[i], -tail[i]),
        lambda i: (rel[i], -tail[i]),
        lambda i: (es[i] - tail[i],),
    ]
    rng = random.Random(12345)
    best = None
    pop = []
    seenk = set()

    def add(ms, st, lst):
        nonlocal best
        if best is None or ms < best[0]:
            best = (ms, st)
        key = tuple(lst)
        if key in seenk:
            return
        seenk.add(key)
        pop.append((ms, lst))

    for kf in rules:
        o = build(kf)
        add(*evaluate(o))
        if best[0] <= LB:
            break

    def elapsed():
        return time.perf_counter() - t0

    P = 30
    tries = 0
    while best[0] > LB and len(pop) < P and tries < 200 and elapsed() < budget * 0.3:
        tries += 1
        noise = [rng.random() * (2 + rng.random() * 10) for _ in range(n)]
        mode = rng.randrange(3)
        if mode == 0:
            o = build(lambda i: (lft[i] - dur[i] + noise[i],))
        elif mode == 1:
            o = build(lambda i: (es[i] - tail[i] + noise[i],))
        else:
            o = build(lambda i: (rng.random(),))
        add(*evaluate(o))

    pos = [0] * n
    gen = 0
    while best[0] > LB and elapsed() < budget:
        gen += 1
        pop.sort(key=lambda x: x[0])
        if len(pop) > P:
            for x in pop[P:]:
                seenk.discard(tuple(x[1]))
            del pop[P:]
        m = len(pop)

        def pick():
            a = rng.randrange(m)
            b = rng.randrange(m)
            return pop[min(a, b)][1]
        A = pick()
        B = pick()
        q1 = rng.randrange(n + 1)
        q2 = rng.randrange(q1, n + 1)
        child = A[:q1]
        inc = set(child)
        mid = [x for x in B if x not in inc]
        part = mid[:q2 - q1]
        child.extend(part)
        inc.update(part)
        child.extend([x for x in A if x not in inc])
        nm = 1 + (rng.random() < 0.5) + (rng.random() < 0.2)
        for _ in range(nm):
            for k2, v in enumerate(child):
                pos[v] = k2
            v = child[rng.randrange(n)]
            lo = 0
            for p in preds[v]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n - 1
            for s in succs[v]:
                if pos[s] - 1 < hi:
                    hi = pos[s] - 1
            pv = pos[v]
            if hi > lo:
                np_ = rng.randint(lo, hi)
                child.pop(pv)
                child.insert(np_, v)
        add(*evaluate(child))
        if gen % 200 == 0 and len(pop) < 5:
            o = build(lambda i: (rng.random(),))
            add(*evaluate(o))

    st = best[1]
    ok = True
    for i in range(n):
        if st[i] < rel[i]:
            ok = False
        for p in preds[i]:
            if st[i] < st[p] + dur[p]:
                ok = False
    if ok:
        Tm = max(st[i] + dur[i] for i in range(n)) + 1
        use = [[0] * Tm for _ in range(K)]
        for i in range(n):
            for r, u in req[i]:
                for tau in range(st[i], st[i] + dur[i]):
                    use[r][tau] += u
        for r in range(K):
            if max(use[r]) > caps[r]:
                ok = False
    if not ok:
        st = [0] * n
        t = 0
        for v in topo:
            t = max(t, rel[v])
            st[v] = t
            t += dur[v]
    state["output"] = {"status": "ok", "start": {ids[i]: int(st[i]) for i in range(n)}}
    return state

