def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = []
    idx = {}
    for k, jb in enumerate(jobs):
        jid = str(jb.get("id"))
        ids.append(jid)
        if jid not in idx:
            idx[jid] = k
    n = len(jobs)
    for jb in jobs:
        for p in (jb.get("after") or []):
            if str(p) not in idx:
                return None, "job %s references unknown job %s" % (jb.get("id"), p)
        for r, u in (jb.get("requires") or {}).items():
            if r not in resources:
                return None, "job %s references unknown resource %s" % (jb.get("id"), r)
            try:
                cap = int(resources[r])
            except Exception:
                cap = 0
            if int(u) > cap:
                return None, "job %s requires %s units of %s but capacity is %s" % (jb.get("id"), u, r, cap)
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for k, jb in enumerate(jobs):
        seen = set()
        for p in (jb.get("after") or []):
            pi = idx[str(p)]
            if pi in seen:
                continue
            seen.add(pi)
            preds[k].append(pi)
            succs[pi].append(k)
    indeg = [len(preds[k]) for k in range(n)]
    queue = [k for k in range(n) if indeg[k] == 0]
    topo = []
    qi = 0
    while qi < len(queue):
        k = queue[qi]
        qi += 1
        topo.append(k)
        for s in succs[k]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) < n:
        cyc = [ids[k] for k in range(n) if indeg[k] > 0]
        return None, "precedence cycle among " + ", ".join(cyc[:6])
    return {"ids": ids, "preds": preds, "succs": succs, "topo": topo}, None


def solve(state, params):
    t0 = time.perf_counter()
    budget = 1.1
    inp = state.get("input") or {}
    info, reason = _validate(inp)
    if info is None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    ids = info["ids"]
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    preds = info["preds"]
    succs = info["succs"]
    topo = info["topo"]
    rnames = list(resources.keys())
    rindex = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    dur = [max(0, int(jb.get("duration", 0) or 0)) for jb in jobs]
    rel = [max(0, int(jb.get("release", 0) or 0)) for jb in jobs]
    req = []
    for k, jb in enumerate(jobs):
        lst = []
        for r, u in (jb.get("requires") or {}).items():
            u = int(u)
            if u > 0 and dur[k] > 0:
                lst.append((rindex[r], u))
        req.append(lst)
    R = len(rnames)
    H = max(rel) + sum(dur) + 2
    zeros = [0] * n
    topo_pos = [0] * n
    for i, k in enumerate(topo):
        topo_pos[k] = i

    # heads and tails
    head = [0] * n
    for k in topo:
        h = rel[k]
        for p in preds[k]:
            v = head[p] + dur[p]
            if v > h:
                h = v
        head[k] = h
    tail = [0] * n
    for k in reversed(topo):
        t = 0
        for s in succs[k]:
            if tail[s] > t:
                t = tail[s]
        tail[k] = t + dur[k]
    LB = max(head[k] + tail[k] for k in range(n))
    for ri in range(R):
        en = 0
        mr = None
        for k in range(n):
            for (r2, u) in req[k]:
                if r2 == ri:
                    en += u * dur[k]
                    mr = head[k] if mr is None else min(mr, head[k])
        if en > 0 and cap[ri] > 0:
            v = mr + (en + cap[ri] - 1) // cap[ri]
            if v > LB:
                LB = v
    nsucc_total = [0] * n
    for k in range(n):
        seen = set()
        stack = list(succs[k])
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            stack.extend(succs[x])
        nsucc_total[k] = len(seen)

    def sgs(order, pl, rl):
        usage = [[0] * H for _ in range(R)]
        start = [0] * n
        fin = [0] * n
        ms = 0
        for j in order:
            t = rl[j]
            for p in pl[j]:
                if fin[p] > t:
                    t = fin[p]
            d = dur[j]
            rq = req[j]
            if rq:
                while True:
                    ok = True
                    for (ri, u) in rq:
                        arr = usage[ri]
                        lim = cap[ri] - u
                        for tt in range(t + d - 1, t - 1, -1):
                            if arr[tt] > lim:
                                t = tt + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (ri, u) in rq:
                    arr = usage[ri]
                    for tt in range(t, t + d):
                        arr[tt] += u
            start[j] = t
            f = t + d
            fin[j] = f
            if f > ms:
                ms = f
        return start, ms

    def order_from_prio(prio):
        indeg = [len(preds[k]) for k in range(n)]
        hp = [(prio[k], topo_pos[k], k) for k in range(n) if indeg[k] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, k = heapq.heappop(hp)
            out.append(k)
            for s in succs[k]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    heapq.heappush(hp, (prio[s], topo_pos[s], s))
        return out

    def fbi(start, ms):
        best_s, best_ms = start, ms
        for _ in range(4):
            fin = [best_s[k] + dur[k] for k in range(n)]
            border = sorted(range(n), key=lambda k: (-fin[k], -topo_pos[k]))
            rs, rms = sgs(border, succs, zeros)
            rfin = [rs[k] + dur[k] for k in range(n)]
            forder = sorted(range(n), key=lambda k: (-rfin[k], topo_pos[k]))
            fs, fms = sgs(forder, preds, rel)
            if fms < best_ms:
                best_s, best_ms = fs, fms
            else:
                break
        return best_s, best_ms

    def order_from_start(s):
        return sorted(range(n), key=lambda k: (s[k], topo_pos[k]))

    rng = random.Random(12345)
    best_start = None
    best_ms = None
    pool = []

    def consider(order):
        nonlocal best_start, best_ms
        s, ms = sgs(order, preds, rel)
        s2, ms2 = fbi(s, ms)
        if ms2 < ms:
            s, ms = s2, ms2
        if best_ms is None or ms < best_ms:
            best_start, best_ms = s, ms
        pool.append((ms, order_from_start(s)))
        return ms

    rules = [
        [-tail[k] for k in range(n)],
        [-(tail[k] + head[k]) for k in range(n)],
        [(LB - tail[k]) for k in range(n)],
        [-nsucc_total[k] for k in range(n)],
        [head[k] for k in range(n)],
        [rel[k] * 1000 - tail[k] for k in range(n)],
        [-tail[k] * 100 - sum(u for _, u in req[k]) for k in range(n)],
        [head[k] * 100 - tail[k] for k in range(n)],
    ]
    for pr in rules:
        consider(order_from_prio(pr))
        if best_ms <= LB:
            break

    # random sampling phase
    samp_end = t0 + budget * 0.3
    while best_ms > LB and time.perf_counter() < samp_end:
        a = rng.random()
        pr = [-(tail[k]) + a * head[k] + rng.uniform(0, 1) * (1 + 0.3 * tail[k] + rng.random() * 3) for k in range(n)]
        consider(order_from_prio(pr))

    # local search on activity lists
    pool.sort(key=lambda x: x[0])
    elites = [o for _, o in pool[:5]]
    deadline = t0 + budget
    ei = 0
    while best_ms > LB and time.perf_counter() < deadline and n > 1:
        cur = list(elites[ei % len(elites)])
        ei += 1
        s, cur_ms = sgs(cur, preds, rel)
        stall = 0
        it = 0
        while stall < 60 + 8 * n and time.perf_counter() < deadline:
            it += 1
            pos = {k: i for i, k in enumerate(cur)}
            i = rng.randrange(n)
            j = cur[i]
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n - 1
            for sx in succs[j]:
                if pos[sx] - 1 < hi:
                    hi = pos[sx] - 1
            if hi <= lo:
                stall += 1
                continue
            npos = rng.randint(lo, hi)
            if npos == i:
                stall += 1
                continue
            cand = cur[:i] + cur[i + 1:]
            cand.insert(npos, j)
            cs, cms = sgs(cand, preds, rel)
            if cms <= cur_ms:
                if cms < cur_ms:
                    stall = 0
                else:
                    stall += 1
                cur, cur_ms, s = cand, cms, cs
                if cms < best_ms:
                    best_start, best_ms = cs, cms
                    if best_ms <= LB:
                        break
            else:
                stall += 1
            if it % 25 == 0:
                fs, fms = fbi(s, cur_ms)
                if fms <= cur_ms:
                    s, cur_ms = fs, fms
                    cur = order_from_start(fs)
                    if fms < best_ms:
                        best_start, best_ms = fs, fms
                        if best_ms <= LB:
                            break
        if best_ms > LB and time.perf_counter() < deadline:
            # inject a perturbed version of the best as a new elite
            ob = order_from_start(best_start)
            elites.append(ob)
            if len(elites) > 8:
                elites.pop(0)

    # final verification (safety)
    start = best_start
    ok = True
    for k in range(n):
        if start[k] < rel[k]:
            ok = False
        for p in preds[k]:
            if start[k] < start[p] + dur[p]:
                ok = False
    if ok:
        usage = [[0] * H for _ in range(R)]
        for k in range(n):
            for (ri, u) in req[k]:
                for tt in range(start[k], start[k] + dur[k]):
                    usage[ri][tt] += u
                    if usage[ri][tt] > cap[ri]:
                        ok = False
    if not ok:
        start, _ = sgs(topo, preds, rel)
    out = {}
    for k in range(n):
        out[ids[k]] = int(start[k])
    state["output"] = {"status": "ok", "start": out}
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _valid(n, dur, rel, preds, req, cap, start):
    for j in range(n):
        if start[j] < rel[j]:
            return False
        for p in preds[j]:
            if start[j] < start[p] + dur[p]:
                return False
    use = {}
    for j in range(n):
        if dur[j] <= 0:
            continue
        for (r, u) in req[j]:
            for t in range(start[j], start[j] + dur[j]):
                k = (r, t)
                use[k] = use.get(k, 0) + u
                if use[k] > cap[r]:
                    return False
    return True


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 1.0
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    dur = [int(j.get("duration", 0) or 0) for j in jobs]
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    preds = []
    req = []
    for i, j in enumerate(jobs):
        ps = []
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            k = idx[p]
            if k not in seen:
                seen.add(k)
                ps.append(k)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > cap[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s, capacity %d" % (ids[i], u, r, cap[ridx[r]]))
            if u > 0:
                rq.append((ridx[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    # topological sort
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    qi = 0
    while qi < len(q):
        j = q[qi]
        qi += 1
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if indeg[j] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(rem[:8]))
    tpos = [0] * n
    for k, j in enumerate(topo):
        tpos[j] = k

    # fallback trivial schedule
    fb = [0] * n
    t = 0
    for j in topo:
        st = max(t, rel[j])
        fb[j] = st
        t = st + dur[j]

    # CPM
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = head[p] + dur[p]
            if v > e:
                e = v
        head[j] = e
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(head[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        work = 0
        mr = None
        for j in range(n):
            for (rr, u) in req[j]:
                if rr == r and dur[j] > 0:
                    work += u * dur[j]
                    mr = rel[j] if mr is None else min(mr, rel[j])
        if work > 0 and cap[r] > 0:
            LB = max(LB, mr + (work + cap[r] - 1) // cap[r])

    H = max(rel) + sum(dur) + max(dur) + 2
    R = len(cap)
    zeros = [0] * n

    def sgs(order, pr, rl):
        start = [0] * n
        fin = [0] * n
        usage = [[0] * H for _ in range(R)]
        ms = 0
        for j in order:
            est = rl[j]
            for p in pr[j]:
                if fin[p] > est:
                    est = fin[p]
            d = dur[j]
            rq = req[j]
            t = est
            if d > 0 and rq:
                while True:
                    ok = True
                    for (r, u) in rq:
                        lim = cap[r] - u
                        ur = usage[r]
                        s = t + d - 1
                        while s >= t:
                            if ur[s] > lim:
                                break
                            s -= 1
                        if s >= t:
                            t = s + 1
                            ok = False
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] += u
            start[j] = t
            f = t + d
            fin[j] = f
            if f > ms:
                ms = f
        return start, ms

    def fbi(order):
        st, ms = sgs(order, preds, rel)
        best_st, best_ms = st, ms
        for _ in range(6):
            border = sorted(range(n), key=lambda j: (-(best_st[j] + dur[j]), -tpos[j]))
            rs, _m = sgs(border, succs, zeros)
            forder = sorted(range(n), key=lambda j: (-(rs[j] + dur[j]), tpos[j]))
            st2, ms2 = sgs(forder, preds, rel)
            if ms2 < best_ms:
                best_st, best_ms = st2, ms2
            else:
                break
        lst = sorted(range(n), key=lambda j: (best_st[j], tpos[j]))
        return best_st, best_ms, lst

    def gen_list(prio, rnd=None, alpha=2.0):
        deg = [len(preds[j]) for j in range(n)]
        elig = [j for j in range(n) if deg[j] == 0]
        out = []
        while elig:
            if rnd is None:
                k = min(range(len(elig)), key=lambda i: (prio[elig[i]], tpos[elig[i]]))
            else:
                mx = max(prio[e] for e in elig)
                ws = [(mx - prio[e] + 1.0) ** alpha for e in elig]
                tot = sum(ws)
                x = rnd.random() * tot
                k = 0
                acc = ws[0]
                while acc < x and k < len(elig) - 1:
                    k += 1
                    acc += ws[k]
            j = elig.pop(k)
            out.append(j)
            for s in succs[j]:
                deg[s] -= 1
                if deg[s] == 0:
                    elig.append(s)
        return out

    nsucc = [0] * n
    for j in reversed(topo):
        acc = set()
        for s in succs[j]:
            acc.add(s)
        stack = list(succs[j])
        while stack:
            x = stack.pop()
            for y in succs[x]:
                if y not in acc:
                    acc.add(y)
                    stack.append(y)
        nsucc[j] = len(acc)
    CP = max(head[j] + tail[j] for j in range(n))
    rw = [sum(u / float(cap[r]) for (r, u) in req[j]) * dur[j] for j in range(n)]
    rwt = [0.0] * n
    for j in reversed(topo):
        m = 0.0
        for s in succs[j]:
            if rwt[s] > m:
                m = rwt[s]
        rwt[j] = rw[j] + dur[j] + m
    rules = [
        [-tail[j] for j in range(n)],
        [-(tail[j] - dur[j]) for j in range(n)],
        [(CP - tail[j]) - head[j] for j in range(n)],
        [head[j] - 0.001 * tail[j] for j in range(n)],
        [-nsucc[j] - 0.001 * tail[j] for j in range(n)],
        [-rwt[j] for j in range(n)],
        [rel[j] - tail[j] for j in range(n)],
    ]

    best_st = fb
    best_ms = max(fb[j] + dur[j] for j in range(n))
    best_list = list(topo)

    def consider(st, ms, lst):
        nonlocal best_st, best_ms, best_list
        if ms < best_ms:
            best_st, best_ms, best_list = st, ms, lst
            return True
        return False

    for pr in rules:
        st, ms, lst = fbi(gen_list(pr))
        consider(st, ms, lst)
        if best_ms <= LB:
            break

    rnd = random.Random(12345)
    cur_list = list(best_list)
    cur_ms = best_ms
    stall = 0
    it = 0
    while best_ms > LB and time.perf_counter() - T0 < BUDGET:
        it += 1
        if stall > 150 or it % 7 == 0:
            pr = rules[rnd.randrange(len(rules))]
            st, ms, lst = fbi(gen_list(pr, rnd, rnd.choice([1.0, 2.0, 3.0])))
            consider(st, ms, lst)
            if stall > 150:
                cur_list, cur_ms = lst, ms
                stall = 0
            continue
        L = list(cur_list)
        nm = 1 + (rnd.random() < 0.3)
        for _ in range(nm):
            i = rnd.randrange(n)
            j = L.pop(i)
            pos = {x: k for k, x in enumerate(L)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(L)
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            L.insert(rnd.randint(lo, hi), j)
        st, ms, lst = fbi(L)
        consider(st, ms, lst)
        if ms <= cur_ms:
            if ms < cur_ms:
                stall = 0
            else:
                stall += 1
            cur_list, cur_ms = lst, ms
        else:
            stall += 1

    if not _valid(n, dur, rel, preds, req, cap, best_st):
        best_st = fb
    state["output"] = {"status": "ok", "start": {ids[j]: int(best_st[j]) for j in range(n)}}
    return state

