    trank = [0] * n
    for k, j in enumerate(topo):
        trank[j] = k
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = es[p] + dur[p]
            if v > e:
                e = v
        es[j] = e
    tail = [0] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            if tail[s] > t:
                t = tail[s]
        tail[j] = t + dur[j]
    nsucc_tot = [0] * n
    for j in reversed(topo):
        nsucc_tot[j] = len(succs[j]) + sum(nsucc_tot[s] for s in succs[j])

    # lower bound
    LB = 0
    for j in range(n):
        if es[j] + tail[j] > LB:
            LB = es[j] + tail[j]
    R = len(cap)
    for r in range(R):
        users = [j for j in range(n) if dur[j] > 0 and any(rr == r for rr, u in reqs[j])]
        if not users or cap[r] <= 0:
            continue
        users.sort(key=lambda j: es[j])
        for k in range(len(users)):
            t = es[users[k]]
            en = 0
            mt = 10 ** 9
            for j in users[k:]:
                for rr, u in reqs[j]:
                    if rr == r:
                        en += u * dur[j]
                mt = min(mt, tail[j] - dur[j])
            v = t + (en + cap[r] - 1) // cap[r] + max(0, mt)
            if v > LB:
                LB = v

    H = max(rel) + sum(dur) + 15
    for j in range(n):
        if es[j] + tail[j] + 15 > H:
            H = es[j] + tail[j] + 15
    LFT = [0] * n
    for j in reversed(topo):
        m = LB
        for s in succs[j]:
            v = LFT[s] - dur[s]
            if v < m:
                m = v
        LFT[j] = m

    def ssgs(order):
        use = [[0] * (H + 15) for _ in range(R)]
        st = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                v = st[p] + dur[p]
                if v > t:
                    t = v
            d = dur[j]
            rq = reqs[j]
            if d > 0 and rq:
                while True:
                    ok = True
                    for tt in range(t, t + d):
                        for r, u in rq:
                            if use[r][tt] + u > cap[r]:
                                ok = False
                                break
                        if not ok:
                            t = tt + 1
                            break
                    if ok:
                        break
                for r, u in rq:
                    ur = use[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
            st[j] = t
        return st

    def bsgs(st0, ms):
        order = sorted(range(n), key=lambda j: (-(st0[j] + dur[j]), -trank[j]))
        use = [[0] * (H + 15) for _ in range(R)]
        st = [0] * n
        for j in order:
            d = dur[j]
            ub = ms - d
            for s in succs[j]:
                v = st[s] - d
                if v < ub:
                    ub = v
            t = ub
            rq = reqs[j]
            if d > 0 and rq:
                while t >= rel[j]:
                    ok = True
                    for tt in range(t + d - 1, t - 1, -1):
                        for r, u in rq:
                            if use[r][tt] + u > cap[r]:
                                ok = False
                                break
                        if not ok:
                            t = tt - d
                            break
                    if ok:
                        break
            if t < st0[j]:
                t = st0[j]
            if d > 0 and rq:
                for r, u in rq:
                    ur = use[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
            st[j] = t
        return st

    def mksp(st):
        return max(st[j] + dur[j] for j in range(n))

    def improve(st):
        ms = mksp(st)
        for _ in range(10):
            b = bsgs(st, ms)
            order = sorted(range(n), key=lambda j: (b[j], trank[j]))
            f = ssgs(order)
            m2 = mksp(f)
            if m2 < ms:
                st, ms = f, m2
            else:
                if m2 == ms:
                    st = f
                break
        return st, ms

    def order_from_keys(key):
        dg = indeg[:]
        h = [(key[j], trank[j], j) for j in range(n) if dg[j] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (key[s], trank[s], s))
        return out

    best = None
    bms = None

    def consider(st, ms):
        nonlocal best, bms
        if bms is None or ms < bms:
            best, bms = st[:], ms

    work = [sum(u for r, u in reqs[j]) * dur[j] for j in range(n)]
    rules = [
        [LFT[j] for j in range(n)],
        [LFT[j] - dur[j] for j in range(n)],
        [-tail[j] for j in range(n)],
        [-nsucc_tot[j] for j in range(n)],
        [es[j] for j in range(n)],
        [es[j] * 1000 - tail[j] for j in range(n)],
        [-work[j] for j in range(n)],
        [rel[j] * 1000 + LFT[j] for j in range(n)],
    ]
    for key in rules:
        st = ssgs(order_from_keys(key))
        st, ms = improve(st)
        consider(st, ms)
        if bms <= LB or time.perf_counter() - t0 > 0.8:
            break

    rng = random.Random(12345)
    budget = 0.9
    it = 0
    while bms > LB and time.perf_counter() - t0 < budget:
        it += 1
        if it % 3:
            base = rules[it % len(rules)]
        else:
            base = [best[j] for j in range(n)]
        sc = rng.choice([0.05, 0.15, 0.3, 0.6])
        bs = abs(max(base) - min(base)) + 1
        key = [base[j] + rng.gauss(0, sc * bs) for j in range(n)]
        st = ssgs(order_from_keys(key))
        st, ms = improve(st)
        consider(st, ms)

    # final verification with safe fallback
    def valid(st):
        for j in range(n):
            if st[j] < rel[j]:
                return False
            for p in preds[j]:
                if st[j] < st[p] + dur[p]:
                    return False
        T = mksp(st)
        use = [[0] * (T + 2) for _ in range(R)]
        for j in range(n):
            for r, u in reqs[j]:
                for tt in range(st[j], st[j] + dur[j]):
                    use[r][tt] += u
                    if use[r][tt] > cap[r]:
                        return False
        return True

    if not valid(best):
        st = [0] * n
        cur = 0
        for j in topo:
            s = max(cur, rel[j])
            st[j] = s
            cur = s + dur[j]
        best = st

    state["output"] = {"status": "ok", "start": {ids[j]: int(best[j]) for j in range(n)}}
    return state

import time, random, heapq
from collections import deque


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    caps = {}
    for k, v in resources.items():
        caps[str(k)] = int(v)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(caps.keys())
    rix = {r: k for k, r in enumerate(rnames)}
    capl = [caps[r] for r in rnames]
    dur = []
    rel = []
    preds = []
    req = []
    for j in jobs:
        jid = str(j.get("id"))
        d = int(j.get("duration", 0) or 0)
        rl = int(j.get("release", 0) or 0)
        dur.append(max(0, d))
        rel.append(max(0, rl))
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (jid, p))
            if idx[p] not in pl:
                pl.append(idx[p])
        preds.append(pl)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            r = str(r)
            u = int(u)
            if r not in caps:
                return _infeasible(state, "job %s requires unknown resource %s" % (jid, r))
            if u > caps[r]:
                return _infeasible(state, "job %s requires %d %s > capacity %d" % (jid, u, r, caps[r]))
            if u > 0:
                rq.append((rix[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    dq = deque([i for i in range(n) if indeg[i] == 0])
    deg = indeg[:]
    topo = []
    while dq:
        x = dq.popleft()
        topo.append(x)
        for y in succs[x]:
            deg[y] -= 1
            if deg[y] == 0:
                dq.append(y)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))
    for i in range(n):
        if dur[i] == 0:
            req[i] = []

    es = [0] * n
    for x in topo:
        e = rel[x]
        for p in preds[x]:
            v = es[p] + dur[p]
            if v > e:
                e = v
        es[x] = e
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for y in succs[x]:
            if tail[y] > m:
                m = tail[y]
        tail[x] = dur[x] + m
    LB = max(es[i] + tail[i] for i in range(n))
    for k in range(len(capl)):
        users = [i for i in range(n) if any(r == k for r, u in req[i])]
        if not users:
            continue
        users.sort(key=lambda i: es[i])
        for a in range(len(users)):
            sub = users[a:]
            en = sum(dur[i] * dict(req[i])[k] for i in sub)
            mt = min(tail[i] - dur[i] for i in sub)
            b = es[users[a]] + -(-en // capl[k]) + mt
            if b > LB:
                LB = b
    H = max(rel) + sum(dur) + 15
    lst = [LB - tail[i] for i in range(n)]
    R = len(capl)

    def sgs(order):
        use = [[0] * H for _ in range(R)]
        st = [0] * n
        fin = [0] * n
        ms = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                if fin[p] > t:
                    t = fin[p]
            d = dur[j]
            rq = req[j]
            if rq:
                while True:
                    ok = True
                    for r, u in rq:
                        lim = capl[r] - u
                        arr = use[r]
                        for tt in range(t + d - 1, t - 1, -1):
                            if arr[tt] > lim:
                                ok = False
                                t = tt + 1
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for r, u in rq:
                    arr = use[r]
                    for tt in range(t, t + d):
                        arr[tt] += u
            st[j] = t
            fin[j] = t + d
            if t + d > ms:
                ms = t + d
        return ms, st

    def backward(st, ms):
        order = sorted(range(n), key=lambda i: -(st[i] + dur[i]))
        use = [[0] * H for _ in range(R)]
        ns = [0] * n
        done = [False] * n
        for j in order:
            lf = ms
            for s in succs[j]:
                if done[s] and ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            t = lf - d
            rq = req[j]
            if rq:
                while True:
                    if t < 0:
                        return None
                    ok = True
                    for r, u in rq:
                        lim = capl[r] - u
                        arr = use[r]
                        for tt in range(t, t + d):
                            if arr[tt] > lim:
                                ok = False
                                t = tt - d
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for r, u in rq:
                    arr = use[r]
                    for tt in range(t, t + d):
                        arr[tt] += u
            ns[j] = t
            done[j] = True
        return ns

    def topo_from_keys(key):
        dg = indeg[:]
        h = [(key[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for y in succs[x]:
                dg[y] -= 1
                if dg[y] == 0:
                    heapq.heappush(h, (key[y], y))
        return out

    best = [None, None, None]

    def consider(order):
        ms, st = sgs(order)
        if best[0] is None or ms < best[0]:
            best[0] = ms
            best[1] = st
            best[2] = order
        return ms, st

    def fbi(order, rounds=4):
        ms, st = consider(order)
        for _ in range(rounds):
            ns = backward(st, ms)
            if ns is None:
                break
            o2 = topo_from_keys([ns[i] * 64 + (st[i] % 64) for i in range(n)])
            m2, s2 = consider(o2)
            if m2 >= ms:
                break
            ms, st, order = m2, s2, o2
        return ms, st, order

    nsucc_all = [0] * n
    for x in range(n):
        seen = set()
        stack = list(succs[x])
        while stack:
            y = stack.pop()
            if y not in seen:
                seen.add(y)
                stack.extend(succs[y])
        nsucc_all[x] = len(seen)
    energy = [dur[i] * sum(u / capl[r] for r, u in req[i]) for i in range(n)]
    rules = [
        [lst[i] for i in range(n)],
        [-tail[i] for i in range(n)],
        [es[i] for i in range(n)],
        [-nsucc_all[i] for i in range(n)],
        [-(tail[i] + energy[i]) for i in range(n)],
        [lst[i] - energy[i] * 0.5 for i in range(n)],
        [-dur[i] for i in range(n)],
        [es[i] + lst[i] for i in range(n)],
    ]
    for key in rules:
        fbi(topo_from_keys(key))
        if best[0] <= LB:
            break

    budget = 0.9
    rng = random.Random(12345)
    if best[0] > LB:
        it = 0
        while time.perf_counter() - t0 < budget * 0.35 and best[0] > LB:
            base = rules[it % len(rules)]
            sc = max(1.0, max(base) - min(base))
            noise = rng.choice([0.1, 0.3, 0.6, 1.0])
            key = [base[i] + rng.random() * sc * noise for i in range(n)]
            fbi(topo_from_keys(key))
            it += 1
    if best[0] > LB and n > 1:
        cur = list(best[2])
        cur_ms = best[0]
        stall = 0
        while time.perf_counter() - t0 < budget and best[0] > LB:
            o = list(cur)
            pos = {j: k for k, j in enumerate(o)}
            moves = 1 if rng.random() < 0.7 else rng.randint(2, 4)
            for _ in range(moves):
                j = rng.randrange(n)
                p = pos[j]
                lo = 0
                for q in preds[j]:
                    if pos[q] + 1 > lo:
                        lo = pos[q] + 1
                hi = n - 1
                for q in succs[j]:
                    if pos[q] - 1 < hi:
                        hi = pos[q] - 1
                if hi <= lo:
                    continue
                np_ = rng.randint(lo, hi)
                if np_ == p:
                    continue
                o.pop(p)
                o.insert(np_, j)
                pos = {jj: k for k, jj in enumerate(o)}
            ms, st = consider(o)
            if ms <= cur_ms:
                if ms < cur_ms:
                    stall = 0
                cur, cur_ms = o, ms
            else:
                stall += 1
            if stall > 300:
                fbi(list(best[2]), 2)
                cur, cur_ms = list(best[2]), best[0]
                stall = 0
    st = best[1]
    state["output"] = {"status": "ok", "start": {ids[i]: int(st[i]) for i in range(n)}}
    return state

import time, random, heapq, math

def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 0.95
    random.seed(12345)
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    caps = [int(res[r]) for r in rnames]
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = []
    reqs = []
    for i, j in enumerate(jobs):
        ps = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "job %s references unknown job %s" % (ids[i], p)}
                return state
            q = jidx[p]
            if q not in ps:
                ps.append(q)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                state["output"] = {"status": "infeasible", "reason": "job %s requires unknown resource %s" % (ids[i], r)}
                return state
            u = int(u)
            k = ridx[r]
            if u > caps[k]:
                state["output"] = {"status": "infeasible", "reason": "job %s needs %d of %s, capacity %d" % (ids[i], u, r, caps[k])}
                return state
            if u > 0:
                rq.append((k, caps[k] - u, u))
        reqs.append(rq)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0][:6]
        state["output"] = {"status": "infeasible", "reason": "precedence cycle among " + ", ".join(cyc)}
        return state
    tpos = [0] * n
    for k, x in enumerate(topo):
        tpos[x] = k
    head = [0] * n
    for x in topo:
        h = rel[x]
        for p in preds[x]:
            h = max(h, head[p] + dur[p])
        head[x] = h
    tail = [0] * n
    for x in reversed(topo):
        t = dur[x]
        for s in succs[x]:
            t = max(t, dur[x] + tail[s])
        tail[x] = t
    LB = max(head[i] + tail[i] for i in range(n))
    R = len(caps)
    for k in range(R):
        if caps[k] <= 0:
            continue
        items = []
        for i in range(n):
            for (kk, lim, u) in reqs[i]:
                if kk == k and dur[i] > 0:
                    items.append((head[i], dur[i] * u, tail[i] - dur[i]))
        ths = sorted(set(a for a, b, c in items))
        for t0 in ths:
            sel = [(b, c) for a, b, c in items if a >= t0]
            w = sum(b for b, c in sel)
            mt = min(c for b, c in sel)
            LB = max(LB, t0 + (w + caps[k] - 1) // caps[k] + mt)
    H = max(rel) + sum(dur) + 20
    LST = [LB - tail[i] for i in range(n)]

    def place(use, j, s, sign):
        d = dur[j]
        for (k, lim, u) in reqs[j]:
            row = use[k]
            for t in range(s, s + d):
                row[t] += sign * u

    def earliest(use, j, est):
        d = dur[j]
        rq = reqs[j]
        if d == 0 or not rq:
            return est
        t = est
        while True:
            bad = -1
            for tau in range(t, t + d):
                for (k, lim, u) in rq:
                    if use[k][tau] > lim:
                        bad = tau
                        break
                if bad >= 0:
                    break
            if bad < 0:
                return t
            t = bad + 1

    def latest(use, j, lo, hi):
        d = dur[j]
        rq = reqs[j]
        if d == 0 or not rq:
            return hi
        s = hi
        while s > lo:
            bad = -1
            for tau in range(s + d - 1, s - 1, -1):
                for (k, lim, u) in rq:
                    if use[k][tau] > lim:
                        bad = tau
                        break
                if bad >= 0:
                    break
            if bad < 0:
                return s
            s = bad - d
        return lo

    def decode(keys):
        use = [[0] * H for _ in range(R)]
        dg = indeg[:]
        hp = [(keys[i], tpos[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(hp)
        st = [0] * n
        fin = [0] * n
        while hp:
            _, _, j = heapq.heappop(hp)
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            s = earliest(use, j, est)
            st[j] = s
            fin[j] = s + dur[j]
            if dur[j]:
                place(use, j, s, 1)
            for x in succs[j]:
                dg[x] -= 1
                if dg[x] == 0:
                    heapq.heappush(hp, (keys[x], tpos[x], x))
        return st, max(fin)

    def rightpass(st, cm):
        use = [[0] * H for _ in range(R)]
        for j in range(n):
            if dur[j]:
                place(use, j, st[j], 1)
        order = sorted(range(n), key=lambda j: (-(st[j] + dur[j]), -tpos[j]))
        ns = st[:]
        for j in order:
            hi = cm
            for x in succs[j]:
                if ns[x] < hi:
                    hi = ns[x]
            hi -= dur[j]
            lo = st[j]
            if hi <= lo:
                continue
            if dur[j]:
                place(use, j, st[j], -1)
            s = latest(use, j, lo, hi)
            ns[j] = s
            if dur[j]:
                place(use, j, s, 1)
        return ns

    def improve(st, cm):
        while True:
            ns = rightpass(st, cm)
            keys = [ns[i] + random.random() * 0.01 for i in range(n)]
            st2, cm2 = decode(keys)
            if cm2 < cm:
                st, cm = st2, cm2
            else:
                if cm2 == cm:
                    st = st2
                return st, cm, [st[i] + random.random() * 0.01 for i in range(n)]

    best = [None, 10 ** 9, None]
    elite = []

    def consider(keys):
        st, cm = decode(keys)
        st, cm, k2 = improve(st, cm)
        if cm < best[1]:
            best[0], best[1], best[2] = st, cm, k2
        elite.append((cm, random.random(), k2))
        elite.sort()
        del elite[8:]
        return cm

    nsucc = [0] * n
    reach = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            reach[x].add(s)
            reach[x] |= reach[s]
        nsucc[x] = len(reach[x])
    work = [dur[i] * sum(u / max(1, caps[k]) for (k, l, u) in reqs[i]) for i in range(n)]
    rules = [
        LST,
        [LST[i] + dur[i] for i in range(n)],
        [-tail[i] for i in range(n)],
        [head[i] for i in range(n)],
        [-nsucc[i] for i in range(n)],
        [LST[i] - work[i] for i in range(n)],
        [head[i] * 1.0 - tail[i] * 0.5 for i in range(n)],
    ]
    for kv in rules:
        consider(kv)
        if best[1] <= LB:
            break
    while best[1] > LB and time.perf_counter() - T0 < BUDGET:
        r = random.random()
        if r < 0.25:
            sc = random.choice([1.0, 3.0, 6.0, 12.0])
            keys = [LST[i] + random.random() * sc for i in range(n)]
        else:
            base = best[2] if (r < 0.6 or not elite) else random.choice(elite)[2]
            keys = base[:]
            if random.random() < 0.5:
                sc = random.choice([0.5, 1.5, 3.0, 6.0])
                keys = [keys[i] + random.random() * sc for i in range(n)]
            else:
                m = random.randint(1, max(1, n // 5))
                for _ in range(m):
                    a = random.randrange(n)
                    keys[a] += random.uniform(-8, 8)
        consider(keys)
    st = best[0]
    state["output"] = {"status": "ok", "start": {ids[i]: int(st[i]) for i in range(n)}}
    return state

import time
import random
import heapq


def _validate(inp):
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idset:
                return "job %s references unknown job %s" % (j.get("id"), p)
        for r, u in (j.get("requires") or {}).items():
            if r not in resources:
                return "job %s references unknown resource %s" % (j.get("id"), r)
            if int(u) > int(resources[r]):
                return "job %s requires %s units of %s but capacity is %s" % (j.get("id"), u, r, resources[r])
    idx = {}
    for i, s in enumerate(ids):
        idx.setdefault(s, i)
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in set(str(x) for x in (j.get("after") or [])):
            succ[idx[p]].append(i)
            indeg[i] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    seen = 0
    while q:
        v = q.pop()
        seen += 1
        for w in succ[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                q.append(w)
    if seen < n:
        cyc = [ids[i] for i in range(n) if indeg[i] > 0]
        return "precedence cycle among " + ", ".join(cyc[:6])
    return None


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.85
    inp = state.get("input") or {}
    err = _validate(inp)
    if err is not None:
        state["output"] = {"status": "infeasible", "reason": err}
        return state
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx.setdefault(s, i)
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    req = []
    for j in jobs:
        lst = []
        if int(j.get("duration", 0)) > 0:
            for r, u in (j.get("requires") or {}).items():
                u = int(u)
                if u > 0:
                    lst.append((ridx[r], u))
        req.append(lst)
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = []
    q = [i for i in range(n) if indeg[i] == 0]
    while q:
        v = q.pop()
        topo.append(v)
        for w in succs[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                q.append(w)
    es = [0] * n
    for v in topo:
        e = rel[v]
        for p in preds[v]:
            if es[p] + dur[p] > e:
                e = es[p] + dur[p]
        es[v] = e
    tail = [0] * n
    for v in reversed(topo):
        t = 0
        for w in succs[v]:
            if tail[w] > t:
                t = tail[w]
        tail[v] = dur[v] + t
    cp = max(es[v] + tail[v] for v in range(n))
    LB = cp
    nres = len(cap)
    for r in range(nres):
        if cap[r] <= 0:
            continue
        items = []
        for v in range(n):
            for rr, u in req[v]:
                if rr == r:
                    items.append((es[v], dur[v] * u, tail[v] - dur[v]))
        if not items:
            continue
        for a in set(x[0] for x in items):
            sel = [x for x in items if x[0] >= a]
            en = sum(x[1] for x in sel)
            mt = min(x[2] for x in sel)
            b = a + -(-en // cap[r]) + mt
            if b > LB:
                LB = b
    maxrel = max(rel)
    H = maxrel + sum(dur) + 16
    lft = [cp - (tail[v] - dur[v]) for v in range(n)]
    lst_ = [cp - tail[v] for v in range(n)]
    nsucc_tot = [0] * n
    desc = [0] * n
    for v in reversed(topo):
        b = 0
        for w in succs[v]:
            b |= desc[w] | (1 << w)
        desc[v] = b
        nsucc_tot[v] = bin(b).count("1")
    work = [dur[v] * sum(u / float(cap[r]) for r, u in req[v]) for v in range(n)]

    def decode(order):
        use = [[0] * H for _ in range(nres)]
        st = [0] * n
        mk = 0
        for v in order:
            t = rel[v]
            for p in preds[v]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[v]
            rq = req[v]
            if d > 0 and rq:
                while True:
                    ok = True
                    tau = t
                    end = t + d
                    while tau < end:
                        bad = False
                        for r, u in rq:
                            if use[r][tau] + u > cap[r]:
                                bad = True
                                break
                        if bad:
                            ok = False
                            break
                        tau += 1
                    if ok:
                        break
                    t = tau + 1
                for r, u in rq:
                    ur = use[r]
                    for tau in range(t, t + d):
                        ur[tau] += u
            st[v] = t
            if t + d > mk:
                mk = t + d
        return st, mk

    def topo_by_key(key):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, v = heapq.heappop(h)
            out.append(v)
            for w in succs[v]:
                indeg2[w] -= 1
                if indeg2[w] == 0:
                    heapq.heappush(h, (key[w], w))
        return out

    def backward_order(st, mk):
        fin = [st[v] + dur[v] for v in range(n)]
        rkey = [(-fin[v], -st[v], v) for v in range(n)]
        indeg2 = [len(succs[i]) for i in range(n)]
        h = [(rkey[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        rorder = []
        while h:
            _, v = heapq.heappop(h)
            rorder.append(v)
            for p in preds[v]:
                indeg2[p] -= 1
                if indeg2[p] == 0:
                    heapq.heappush(h, (rkey[p], p))
        use = [[0] * H for _ in range(nres)]
        rs = [0] * n
        for v in rorder:
            t = 0
            for w in succs[v]:
                f = rs[w] + dur[w]
                if f > t:
                    t = f
            d = dur[v]
            rq = req[v]
            if d > 0 and rq:
                while True:
                    ok = True
                    tau = t
                    end = t + d
                    while tau < end:
                        bad = False
                        for r, u in rq:
                            if use[r][tau] + u > cap[r]:
                                bad = True
                                break
                        if bad:
                            ok = False
                            break
                        tau += 1
                    if ok:
                        break
                    t = tau + 1
                for r, u in rq:
                    ur = use[r]
                    for tau in range(t, t + d):
                        ur[tau] += u
            rs[v] = t
        M = max(rs[v] + dur[v] for v in range(n))
        key = [(max(M - rs[v] - dur[v] + (mk - M), rel[v]), M - rs[v] - dur[v], v) for v in range(n)]
        return topo_by_key(key)

    best = [None, None, 10 ** 9]

    def consider(order):
        st, mk = decode(order)
        if mk < best[2]:
            best[0] = order
            best[1] = st
            best[2] = mk
        return st, mk

    def fb_improve(order):
        st, mk = consider(order)
        cur_mk = mk
        for _ in range(6):
            o2 = backward_order(st, mk)
            st2, mk2 = consider(o2)
            o3 = topo_by_key([(st2[v], v) for v in range(n)])
            st3, mk3 = consider(o3)
            if mk3 < cur_mk:
                cur_mk = mk3
                st, mk = st3, mk3
                order = o3
            else:
                if mk2 < cur_mk:
                    cur_mk = mk2
                    st, mk = st2, mk2
                    order = o2
                break
        return order, cur_mk

    rules = [
        [(lft[v], es[v], v) for v in range(n)],
        [(lst_[v], es[v], v) for v in range(n)],
        [(es[v], lft[v], v) for v in range(n)],
        [(-tail[v], es[v], v) for v in range(n)],
        [(-nsucc_tot[v], lft[v], v) for v in range(n)],
        [(max(rel[v], es[v]) - tail[v], v) for v in range(n)],
        [(-work[v] - tail[v], v) for v in range(n)],
        [(lft[v] - dur[v] * 0.5, v) for v in range(n)],
    ]
    for key in rules:
        fb_improve(topo_by_key(key))
        if best[2] <= LB:
            break
    rng = random.Random(12345)

    def elapsed():
        return time.perf_counter() - t0

    if best[2] > LB:
        span = max(1, cp)
        cur = list(best[0])
        cur_mk = best[2]
        stall = 0
        while elapsed() < budget and best[2] > LB:
            mode = rng.random()
            if mode < 0.25:
                base = rules[rng.randrange(len(rules))]
                noise = rng.random() * 0.6 * span + 0.5
                key = [(base[v][0] + rng.random() * noise, v) for v in range(n)]
                o, m = fb_improve(topo_by_key(key))
                if m <= cur_mk or stall > 60:
                    cur, cur_mk = o, m
                    stall = 0
            else:
                o = list(cur)
                k = 1 + (rng.random() < 0.4) + (rng.random() < 0.2)
                for _ in range(k):
                    i = rng.randrange(n)
                    v = o[i]
                    pos = {x: p for p, x in enumerate(o)}
                    lo = 0
                    for p in preds[v]:
                        if pos[p] + 1 > lo:
                            lo = pos[p] + 1
                    hi = n - 1
                    for w in succs[v]:
                        if pos[w] - 1 < hi:
                            hi = pos[w] - 1
                    if hi < lo:
                        continue
                    j = rng.randint(lo, hi)
                    del o[i]
                    o.insert(j, v)
                if mode < 0.45:
                    o2, m = fb_improve(o)
                else:
                    st, m = consider(o)
                    o2 = o
                if m <= cur_mk:
                    if m < cur_mk:
                        stall = 0
                    else:
                        stall += 1
                    cur, cur_mk = o2, m
                else:
                    stall += 1
                if stall > 300:
                    cur, cur_mk = list(best[0]), best[2]
                    stall = 0
    st = best[1]
    state["output"] = {"status": "ok", "start": {ids[v]: int(st[v]) for v in range(n)}}
    state["lb"] = LB
    return state

import time, random, heapq

def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    reason = None
    if len(idset) != len(ids):
        reason = "duplicate job id"
    for j in jobs:
        if reason: break
        for p in j.get("after") or []:
            if p not in idset:
                reason = "job %s references unknown job %s" % (j.get("id"), p); break
        if reason: break
        for r, u in (j.get("requires") or {}).items():
            if r not in res:
                reason = "job %s references unknown resource %s" % (j.get("id"), r); break
            if u > res[r]:
                reason = "job %s requires %s %s > capacity %s" % (j.get("id"), u, r, res[r]); break
    if not reason:
        idx = {i: k for k, i in enumerate(ids)}
        n = len(ids)
        indeg = [0]*n
        succ = [[] for _ in range(n)]
        for k, j in enumerate(jobs):
            for p in set(j.get("after") or []):
                succ[idx[p]].append(k); indeg[k] += 1
        q = [k for k in range(n) if indeg[k] == 0]
        seen = 0
        while q:
            k = q.pop(); seen += 1
            for s in succ[k]:
                indeg[s] -= 1
                if indeg[s] == 0: q.append(s)
        if seen < n:
            cyc = [ids[k] for k in range(n) if indeg[k] > 0]
            reason = "precedence cycle among " + ", ".join(cyc[:6])
    if reason:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["feasible"] = False
    else:
        state["feasible"] = True
    return state

def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 1.0
    inp = state["input"]
    res = inp["resources"]; jobs = inp["jobs"]
    rnames = list(res.keys()); cap = [int(res[r]) for r in rnames]
    rix = {r: i for i, r in enumerate(rnames)}
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    idx = {i: k for k, i in enumerate(ids)}
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    pred = [sorted(set(idx[p] for p in (j.get("after") or []))) for j in jobs]
    succ = [[] for _ in range(n)]
    for k in range(n):
        for p in pred[k]: succ[p].append(k)
    req = []
    for k, j in enumerate(jobs):
        rq = [(rix[r], int(u)) for r, u in (j.get("requires") or {}).items() if int(u) > 0]
        req.append(rq if dur[k] > 0 else [])
    indeg = [len(pred[k]) for k in range(n)]
    topo = []; q = [k for k in range(n) if indeg[k] == 0]
    while q:
        k = q.pop(); topo.append(k)
        for s in succ[k]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    head = [0]*n
    for k in topo:
        head[k] = max([rel[k]] + [head[p]+dur[p] for p in pred[k]])
    tail = [0]*n
    for k in reversed(topo):
        tail[k] = dur[k] + max([0] + [tail[s] for s in succ[k]])
    LB = max([head[k]+tail[k] for k in range(n)] + [0])
    for ri in range(len(cap)):
        js = [k for k in range(n) if any(r == ri for r, u in req[k])]
        if js and cap[ri] > 0:
            e = sum(u*dur[k] for k in js for r, u in req[k] if r == ri)
            mh = min(head[k] for k in js); mt = min(tail[k]-dur[k] for k in js)
            LB = max(LB, mh + (e + cap[ri]-1)//cap[ri] + mt)
    H = max(rel + [0]) + sum(dur) + 2
    R = len(cap)

    def sgs(order):
        use = [[0]*H for _ in range(R)]
        st = [0]*n
        for k in order:
            t = rel[k]
            for p in pred[k]:
                f = st[p]+dur[p]
                if f > t: t = f
            d = dur[k]; rq = req[k]
            if rq:
                while True:
                    bad = -1
                    for tt in range(t, t+d):
                        for r, u in rq:
                            if use[r][tt]+u > cap[r]:
                                bad = tt; break
                        if bad >= 0: break
                    if bad < 0: break
                    t = bad+1
                for r, u in rq:
                    ur = use[r]
                    for tt in range(t, t+d): ur[tt] += u
            st[k] = t
        return st

    def backward(st, M):
        order = sorted(range(n), key=lambda k: -(st[k]+dur[k]))
        use = [[0]*H for _ in range(R)]
        ns = [0]*n
        for k in order:
            f = M
            for s in succ[k]:
                if ns[s] < f: f = ns[s]
            d = dur[k]; rq = req[k]
            if rq:
                while True:
                    bad = -1
                    for tt in range(f-1, f-d-1, -1):
                        for r, u in rq:
                            if use[r][tt]+u > cap[r]:
                                bad = tt; break
                        if bad >= 0: break
                    if bad < 0: break
                    f = bad
                for r, u in rq:
                    ur = use[r]
                    for tt in range(f-d, f): ur[tt] += u
            ns[k] = f-d
        return ns

    def mk(st):
        return max([st[k]+dur[k] for k in range(n)] + [0])

    def evaluate(order):
        st = sgs(order); m = mk(st)
        for _ in range(3):
            bs = backward(st, m)
            if any(bs[k] < rel[k] for k in range(n)):
                break
            o2 = sorted(range(n), key=lambda k: (bs[k], -dur[k]))
            st2 = sgs(o2); m2 = mk(st2)
            if m2 < m:
                st, m = st2, m2
            else:
                if m2 == m: st = st2
                break
        return st, m

    def list_from_keys(key):
        ind = [len(pred[k]) for k in range(n)]
        h = [(key[k], k) for k in range(n) if ind[k] == 0]
        heapq.heapify(h); out = []
        while h:
            _, k = heapq.heappop(h); out.append(k)
            for s in succ[k]:
                ind[s] -= 1
                if ind[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    best_st = None; best_m = None
    def consider(st, m):
        nonlocal best_st, best_m
        if best_m is None or m < best_m:
            best_st, best_m = st[:], m
    nsucc = [len(set(succ[k])) for k in range(n)]
    work = [dur[k]*sum(u/max(1, cap[r]) for r, u in req[k]) for k in range(n)]
    rules = [
        [-tail[k] for k in range(n)],
        [head[k] - tail[k] for k in range(n)],
        [-(head[k]+tail[k])*1000 + head[k] for k in range(n)],
        [head[k] for k in range(n)],
        [-nsucc[k] for k in range(n)],
        [-work[k] for k in range(n)],
        [-tail[k]*100 - work[k] for k in range(n)],
    ]
    for key in rules:
        st, m = evaluate(list_from_keys(key)); consider(st, m)
        if best_m <= LB: break
    def order_of(st):
        return sorted(range(n), key=lambda k: (st[k], -dur[k]))
    cur_order = order_of(best_st); cur_m = best_m
    it = 0; stall = 0
    while best_m > LB and time.perf_counter() - T0 < BUDGET and n > 1:
        it += 1
        if stall > 60 or it % 7 == 0:
            a = rng.random()*0.6
            key = [(head[k]-tail[k]) * (1 + a*(rng.random()-0.5)) + rng.random()*a*3 for k in range(n)]
            o = list_from_keys(key)
            st, m = evaluate(o)
            consider(st, m)
            if stall > 60:
                cur_order, cur_m = order_of(st), m; stall = 0
            continue
        o = cur_order[:]
        for _ in range(1 + rng.randrange(2)):
            pos = {k: i for i, k in enumerate(o)}
            k = o[rng.randrange(n)]
            lo = max([pos[p] for p in pred[k]] + [-1]) + 1
            hi = min([pos[s] for s in succ[k]] + [n])
            i = pos[k]
            o.pop(i)
            if hi > i: hi -= 1
            j = rng.randint(lo, hi)
            o.insert(j, k)
        st, m = evaluate(o)
        consider(st, m)
        if m <= cur_m:
            if m < cur_m: stall = 0
            else: stall += 1
            cur_order, cur_m = order_of(st), m
        else:
            stall += 1
    state["output"] = {"status": "ok", "start": {ids[k]: int(best_st[k]) for k in range(n)}}
    state["lb"] = LB; state["iters"] = it
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def check(start, dur, rel, preds, req, cap, n):
    if start is None:
        return False
    use = {}
    for j in range(n):
        if start[j] < rel[j]:
            return False
        for p in preds[j]:
            if start[j] < start[p] + dur[p]:
                return False
        for (r, u) in req[j]:
            for t in range(start[j], start[j] + dur[j]):
                k = (r, t)
                use[k] = use.get(k, 0) + u
                if use[k] > cap[r]:
                    return False
    return True


def solve(state, params):
    t_begin = time.perf_counter()
    budget = 0.85
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = []
    for r in rnames:
        try:
            cap.append(int(res[r]))
        except Exception:
            cap.append(0)
    R = len(rnames)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, x in enumerate(ids):
        jidx[x] = i
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    dur = []
    rel = []
    preds = []
    req = []
    for i, j in enumerate(jobs):
        dur.append(max(0, int(j.get("duration") or 0)))
        rel.append(max(0, int(j.get("release") or 0)))
        ps = []
        for a in (j.get("after") or []):
            a = str(a)
            if a not in jidx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], a))
            p = jidx[a]
            if p not in ps:
                ps.append(p)
        preds.append(ps)
        rq = []
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > cap[ridx[r]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, r, cap[ridx[r]]))
            if u > 0:
                rq.append((ridx[r], u))
        req.append(rq)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        left = [ids[i] for i in range(n) if indeg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(left[:6]))
    trank = [0] * n
    for k, x in enumerate(topo):
        trank[x] = k
    es = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[x] = t
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = max(es[i] + tail[i] for i in range(n))
    hs = sorted(set(es))
    for r in range(R):
        if cap[r] <= 0:
            continue
        for h in hs:
            e = 0
            for i in range(n):
                if es[i] >= h:
                    for (rr, u) in req[i]:
                        if rr == r:
                            e += u * dur[i]
            if e > 0:
                v = h + (e + cap[r] - 1) // cap[r]
                if v > LB:
                    LB = v
    H = max(rel) + sum(dur) + 30
    work = [sum(u * dur[i] / max(1, cap[r]) for (r, u) in req[i]) for i in range(n)]
    nsucc_tot = [0] * n
    desc = [set() for _ in range(n)]
    for x in reversed(topo):
        for s in succs[x]:
            desc[x].add(s)
            desc[x] |= desc[s]
        nsucc_tot[x] = len(desc[x])

    def decode(order):
        prof = [[0] * H for _ in range(R)]
        start = [0] * n
        mk = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = start[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    ok = True
                    for (r, u) in rq:
                        lim = cap[r] - u
                        pr = prof[r]
                        for x in range(t, t + d):
                            if pr[x] > lim:
                                ok = False
                                t = x + 1
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, u) in rq:
                    pr = prof[r]
                    for x in range(t, t + d):
                        pr[x] += u
            start[j] = t
            if t + d > mk:
                mk = t + d
        return start, mk

    def right_justify(start, M):
        st = list(start)
        prof = [[0] * H for _ in range(R)]
        for j in range(n):
            for (r, u) in req[j]:
                pr = prof[r]
                for x in range(st[j], st[j] + dur[j]):
                    pr[x] += u
        order = sorted(range(n), key=lambda j: (st[j] + dur[j], trank[j]), reverse=True)
        for j in order:
            lim = M
            for s in succs[j]:
                if st[s] < lim:
                    lim = st[s]
            d = dur[j]
            latest = lim - d
            if latest <= st[j]:
                continue
            rq = req[j]
            if d == 0 or not rq:
                st[j] = latest
                continue
            for (r, u) in rq:
                pr = prof[r]
                for x in range(st[j], st[j] + d):
                    pr[x] -= u
            t = latest
            while t > st[j]:
                ok = True
                for (r, u) in rq:
                    lm = cap[r] - u
                    pr = prof[r]
                    for x in range(t + d - 1, t - 1, -1):
                        if pr[x] > lm:
                            ok = False
                            t = x - d
                            break
                    if not ok:
                        break
                if ok:
                    break
            if t < st[j]:
                t = st[j]
            st[j] = t
            for (r, u) in rq:
                pr = prof[r]
                for x in range(t, t + d):
                    pr[x] += u
        return st

    def canon(start):
        return sorted(range(n), key=lambda j: (start[j], trank[j]))

    def evaluate(order):
        s, M = decode(order)
        o = canon(s)
        for _k in range(3):
            rs = right_justify(s, M)
            o2 = canon(rs)
            s2, M2 = decode(o2)
            if M2 < M:
                s, M, o = s2, M2, canon(s2)
            else:
                if M2 == M:
                    s, o = s2, canon(s2)
                break
        return o, s, M

    def gen_list(pri, noise):
        keys = [pri[i] + (random.random() * noise if noise else 0.0) for i in range(n)]
        deg = [len(preds[i]) for i in range(n)]
        h = [(-keys[i], trank[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _a, _b, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (-keys[s], trank[s], s))
        return out

    random.seed(12345 + n)
    pris = [
        [float(tail[i]) for i in range(n)],
        [float(-es[i]) for i in range(n)],
        [float(tail[i] - es[i]) for i in range(n)],
        [float(tail[i]) + 0.5 * work[i] for i in range(n)],
        [float(nsucc_tot[i]) + 0.01 * tail[i] for i in range(n)],
        [float(tail[i] + dur[i]) for i in range(n)],
    ]
    best_s, best_M, best_o = None, None, None
    for pr in pris:
        o, s, M = evaluate(gen_list(pr, 0.0))
        if best_M is None or M < best_M:
            best_s, best_M, best_o = s, M, o
        if best_M <= LB:
            break

    def mutate(order):
        L = list(order)
        k = random.randint(1, 3)
        for _k in range(k):
            i = random.randrange(n)
            j = L.pop(i)
            lo = 0
            hi = len(L)
            pset = preds[j]
            sset = succs[j]
            if pset or sset:
                for idx in range(len(L)):
                    y = L[idx]
                    if y in pset:
                        if idx + 1 > lo:
                            lo = idx + 1
                    elif y in sset:
                        if idx < hi:
                            hi = idx
            if hi < lo:
                hi = lo
            L.insert(random.randint(lo, hi), j)
        return L

    cur_o, cur_M = best_o, best_M
    stall = 0
    it = 0
    span = max(1.0, float(max(tail)))
    while best_M > LB and n > 1:
        it += 1
        if (it & 3) == 0 and time.perf_counter() - t_begin > budget:
            break
        if stall > 150:
            stall = 0
            if random.random() < 0.5:
                cur_o, cur_M = best_o, best_M
            else:
                pr = pris[random.randrange(len(pris))]
                o, s, M = evaluate(gen_list(pr, span * random.uniform(0.1, 0.8)))
                cur_o, cur_M = o, M
                if M < best_M:
                    best_s, best_M, best_o = s, M, o
            continue
        o, s, M = evaluate(mutate(cur_o))
        if M < best_M:
            best_s, best_M, best_o = s, M, o
            stall = 0
        else:
            stall += 1
        if M <= cur_M or random.random() < 0.03:
            cur_o, cur_M = o, M

    start = best_s
    if not check(start, dur, rel, preds, req, cap, n):
        start = [0] * n
        t = 0
        for x in topo:
            t = max(t, rel[x])
            start[x] = t
            t += dur[x]
    out = {}
    for i in range(n):
        out[ids[i]] = int(start[i])
    state["output"] = {"status": "ok", "start": out}
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t_start = time.perf_counter()
    budget = 1.05
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, jid in enumerate(ids):
        idx[jid] = i
    n = len(jobs)
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    caps = [int(resources[r]) for r in rnames]

    dur = [0] * n
    rel = [0] * n
    preds = [[] for _ in range(n)]
    req = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        dur[i] = max(0, int(j.get("duration", 0) or 0))
        rel[i] = max(0, int(j.get("release", 0) or 0))
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            pi = idx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s requires unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > caps[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s, capacity %d" % (ids[i], u, r, caps[ridx[r]]))
            if u > 0:
                req[i].append((ridx[r], u))

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if deg[i] > 0]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc[:6]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    tpos = [0] * n
    for k, x in enumerate(topo):
        tpos[x] = k

    # heads / tails
    es = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            f = es[p] + dur[p]
            if f > t:
                t = f
        es[x] = t
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = max(es[i] + tail[i] for i in range(n))
    R = len(caps)
    for r in range(R):
        rels = sorted(set(es[i] for i in range(n)))
        for r0 in rels:
            w = 0
            for i in range(n):
                if es[i] >= r0:
                    for (rr, u) in req[i]:
                        if rr == r:
                            w += u * dur[i]
            if w > 0 and caps[r] > 0:
                b = r0 + (w + caps[r] - 1) // caps[r]
                if b > LB:
                    LB = b
    work = [sum(u * dur[i] / float(max(1, caps[r])) for (r, u) in req[i]) for i in range(n)]

    H = max(rel) + sum(dur) + 20
    lims = [[(r, caps[r] - u) for (r, u) in req[i]] for i in range(n)]

    def ssgs(order):
        usage = [[0] * H for _ in range(R)]
        S = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = S[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            lm = lims[j]
            if d > 0 and lm:
                while True:
                    bad = -1
                    for tt in range(t, t + d):
                        for (r, lim) in lm:
                            if usage[r][tt] > lim:
                                bad = tt
                                break
                        if bad >= 0:
                            break
                    if bad < 0:
                        break
                    t = bad + 1
                for (r, u) in req[j]:
                    ur = usage[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
            S[j] = t
        return S

    def mksp(S):
        return max(S[i] + dur[i] for i in range(n))

    def right_just(S, M):
        order = sorted(range(n), key=lambda j: (-(S[j] + dur[j]), -tpos[j]))
        usage = [[0] * (H + M + 5) for _ in range(R)]
        NS = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if NS[s] < lf:
                    lf = NS[s]
            d = dur[j]
            t = lf - d
            lm = lims[j]
            if d > 0 and lm:
                while t >= S[j]:
                    bad = -1
                    for tt in range(t + d - 1, t - 1, -1):
                        for (r, lim) in lm:
                            if usage[r][tt] > lim:
                                bad = tt
                                break
                        if bad >= 0:
                            break
                    if bad < 0:
                        break
                    t = bad - d
                if t < S[j]:
                    return None
                for (r, u) in req[j]:
                    ur = usage[r]
                    for tt in range(t, t + d):
                        ur[tt] += u
            else:
                if t < S[j]:
                    return None
            NS[j] = t
        return NS

    def order_by_start(S):
        return sorted(range(n), key=lambda j: (S[j], tpos[j]))

    def double_just(S):
        M = mksp(S)
        for _ in range(6):
            RS = right_just(S, M)
            if RS is None:
                break
            L = ssgs(order_by_start(RS))
            m2 = mksp(L)
            if m2 < M:
                S, M = L, m2
            else:
                if m2 == M:
                    S = L
                break
        return S, M

    def valid(S):
        for i in range(n):
            if not isinstance(S[i], int) or S[i] < rel[i]:
                return False
            for p in preds[i]:
                if S[i] < S[p] + dur[p]:
                    return False
        M = mksp(S)
        usage = [[0] * (M + 2) for _ in range(R)]
        for i in range(n):
            for (r, u) in req[i]:
                for tt in range(S[i], S[i] + dur[i]):
                    usage[r][tt] += u
        for r in range(R):
            if max(usage[r]) > caps[r]:
                return False
        return True

    rng = random.Random(12345)
    succ_count = [0] * n
    for x in reversed(topo):
        seen = set()
        stack = list(succs[x])
        while stack:
            y = stack.pop()
            if y not in seen:
                seen.add(y)
                stack.extend(succs[y])
        succ_count[x] = len(seen)

    rules = [
        lambda j: (-tail[j], es[j]),
        lambda j: (es[j], -tail[j]),
        lambda j: (es[j] - tail[j], -work[j]),
        lambda j: (-succ_count[j], -tail[j]),
        lambda j: (-(tail[j] + work[j]), es[j]),
        lambda j: (-dur[j], -tail[j]),
    ]

    def build_list(keyf, noise):
        d = indeg[:]
        elig = [i for i in range(n) if d[i] == 0]
        out = []
        while elig:
            elig.sort(key=keyf)
            if noise > 0:
                k = 0
                while k < len(elig) - 1 and rng.random() < noise:
                    k += 1
            else:
                k = 0
            x = elig.pop(k)
            out.append(x)
            for s in succs[x]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    def time_left():
        return budget - (time.perf_counter() - t_start)

    best_S = None
    best_M = None

    def consider(S):
        nonlocal best_S, best_M
        S2, M2 = double_just(S)
        if best_M is None or M2 < best_M:
            best_S, best_M = S2, M2
        return S2, M2

    for rf in rules:
        consider(ssgs(build_list(rf, 0.0)))
        if best_M <= LB or time_left() < 0.5:
            break

    # random sampling phase
    phase1_end = budget * 0.35
    it = 0
    while best_M > LB and (time.perf_counter() - t_start) < phase1_end:
        rf = rules[it % len(rules)]
        it += 1
        lst = build_list(rf, 0.3 + 0.4 * rng.random())
        S = ssgs(lst)
        M = mksp(S)
        if M <= best_M + 1:
            consider(S)
        if time_left() < 0.05:
            break

    # local search on activity lists
    cur = order_by_start(best_S)
    cur_M = best_M
    stall = 0
    while best_M > LB and time_left() > 0.02:
        lst = cur[:]
        nm = 1 if rng.random() < 0.7 else rng.randint(2, 3)
        for _ in range(nm):
            i = rng.randrange(n)
            j = lst.pop(i)
            pos = {x: k for k, x in enumerate(lst)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(lst)
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            lst.insert(rng.randint(lo, hi), j)
        S = ssgs(lst)
        M = mksp(S)
        if M < cur_M:
            S2, M2 = consider(S)
            cur = order_by_start(S2)
            cur_M = M2
            stall = 0
        elif M == cur_M:
            cur = lst
            stall += 1
        else:
            stall += 1
        if stall > 300:
            stall = 0
            if rng.random() < 0.5:
                cur = order_by_start(best_S)
                cur_M = best_M
            else:
                lst = build_list(rules[rng.randrange(len(rules))], 0.5)
                S2, M2 = consider(ssgs(lst))
                cur = order_by_start(S2)
                cur_M = M2

    if best_S is None or not valid(best_S):
        # guaranteed-valid sequential fallback
        S = [0] * n
        t = 0
        for x in topo:
            t = max(t, rel[x])
            S[x] = t
            t += dur[x]
        best_S = S

    state["output"] = {"status": "ok", "start": {ids[i]: int(best_S[i]) for i in range(n)}}
    return state

