        h = rel[x]
        for p in preds[x]:
            v = head[p] + dur[p]
            if v > h:
                h = v
        head[x] = h
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = max(head[i] + tail[i] for i in range(n))
    for r in range(nr):
        users = [i for i in range(n) if any(rr == r for rr, _ in req[i])]
        if users and cap[r] > 0:
            energy = 0
            for i in users:
                for rr, u in req[i]:
                    if rr == r:
                        energy += u * dur[i]
            mr = min(head[i] for i in users)
            mt = min(tail[i] - dur[i] for i in users)
            lb = mr + (energy + cap[r] - 1) // cap[r] + mt
            if lb > LB:
                LB = lb

    H = max(rel) + sum(dur) + max(head) + 5

    def forward(order):
        usage = [[0] * H for _ in range(nr)]
        start = [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                v = start[p] + dur[p]
                if v > est:
                    est = v
            d = dur[j]
            rq = req[j]
            if d == 0 or not rq:
                start[j] = est
                continue
            t = est
            while True:
                ok = True
                tt = t
                end = t + d
                while tt < end:
                    bad = False
                    for r, u in rq:
                        if usage[r][tt] + u > cap[r]:
                            bad = True
                            break
                    if bad:
                        ok = False
                        t = tt + 1
                        break
                    tt += 1
                if ok:
                    break
            start[j] = t
            for r, u in rq:
                ur = usage[r]
                for tt in range(t, t + d):
                    ur[tt] += u
        return start

    def makespan(start):
        return max(start[i] + dur[i] for i in range(n))

    def backward(start):
        T = makespan(start)
        order = sorted(range(n), key=lambda i: (-(start[i] + dur[i]), -tpos[i]))
        usage = [[0] * (T + 2) for _ in range(nr)]
        ns = [0] * n
        for j in order:
            lf = T
            for s in succs[j]:
                if ns[s] < lf:
                    lf = ns[s]
            d = dur[j]
            rq = req[j]
            if d == 0 or not rq:
                st = lf - d
                if st < rel[j]:
                    return None
                ns[j] = st
                continue
            t = lf - d
            while True:
                if t < rel[j]:
                    return None
                ok = True
                tt = t + d - 1
                while tt >= t:
                    bad = False
                    for r, u in rq:
                        if usage[r][tt] + u > cap[r]:
                            bad = True
                            break
                    if bad:
                        ok = False
                        t = tt - d
                        break
                    tt -= 1
                if ok:
                    break
            ns[j] = t
            for r, u in rq:
                ur = usage[r]
                for tt in range(t, t + d):
                    ur[tt] += u
        return ns

    def order_from(start):
        return sorted(range(n), key=lambda i: (start[i], tpos[i]))

    def improve(start):
        ms = makespan(start)
        for _ in range(20):
            b = backward(start)
            if b is None:
                break
            f = forward(order_from(b))
            fm = makespan(f)
            if fm < ms:
                start, ms = f, fm
            else:
                break
        return start, ms

    def list_from_keys(key):
        # key: larger = earlier; precedence-feasible
        deg = [len(preds[i]) for i in range(n)]
        h = [(-key[i], tpos[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (-key[s], tpos[s], s))
        return out

    nsucc = [0] * n
    for x in reversed(topo):
        seen = set()
        stack = list(succs[x])
        while stack:
            y = stack.pop()
            if y in seen:
                continue
            seen.add(y)
            stack.extend(succs[y])
        nsucc[x] = len(seen)
    load = [sum(u / float(cap[r]) for r, u in req[i]) * dur[i] for i in range(n)]

    rules = [
        [tail[i] for i in range(n)],
        [tail[i] - 0.5 * head[i] for i in range(n)],
        [-(head[i]) * 1000 + tail[i] for i in range(n)],
        [nsucc[i] * 100 + tail[i] for i in range(n)],
        [tail[i] * 10 + load[i] for i in range(n)],
        [-(LB - tail[i]) for i in range(n)],
    ]

    best = None
    best_ms = None

    def consider(st):
        nonlocal best, best_ms
        st, ms = improve(st)
        if best is None or ms < best_ms:
            best, best_ms = st, ms

    for key in rules:
        consider(forward(list_from_keys(key)))
        if best_ms <= LB or time.perf_counter() - t0 > budget:
            break

    rng = random.Random(12345)
    it = 0
    while best_ms > LB and time.perf_counter() - t0 < budget:
        it += 1
        mode = it % 3
        if mode == 0 and best is not None:
            noise = 1 + rng.random() * 4
            key = [-(best[i] + rng.uniform(-noise, noise)) for i in range(n)]
        elif mode == 1:
            a = rng.uniform(0.05, 0.5)
            key = [tail[i] * (1 + rng.uniform(-a, a)) - rng.random() * 0.3 * head[i] for i in range(n)]
        else:
            key = [rng.random() * (tail[i] + 1) + rng.random() * load[i] for i in range(n)]
        consider(forward(list_from_keys(key)))

    state["output"] = {"status": "ok", "start": {ids[i]: int(best[i]) for i in range(n)}}
    return state

import time
import random
import heapq


def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 0.95
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    def fail(msg):
        state["output"] = {"status": "infeasible", "reason": str(msg)[:200]}
        return state

    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    caps = []
    for r in rnames:
        try:
            caps.append(int(resources[r]))
        except Exception:
            caps.append(0)
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, x in enumerate(ids):
        if x not in idx:
            idx[x] = i

    dur, rel, preds, reqs = [], [], [], []
    for i, j in enumerate(jobs):
        d = int(j.get("duration") or 0)
        r = int(j.get("release") or 0)
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return fail("job %s references unknown job %s" % (ids[i], p))
            q = idx[p]
            if q not in pl:
                pl.append(q)
        rq = []
        for rn, u in (j.get("requires") or {}).items():
            if rn not in ridx:
                return fail("job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            k = ridx[rn]
            if u > caps[k]:
                return fail("job %s requires %d of %s but capacity is %d" % (ids[i], u, rn, caps[k]))
            if u > 0:
                rq.append((k, u))
        dur.append(max(0, d))
        rel.append(max(0, r))
        preds.append(pl)
        reqs.append(rq)

    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)

    # cycle detection (Kahn)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    h = 0
    while h < len(q):
        x = q[h]
        h += 1
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        bad = [ids[i] for i in range(n) if indeg[i] > 0]
        return fail("precedence cycle involving " + ", ".join(bad[:6]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for pos, x in enumerate(topo):
        rank[x] = pos

    # heads / tails
    es0 = [0] * n
    for x in topo:
        t = rel[x]
        for p in preds[x]:
            f = es0[p] + dur[p]
            if f > t:
                t = f
        es0[x] = t
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dur[x] + m
    LB = 0
    for i in range(n):
        if es0[i] + tail[i] > LB:
            LB = es0[i] + tail[i]
    for k in range(len(caps)):
        if caps[k] <= 0:
            continue
        work = 0
        r0 = None
        for i in range(n):
            if dur[i] > 0:
                for kk, u in reqs[i]:
                    if kk == k:
                        work += u * dur[i]
                        if r0 is None or es0[i] < r0:
                            r0 = es0[i]
        if work > 0:
            b = r0 + (work + caps[k] - 1) // caps[k]
            if b > LB:
                LB = b

    H = max(rel) + sum(dur) + 2
    SZ = H + 20
    R = len(caps)

    def sgs(order):
        free = [[c] * SZ for c in caps]
        st = [0] * n
        ms = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = reqs[j]
            if d > 0 and rq:
                while True:
                    moved = False
                    for k, u in rq:
                        fk = free[k]
                        tt = t + d - 1
                        while tt >= t:
                            if fk[tt] < u:
                                break
                            tt -= 1
                        if tt >= t:
                            t = tt + 1
                            moved = True
                            break
                    if not moved:
                        break
                for k, u in rq:
                    fk = free[k]
                    for tt in range(t, t + d):
                        fk[tt] -= u
            st[j] = t
            if t + d > ms:
                ms = t + d
        return st, ms

    def makespan(st):
        m = 0
        for i in range(n):
            if st[i] + dur[i] > m:
                m = st[i] + dur[i]
        return m

    def justify(st0):
        st = list(st0)
        M = makespan(st)
        while True:
            free = [[c] * SZ for c in caps]
            for i in range(n):
                d = dur[i]
                if d > 0:
                    for k, u in reqs[i]:
                        fk = free[k]
                        for tt in range(st[i], st[i] + d):
                            fk[tt] -= u
            # backward (right) shift
            order = sorted(range(n), key=lambda i: (-(st[i] + dur[i]), -rank[i]))
            for j in order:
                d = dur[j]
                LF = M
                for s in succs[j]:
                    if st[s] < LF:
                        LF = st[s]
                cur = st[j]
                rq = reqs[j]
                if d == 0 or not rq:
                    if LF - d > cur:
                        st[j] = LF - d
                    continue
                for k, u in rq:
                    fk = free[k]
                    for tt in range(cur, cur + d):
                        fk[tt] += u
                t = LF - d
                while t > cur:
                    moved = False
                    for k, u in rq:
                        fk = free[k]
                        tt = t
                        e = t + d
                        while tt < e:
                            if fk[tt] < u:
                                break
                            tt += 1
                        if tt < e:
                            t = tt - d
                            moved = True
                            break
                    if not moved:
                        break
                if t < cur:
                    t = cur
                for k, u in rq:
                    fk = free[k]
                    for tt in range(t, t + d):
                        fk[tt] -= u
                st[j] = t
            # forward (left) shift
            order = sorted(range(n), key=lambda i: (st[i], rank[i]))
            for j in order:
                d = dur[j]
                es = rel[j]
                for p in preds[j]:
                    f = st[p] + dur[p]
                    if f > es:
                        es = f
                cur = st[j]
                rq = reqs[j]
                if d == 0 or not rq:
                    if es < cur:
                        st[j] = es
                    continue
                for k, u in rq:
                    fk = free[k]
                    for tt in range(cur, cur + d):
                        fk[tt] += u
                t = es
                while t < cur:
                    moved = False
                    for k, u in rq:
                        fk = free[k]
                        tt = t + d - 1
                        while tt >= t:
                            if fk[tt] < u:
                                break
                            tt -= 1
                        if tt >= t:
                            t = tt + 1
                            moved = True
                            break
                    if not moved:
                        break
                if t > cur:
                    t = cur
                for k, u in rq:
                    fk = free[k]
                    for tt in range(t, t + d):
                        fk[tt] -= u
                st[j] = t
            M2 = makespan(st)
            if M2 >= M:
                return st, M2
            M = M2

    def order_of(st):
        return sorted(range(n), key=lambda i: (st[i], rank[i]))

    def build_list(keys):
        indeg2 = [len(preds[i]) for i in range(n)]
        hp = [(keys[i], rank[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, _, x = heapq.heappop(hp)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(hp, (keys[s], rank[s], s))
        return out

    # priority rules
    avgd = max(1.0, sum(dur) / float(n))
    nsucc_tot = [0] * n
    reach = [set() for _ in range(n)]
    for x in reversed(topo):
        sx = set()
        for s in succs[x]:
            sx.add(s)
            sx |= reach[s]
        reach[x] = sx
        nsucc_tot[x] = len(sx)
    rload = [0.0] * n
    for i in range(n):
        v = 0.0
        for k, u in reqs[i]:
            if caps[k] > 0:
                v += float(u) / caps[k]
        rload[i] = v * dur[i]
    wtail = [0.0] * n
    for x in reversed(topo):
        m = 0.0
        for s in succs[x]:
            if wtail[s] > m:
                m = wtail[s]
        wtail[x] = dur[x] + 0.5 * rload[x] + m
    rules = [
        [-float(tail[i]) for i in range(n)],
        [float(es0[i]) - 0.01 * tail[i] for i in range(n)],
        [-float(nsucc_tot[i]) * avgd - 0.01 * tail[i] for i in range(n)],
        [-wtail[i] for i in range(n)],
        [float(es0[i]) - float(tail[i]) for i in range(n)],
    ]
    scale = max(1.0, float(LB))

    rng = random.Random(12345)
    best_st = None
    best_ms = None
    elite = []  # list of (ms, order)

    def add_elite(ms, order):
        elite.append((ms, order))
        elite.sort(key=lambda e: e[0])
        while len(elite) > 8:
            elite.pop()

    def consider(st, ms):
        nonlocal best_st, best_ms
        if best_ms is None or ms < best_ms:
            best_st = list(st)
            best_ms = ms
            return True
        return False

    for keys in rules:
        o = build_list(keys)
        st, ms = sgs(o)
        st2, ms2 = justify(st)
        if ms2 < ms:
            st, ms = st2, ms2
        consider(st, ms)
        add_elite(ms, order_of(st))
        if best_ms <= LB:
            break

    def elapsed():
        return time.perf_counter() - T0

    # Phase 1: biased random sampling
    p1 = BUDGET * 0.35
    while best_ms > LB and elapsed() < p1:
        base = rules[rng.randrange(len(rules))]
        amp = scale * rng.choice([0.05, 0.1, 0.2, 0.35, 0.6])
        keys = [base[i] + amp * rng.random() for i in range(n)]
        o = build_list(keys)
        st, ms = sgs(o)
        if ms <= best_ms * 1.1 + 1:
            st2, ms2 = justify(st)
            if ms2 < ms:
                st, ms = st2, ms2
            add_elite(ms, order_of(st))
        consider(st, ms)

    # Phase 2: local search on activity lists
    def mutate(order):
        o = list(order)
        pos_j = rng.randrange(n)
        j = o.pop(pos_j)
        pos = {x: i for i, x in enumerate(o)}
        lo = 0
        for p in preds[j]:
            if pos[p] + 1 > lo:
                lo = pos[p] + 1
        hi = n - 1
        for s in succs[j]:
            if pos[s] < hi:
                hi = pos[s]
        if hi < lo:
            hi = lo
        o.insert(rng.randint(lo, hi), j)
        return o

    if elite:
        cur_ms, cur_order = elite[0]
    else:
        cur_order = order_of(best_st)
        cur_ms = best_ms
    stall = 0
    while best_ms > LB and elapsed() < BUDGET:
        nm = 1 if rng.random() < 0.7 else rng.randint(2, 4)
        o = cur_order
        for _ in range(nm):
            o = mutate(o)
        st, ms = sgs(o)
        if ms <= cur_ms + (1 if rng.random() < 0.05 else 0):
            if ms <= best_ms:
                st2, ms2 = justify(st)
                if ms2 < ms:
                    st, ms = st2, ms2
                    o = order_of(st)
            if ms < cur_ms:
                stall = 0
            else:
                stall += 1
            cur_order, cur_ms = o, ms
            if consider(st, ms):
                add_elite(ms, o)
                stall = 0
        else:
            stall += 1
        if stall > 150 + 5 * n:
            stall = 0
            if rng.random() < 0.5 and elite:
                cur_ms, cur_order = elite[rng.randrange(len(elite))]
            else:
                base = rules[rng.randrange(len(rules))]
                amp = scale * rng.choice([0.1, 0.2, 0.4])
                keys = [base[i] + amp * rng.random() for i in range(n)]
                cur_order = build_list(keys)
                st, cur_ms = sgs(cur_order)
                consider(st, cur_ms)

    # verification
    def valid(st):
        M = 0
        for i in range(n):
            if not isinstance(st[i], int) or st[i] < rel[i]:
                return False
            for p in preds[i]:
                if st[i] < st[p] + dur[p]:
                    return False
            if st[i] + dur[i] > M:
                M = st[i] + dur[i]
        use = [[0] * (M + 1) for _ in range(R)]
        for i in range(n):
            if dur[i] > 0:
                for k, u in reqs[i]:
                    uk = use[k]
                    for tt in range(st[i], st[i] + dur[i]):
                        uk[tt] += u
                        if uk[tt] > caps[k]:
                            return False
        return True

    final = best_st
    if final is None or not valid(final):
        final = [0] * n
        cursor = 0
        for x in topo:
            s = max(rel[x], cursor)
            for p in preds[x]:
                f = final[p] + dur[p]
                if f > s:
                    s = f
            final[x] = s
            cursor = s + dur[x]

    state["output"] = {"status": "ok", "start": {ids[i]: int(final[i]) for i in range(n)}}
    return state

import time
import random
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _sgs(order, n, dur, rel, preds, req, cap, H):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    start = [0] * n
    ms = 0
    for j in order:
        t = rel[j]
        for p in preds[j]:
            f = start[p] + dur[p]
            if f > t:
                t = f
        d = dur[j]
        rq = req[j]
        if d > 0 and rq:
            while True:
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t, t + d):
                        if ur[s] > lim:
                            t = s + 1
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        start[j] = t
        if t + d > ms:
            ms = t + d
    return start, ms


def _bwd(start, ms, n, dur, rel, succs, req, cap, H, rank):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
    bs = [0] * n
    for j in order:
        lf = ms
        for s in succs[j]:
            if bs[s] < lf:
                lf = bs[s]
        d = dur[j]
        t = lf - d
        rq = req[j]
        if d > 0 and rq:
            while True:
                if t < 0:
                    return None
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t + d - 1, t - 1, -1):
                        if ur[s] > lim:
                            t = s - d
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        if t < 0:
            return None
        bs[j] = t
    return bs


def _validate(starts, n, dur, rel, preds, req, cap):
    if len(starts) != n:
        return False
    for j in range(n):
        if starts[j] < rel[j]:
            return False
        for p in preds[j]:
            if starts[j] < starts[p] + dur[p]:
                return False
    events = {}
    for j in range(n):
        if dur[j] > 0:
            for t in range(starts[j], starts[j] + dur[j]):
                lst = events.get(t)
                if lst is None:
                    lst = [0] * len(cap)
                    events[t] = lst
                for r, u in req[j]:
                    lst[r] += u
    for t in events:
        lst = events[t]
        for r in range(len(cap)):
            if lst[r] > cap[r]:
                return False
    return True


def solve(state, params):
    t0 = time.perf_counter()
    budget = 0.9
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]

    n = len(jobs)
    ids = [str(jb.get("id")) for jb in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i

    dur = []
    rel = []
    preds = []
    req = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        pl = []
        seen = set()
        for p in (jb.get("after") or []):
            ps = str(p)
            if ps not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], ps))
            pi = idx[ps]
            if pi not in seen:
                seen.add(pi)
                pl.append(pi)
        preds.append(pl)
        rq = []
        for rn, u in (jb.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append((ridx[rn], u))
        req.append(rq)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if deg[j] > 0]
        return _infeasible(state, "precedence cycle among: " + ", ".join(rem[:8]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k

    # heads / tails
    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(es[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        if cap[r] <= 0:
            continue
        users = [j for j in range(n) if dur[j] > 0 and any(rr == r for rr, _ in req[j])]
        if not users:
            continue
        thr = sorted(set(es[j] for j in users))
        for th in thr:
            E = 0
            for j in users:
                if es[j] >= th:
                    for rr, u in req[j]:
                        if rr == r:
                            E += u * dur[j]
            lbv = th + (E + cap[r] - 1) // cap[r]
            if lbv > LB:
                LB = lbv

    H = max(rel) + sum(dur) + max(dur) + 5

    # descendants count
    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= (1 << s) | desc[s]
        desc[j] = m
    nsucc = [bin(desc[j]).count("1") for j in range(n)]
    grpw = [dur[j] + sum(dur[s] for s in succs[j]) for j in range(n)]
    work = [dur[j] * (1 + sum(u for _, u in req[j])) for j in range(n)]

    rng = random.Random(12345)

    def gen_order(prio, noise):
        d = indeg[:]
        elig = [j for j in range(n) if d[j] == 0]
        out = []
        while elig:
            if noise <= 0:
                bi = 0
                bv = None
                for k, j in enumerate(elig):
                    v = (prio[j], tail[j], -j)
                    if bv is None or v > bv:
                        bv = v
                        bi = k
            else:
                mn = min(prio[j] for j in elig)
                ws = [(prio[j] - mn + 1.0) ** noise for j in elig]
                tot = sum(ws)
                x = rng.random() * tot
                bi = len(elig) - 1
                acc = 0.0
                for k, w in enumerate(ws):
                    acc += w
                    if x <= acc:
                        bi = k
                        break
            j = elig.pop(bi)
            out.append(j)
            for s in succs[j]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    def improve(order):
        st, ms = _sgs(order, n, dur, rel, preds, req, cap, H)
        for _ in range(3):
            bs = _bwd(st, ms, n, dur, rel, succs, req, cap, H, rank)
            if bs is None:
                break
            o2 = sorted(range(n), key=lambda j: (bs[j], rank[j]))
            st2, ms2 = _sgs(o2, n, dur, rel, preds, req, cap, H)
            if ms2 < ms:
                order, st, ms = o2, st2, ms2
            else:
                if ms2 == ms:
                    order, st = o2, st2
                break
        # normalise order to forward start times
        order = sorted(range(n), key=lambda j: (st[j], rank[j]))
        return order, st, ms

    best = {"ms": None, "st": None}

    def consider(st, ms):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]

    def timeout():
        return time.perf_counter() - t0 > budget

    pop = []
    seen = set()
    rules = [
        tail,
        [-es[j] for j in range(n)],
        nsucc,
        grpw,
        [tail[j] * 100 + nsucc[j] for j in range(n)],
        [tail[j] - es[j] for j in range(n)],
        work,
        dur,
    ]
    for pr in rules:
        o = gen_order(pr, 0)
        o, st, ms = improve(o)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))
        if best["ms"] <= LB or timeout():
            break

    P = 30
    tries = 0
    while len(pop) < P and best["ms"] > LB and not timeout() and tries < 200:
        tries += 1
        pr = rules[rng.randrange(len(rules))]
        o = gen_order(pr, rng.choice([1.0, 2.0, 3.0]))
        o, st, ms = improve(o)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))

    predset = [set(preds[j]) for j in range(n)]
    stagn = 0
    while best["ms"] > LB and not timeout() and len(pop) >= 2:
        def tour():
            a = pop[rng.randrange(len(pop))]
            b = pop[rng.randrange(len(pop))]
            return a if a[0] <= b[0] else b
        m = tour()[1]
        f = tour()[1]
        q = rng.randrange(1, n) if n > 1 else 1
        head = m[:q]
        hs = set(head)
        child = head + [j for j in f if j not in hs]
        # mutation: adjacent swaps
        nm = rng.randrange(0, 3)
        for _ in range(nm):
            if n < 2:
                break
            i = rng.randrange(n - 1)
            a, b = child[i], child[i + 1]
            if a not in predset[b]:
                child[i], child[i + 1] = b, a
        if rng.random() < 0.3 and n > 2:
            # shift a job to a random position within its precedence window
            i = rng.randrange(n)
            j = child[i]
            child.pop(i)
            lo = 0
            hi = len(child)
            for k, x in enumerate(child):
                if x in predset[j]:
                    lo = k + 1
            for k in range(len(child) - 1, -1, -1):
                if j in predset[child[k]]:
                    hi = k
            if lo > hi:
                lo = hi
            child.insert(rng.randint(lo, hi), j)
        o, st, ms = improve(child)
        prev = best["ms"]
        consider(st, ms)
        if best["ms"] < prev:
            stagn = 0
        else:
            stagn += 1
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            wi = max(range(len(pop)), key=lambda k: pop[k][0])
            if ms <= pop[wi][0]:
                pop[wi] = (ms, o)
        if stagn > 300:
            stagn = 0
            pop.sort(key=lambda x: x[0])
            keep = pop[: max(2, len(pop) // 3)]
            pop = keep
            while len(pop) < P and not timeout():
                pr = rules[rng.randrange(len(rules))]
                o = gen_order(pr, rng.choice([1.0, 2.0, 4.0]))
                o, st, ms = improve(o)
                consider(st, ms)
                pop.append((ms, o))

    st = best["st"]
    if st is None or not _validate(st, n, dur, rel, preds, req, cap):
        # fallback: strictly sequential schedule in topological order
        st = [0] * n
        t = 0
        for j in topo:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

import time, random, heapq, math

def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    reason = None
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idset:
                reason = "job %s references unknown job %s" % (j.get("id"), p); break
        if reason: break
        for r, u in (j.get("requires") or {}).items():
            if r not in res:
                reason = "job %s references unknown resource %s" % (j.get("id"), r); break
            if int(u) > int(res[r]):
                reason = "job %s requires %s units of %s > capacity %s" % (j.get("id"), u, r, res[r]); break
        if reason: break
    if reason is None:
        idx = {}
        for i, s in enumerate(ids): idx[s] = i
        n = len(jobs)
        succ = [[] for _ in range(n)]
        indeg = [0] * n
        for i, j in enumerate(jobs):
            for p in set(str(x) for x in (j.get("after") or [])):
                succ[idx[p]].append(i); indeg[i] += 1
        q = [i for i in range(n) if indeg[i] == 0]
        seen = 0
        while q:
            v = q.pop(); seen += 1
            for w in succ[v]:
                indeg[w] -= 1
                if indeg[w] == 0: q.append(w)
        if seen < n:
            cyc = [ids[i] for i in range(n) if indeg[i] > 0]
            reason = "precedence cycle among " + ", ".join(cyc[:6])
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["infeasible"] = True
    else:
        state["infeasible"] = False
    return state

def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 0.9
    inp = state["input"]
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(res.keys())
    rix = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(rnames)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids): idx[s] = i
    dur = [max(0, int(j.get("duration", 0))) for j in jobs]
    rel = [max(0, int(j.get("release", 0))) for j in jobs]
    req = []
    for i, j in enumerate(jobs):
        lst = []
        if dur[i] > 0:
            for r, u in (j.get("requires") or {}).items():
                if int(u) > 0: lst.append((rix[r], int(u)))
        req.append(lst)
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        v = q.pop(); topo.append(v)
        for w in succs[v]:
            indeg[w] -= 1
            if indeg[w] == 0: q.append(w)
    head = [0] * n
    for v in topo:
        h = rel[v]
        for p in preds[v]: h = max(h, head[p] + dur[p])
        head[v] = h
    tail = [0] * n
    for v in reversed(topo):
        t = 0
        for w in succs[v]: t = max(t, tail[w])
        tail[v] = t + dur[v]
    nsucc = [0] * n
    for v in reversed(topo):
        nsucc[v] = len(succs[v]) + sum(nsucc[w] for w in succs[v])
    LB = max(head[v] + tail[v] for v in range(n))
    for r in range(R):
        tot = 0; mr = None; mt = None
        for v in range(n):
            for (rr, u) in req[v]:
                if rr == r:
                    tot += u * dur[v]
                    mr = head[v] if mr is None else min(mr, head[v])
                    tt = tail[v] - dur[v]
                    mt = tt if mt is None else min(mt, tt)
        if tot:
            LB = max(LB, mr + (tot + cap[r] - 1) // cap[r] + mt)
        big = [v for v in range(n) if any(rr == r and 2 * u > cap[r] for (rr, u) in req[v])]
        if big:
            LB = max(LB, min(head[v] for v in big) + sum(dur[v] for v in big) + min(tail[v] - dur[v] for v in big))
    H = max(rel) + sum(dur) + max(head[v] + tail[v] for v in range(n)) + 20
    zeros = [0] * n

    def sgs(pr, ps, rl, key):
        usage = [[0] * H for _ in range(R)]
        st = [0] * n
        fin = [0] * n
        cnt = [len(pr[i]) for i in range(n)]
        hp = [(key[i], i) for i in range(n) if cnt[i] == 0]
        heapq.heapify(hp)
        ms = 0
        while hp:
            _, j = heapq.heappop(hp)
            e = rl[j]
            for p in pr[j]:
                if fin[p] > e: e = fin[p]
            d = dur[j]; rq = req[j]
            if d > 0 and rq:
                t = e
                while True:
                    ok = True
                    for tt in range(t + d - 1, t - 1, -1):
                        for (r, u) in rq:
                            if usage[r][tt] + u > cap[r]:
                                ok = False; break
                        if not ok: break
                    if ok: break
                    t = tt + 1
                for tt in range(t, t + d):
                    for (r, u) in rq:
                        usage[r][tt] += u
                e = t
            st[j] = e; fin[j] = e + d
            if fin[j] > ms: ms = fin[j]
            for w in ps[j]:
                cnt[w] -= 1
                if cnt[w] == 0: heapq.heappush(hp, (key[w], w))
        return st, ms

    def fbi(key):
        st, ms = sgs(preds, succs, rel, key)
        best = (ms, st)
        for _ in range(6):
            bkey = [-(st[i] + dur[i]) + 1e-6 * i for i in range(n)]
            bs, bms = sgs(succs, preds, zeros, bkey)
            fkey = [(bms - bs[i] - dur[i]) + 1e-6 * (st[i]) for i in range(n)]
            st, ms = sgs(preds, succs, rel, fkey)
            if ms < best[0]:
                best = (ms, st)
            else:
                break
        return best

    rnd = random.Random(12345)
    bestms = None; beststart = None; bestkey = None

    def consider(key):
        nonlocal bestms, beststart, bestkey
        ms, st = fbi(key)
        if bestms is None or ms < bestms or (ms == bestms and rnd.random() < 0.3):
            bestms, beststart, bestkey = ms, st, key
        return ms

    rules = [
        [-tail[i] for i in range(n)],
        [head[i] - tail[i] * 1.0 for i in range(n)],
        [head[i] for i in range(n)],
        [-nsucc[i] - tail[i] * 0.01 for i in range(n)],
        [-tail[i] + head[i] * 0.5 for i in range(n)],
        [-(dur[i] * sum(u for _, u in req[i])) for i in range(n)],
    ]
    for k in rules:
        consider([k[i] + 1e-6 * i for i in range(n)])
        if bestms <= LB: break
    span = max(1, max(tail) + max(head))
    while bestms > LB and time.perf_counter() - T0 < BUDGET:
        mode = rnd.random()
        if mode < 0.35:
            base = rules[rnd.randrange(len(rules))]
            sc = rnd.choice([0.1, 0.3, 1.0, 3.0]) * span
            key = [base[i] + rnd.random() * sc for i in range(n)]
        elif mode < 0.45:
            key = [rnd.random() for _ in range(n)]
        else:
            key = [beststart[i] + 1e-3 * rnd.random() for i in range(n)]
            m = rnd.randint(1, max(1, n // 5))
            for _ in range(m):
                j = rnd.randrange(n)
                key[j] += rnd.uniform(-1, 1) * rnd.choice([1, 3, 8, 20])
        consider(key)
    state["output"] = {"status": "ok", "start": {ids[i]: int(beststart[i]) for i in range(n)}}
    state["lb"] = LB
    state["ms"] = bestms
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t_begin = time.perf_counter()
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, jid in enumerate(ids):
        idx[jid] = i
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]

    dur = [max(0, int(j.get("duration", 0) or 0)) for j in jobs]
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    preds = [[] for _ in range(n)]
    req = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], p))
            pi = idx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
        for r, u in (j.get("requires") or {}).items():
            if r not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], r))
            u = int(u)
            if u > cap[ridx[r]]:
                return _infeasible(state, "job %s requires %d of %s, capacity %d" % (ids[i], u, r, cap[ridx[r]]))
            if u > 0:
                req[i].append((ridx[r], u))
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)

    # cycle detection (Kahn)
    indeg = [len(preds[i]) for i in range(n)]
    queue = [i for i in range(n) if indeg[i] == 0]
    topo = []
    k = 0
    while k < len(queue):
        v = queue[k]; k += 1
        topo.append(v)
        for s in succs[v]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) < n:
        cyc = [ids[i] for i in range(n) if indeg[i] > 0][:5]
        return _infeasible(state, "precedence cycle among " + ", ".join(cyc))

    for i in range(n):
        if dur[i] == 0:
            req[i] = []

    # heads, tails, lower bound
    head = [0] * n
    for v in topo:
        h = rel[v]
        for p in preds[v]:
            h = max(h, head[p] + dur[p])
        head[v] = h
    tail = [0] * n
    for v in reversed(topo):
        t = 0
        for s in succs[v]:
            t = max(t, tail[s])
        tail[v] = dur[v] + t
    LB = max(head[i] + tail[i] for i in range(n))
    R = len(cap)
    for r in range(R):
        users = [i for i in range(n) if any(rr == r for rr, _ in req[i])]
        if not users:
            continue
        hs = sorted(set(head[i] for i in users))
        for h in hs:
            e = 0
            mintail_after = None
            for i in users:
                if head[i] >= h:
                    for rr, u in req[i]:
                        if rr == r:
                            e += u * dur[i]
            if e > 0:
                LB = max(LB, h + (e + cap[r] - 1) // cap[r])

    H = max(rel) + 2 * sum(dur) + 5

    def sgs(keys, P, S, rl):
        # serial SGS, topological selection by min key
        start = [0] * n
        finish = [0] * n
        use = [[0] * H for _ in range(R)]
        deg = [len(P[i]) for i in range(n)]
        heap = [(keys[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(heap)
        ms = 0
        while heap:
            _, j = heapq.heappop(heap)
            est = rl[j]
            for p in P[j]:
                if finish[p] > est:
                    est = finish[p]
            d = dur[j]
            rq = req[j]
            t = est
            if rq:
                while True:
                    ok = True
                    for tt in range(t, t + d):
                        for r, u in rq:
                            if use[r][tt] + u > cap[r]:
                                ok = False
                                break
                        if not ok:
                            t = tt + 1
                            break
                    if ok:
                        break
                for tt in range(t, t + d):
                    for r, u in rq:
                        use[r][tt] += u
            start[j] = t
            finish[j] = t + d
            if t + d > ms:
                ms = t + d
            for s in S[j]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(heap, (keys[s], s))
        return start, ms

    zeros = [0] * n

    def improve(start, ms):
        # forward-backward improvement
        while True:
            bkeys = [-(start[i] + dur[i]) - 1e-6 * tail[i] for i in range(n)]
            ms_start, bms = sgs(bkeys, succs, preds, zeros)
            fkeys = [bms - ms_start[i] - dur[i] for i in range(n)]
            ns, nms = sgs(fkeys, preds, succs, rel)
            if nms < ms:
                start, ms = ns, nms
            else:
                return start, ms

    best = None
    best_ms = None

    def consider(keys):
        nonlocal best, best_ms
        s, m = sgs(keys, preds, succs, rel)
        s, m = improve(s, m)
        if best_ms is None or m < best_ms:
            best, best_ms = s, m
        return m

    rules = [
        [-tail[i] for i in range(n)],
        [head[i] - tail[i] * 0.001 for i in range(n)],
        [head[i] - (LB - tail[i]) * 0 - tail[i] for i in range(n)],
        [-(tail[i] + sum(u for _, u in req[i]) * dur[i] * 0.1) for i in range(n)],
        [-len(succs[i]) - tail[i] * 0.01 for i in range(n)],
        [-(LB - tail[i] - head[i]) * 0 + (LB - tail[i]) for i in range(n)],
    ]
    for kk in rules:
        consider(kk)
        if best_ms <= LB:
            break

    rng = random.Random(12345)
    budget = 1.0
    it = 0
    while best_ms > LB and time.perf_counter() - t_begin < budget:
        it += 1
        mode = rng.random()
        if mode < 0.4:
            sc = rng.choice([0.5, 1.0, 2.0, 4.0, 8.0])
            keys = [-tail[i] + rng.uniform(0, sc) for i in range(n)]
        elif mode < 0.55:
            sc = rng.choice([1.0, 3.0, 6.0])
            keys = [head[i] - tail[i] + rng.uniform(0, sc) for i in range(n)]
        else:
            sc = rng.choice([0.5, 1.5, 3.0, 6.0])
            keys = [best[i] + rng.uniform(-sc, sc) for i in range(n)]
            if rng.random() < 0.3:
                a = rng.randrange(n); b = rng.randrange(n)
                keys[a], keys[b] = keys[b], keys[a]
        consider(keys)

    # final verification (safety)
    ok = True
    for i in range(n):
        if best[i] < rel[i]:
            ok = False
        for p in preds[i]:
            if best[i] < best[p] + dur[p]:
                ok = False
    if ok:
        use = [[0] * (best_ms + 1) for _ in range(R)]
        for i in range(n):
            for r, u in req[i]:
                for tt in range(best[i], best[i] + dur[i]):
                    use[r][tt] += u
                    if use[r][tt] > cap[r]:
                        ok = False
    if not ok:
        # fallback: fully serial schedule in topological order
        t = 0
        best = [0] * n
        for v in topo:
            s = max(t, rel[v])
            for p in preds[v]:
                s = max(s, best[p] + dur[p])
            best[v] = s
            t = s + dur[v]

    state["output"] = {"status": "ok", "start": {ids[i]: int(best[i]) for i in range(n)}}
    return state

import time
import random
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _sgs(order, n, dur, rel, preds, req, cap, H):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    start = [0] * n
    ms = 0
    for j in order:
        t = rel[j]
        for p in preds[j]:
            f = start[p] + dur[p]
            if f > t:
                t = f
        d = dur[j]
        rq = req[j]
        if d > 0 and rq:
            while True:
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t, t + d):
                        if ur[s] > lim:
                            t = s + 1
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        start[j] = t
        if t + d > ms:
            ms = t + d
    return start, ms


def _bwd(start, ms, n, dur, rel, succs, req, cap, H, rank):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
    bs = [0] * n
    for j in order:
        lf = ms
        for s in succs[j]:
            if bs[s] < lf:
                lf = bs[s]
        d = dur[j]
        t = lf - d
        rq = req[j]
        if d > 0 and rq:
            while True:
                if t < 0:
                    return None
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t + d - 1, t - 1, -1):
                        if ur[s] > lim:
                            t = s - d
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        if t < 0:
            return None
        bs[j] = t
    return bs


def _validate(starts, n, dur, rel, preds, req, cap):
    if len(starts) != n:
        return False
    for j in range(n):
        if starts[j] < rel[j]:
            return False
        for p in preds[j]:
            if starts[j] < starts[p] + dur[p]:
                return False
    events = {}
    for j in range(n):
        if dur[j] > 0:
            for t in range(starts[j], starts[j] + dur[j]):
                lst = events.get(t)
                if lst is None:
                    lst = [0] * len(cap)
                    events[t] = lst
                for r, u in req[j]:
                    lst[r] += u
    for t in events:
        lst = events[t]
        for r in range(len(cap)):
            if lst[r] > cap[r]:
                return False
    return True


def _bnb(n, dur, rel, preds, succs, req, cap, H, rank, topo, tail, indeg,
         best_ms, best_st, deadline):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    st = [0] * n
    placed = [False] * n
    deg = indeg[:]
    remE = [0] * R
    for j in range(n):
        if dur[j] > 0:
            for r, u in req[j]:
                remE[r] += u * dur[j]
    esd = [0] * n
    inc = {"ms": best_ms, "st": best_st[:] if best_st else None,
           "cnt": 0, "stop": False, "improved": False}

    def place_time(j):
        t = rel[j]
        for p in preds[j]:
            f = st[p] + dur[p]
            if f > t:
                t = f
        d = dur[j]
        rq = req[j]
        if d > 0 and rq:
            while True:
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t, t + d):
                        if ur[s] > lim:
                            t = s + 1
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
        return t

    def dfs(k, s_last, r_last, cur_ms):
        if inc["stop"]:
            return
        if k == n:
            if cur_ms < inc["ms"]:
                inc["ms"] = cur_ms
                inc["st"] = st[:]
                inc["improved"] = True
            return
        inc["cnt"] += 1
        if (inc["cnt"] & 127) == 0 and time.perf_counter() > deadline:
            inc["stop"] = True
            return
        ub = inc["ms"] - 1
        if cur_ms > ub:
            return
        # dynamic critical-path bound
        for j in topo:
            if placed[j]:
                continue
            t = rel[j]
            if s_last > t:
                t = s_last
            for p in preds[j]:
                if placed[p]:
                    f = st[p] + dur[p]
                else:
                    f = esd[p] + dur[p]
                if f > t:
                    t = f
            esd[j] = t
            if t + tail[j] > ub:
                return
        # energy bound
        for r in range(R):
            E = remE[r]
            if E > 0:
                if ub <= s_last:
                    return
                free = cap[r] * (ub - s_last) - sum(usage[r][s_last:ub])
                if free < E:
                    return
        cands = []
        for j in range(n):
            if placed[j] or deg[j] != 0:
                continue
            t = place_time(j)
            if t < s_last or (t == s_last and rank[j] < r_last):
                continue
            if t + tail[j] > ub:
                continue
            cands.append((t + tail[j], t, -dur[j], j))
        cands.sort()
        for _, t, _, j in cands:
            if inc["stop"]:
                return
            if t + tail[j] > inc["ms"] - 1:
                continue
            d = dur[j]
            rq = req[j]
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] += u
                    remE[r] -= u * d
            st[j] = t
            placed[j] = True
            for s in succs[j]:
                deg[s] -= 1
            nm = cur_ms if cur_ms > t + d else t + d
            dfs(k + 1, t, rank[j], nm)
            for s in succs[j]:
                deg[s] += 1
            placed[j] = False
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] -= u
                    remE[r] += u * d

    dfs(0, 0, -1, 0)
    return inc["ms"], inc["st"], (not inc["stop"])


def solve(state, params):
    t0 = time.perf_counter()
    ga_budget = 0.55
    total_budget = 1.1
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]

    n = len(jobs)
    ids = [str(jb.get("id")) for jb in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i

    dur = []
    rel = []
    preds = []
    req = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        pl = []
        seen = set()
        for p in (jb.get("after") or []):
            ps = str(p)
            if ps not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], ps))
            pi = idx[ps]
            if pi not in seen:
                seen.add(pi)
                pl.append(pi)
        preds.append(pl)
        rq = []
        for rn, u in (jb.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append((ridx[rn], u))
        req.append(rq)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if deg[j] > 0]
        return _infeasible(state, "precedence cycle among: " + ", ".join(rem[:8]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k

    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(es[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        if cap[r] <= 0:
            continue
        users = [j for j in range(n) if dur[j] > 0 and any(rr == r for rr, _ in req[j])]
        if not users:
            continue
        thr = sorted(set(es[j] for j in users))
        for th in thr:
            E = 0
            for j in users:
                if es[j] >= th:
                    for rr, u in req[j]:
                        if rr == r:
                            E += u * dur[j]
            lbv = th + (E + cap[r] - 1) // cap[r]
            if lbv > LB:
                LB = lbv

    H = max(rel) + sum(dur) + max(dur) + 5

    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= (1 << s) | desc[s]
        desc[j] = m
    nsucc = [bin(desc[j]).count("1") for j in range(n)]
    grpw = [dur[j] + sum(dur[s] for s in succs[j]) for j in range(n)]
    work = [dur[j] * (1 + sum(u for _, u in req[j])) for j in range(n)]

    rng = random.Random(12345)

    def gen_order(prio, noise):
        d = indeg[:]
        elig = [j for j in range(n) if d[j] == 0]
        out = []
        while elig:
            if noise <= 0:
                bi = 0
                bv = None
                for k, j in enumerate(elig):
                    v = (prio[j], tail[j], -j)
                    if bv is None or v > bv:
                        bv = v
                        bi = k
            else:
                mn = min(prio[j] for j in elig)
                ws = [(prio[j] - mn + 1.0) ** noise for j in elig]
                tot = sum(ws)
                x = rng.random() * tot
                bi = len(elig) - 1
                acc = 0.0
                for k, w in enumerate(ws):
                    acc += w
                    if x <= acc:
                        bi = k
                        break
            j = elig.pop(bi)
            out.append(j)
            for s in succs[j]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    def improve(order):
        st, ms = _sgs(order, n, dur, rel, preds, req, cap, H)
        for _ in range(3):
            bs = _bwd(st, ms, n, dur, rel, succs, req, cap, H, rank)
            if bs is None:
                break
            o2 = sorted(range(n), key=lambda j: (bs[j], rank[j]))
            st2, ms2 = _sgs(o2, n, dur, rel, preds, req, cap, H)
            if ms2 < ms:
                order, st, ms = o2, st2, ms2
            else:
                if ms2 == ms:
                    order, st = o2, st2
                break
        order = sorted(range(n), key=lambda j: (st[j], rank[j]))
        return order, st, ms

    best = {"ms": None, "st": None}

    def consider(st, ms):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]

    def timeout():
        return time.perf_counter() - t0 > ga_budget

    pop = []
    seen = set()
    rules = [
        tail,
        [-es[j] for j in range(n)],
        nsucc,
        grpw,
        [tail[j] * 100 + nsucc[j] for j in range(n)],
        [tail[j] - es[j] for j in range(n)],
        work,
        dur,
    ]
    for pr in rules:
        o = gen_order(pr, 0)
        o, st, ms = improve(o)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))
        if best["ms"] <= LB or timeout():
            break

    P = 30
    tries = 0
    while len(pop) < P and best["ms"] > LB and not timeout() and tries < 200:
        tries += 1
        pr = rules[rng.randrange(len(rules))]
        o = gen_order(pr, rng.choice([1.0, 2.0, 3.0]))
        o, st, ms = improve(o)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))

    predset = [set(preds[j]) for j in range(n)]
    stagn = 0
    while best["ms"] > LB and not timeout() and len(pop) >= 2:
        def tour():
            a = pop[rng.randrange(len(pop))]
            b = pop[rng.randrange(len(pop))]
            return a if a[0] <= b[0] else b
        m = tour()[1]
        f = tour()[1]
        q = rng.randrange(1, n) if n > 1 else 1
        head = m[:q]
        hs = set(head)
        child = head + [j for j in f if j not in hs]
        nm = rng.randrange(0, 3)
        for _ in range(nm):
            if n < 2:
                break
            i = rng.randrange(n - 1)
            a, b = child[i], child[i + 1]
            if a not in predset[b]:
                child[i], child[i + 1] = b, a
        if rng.random() < 0.3 and n > 2:
            i = rng.randrange(n)
            j = child[i]
            child.pop(i)
            lo = 0
            hi = len(child)
            for k, x in enumerate(child):
                if x in predset[j]:
                    lo = k + 1
            for k in range(len(child) - 1, -1, -1):
                if j in predset[child[k]]:
                    hi = k
            if lo > hi:
                lo = hi
            child.insert(rng.randint(lo, hi), j)
        o, st, ms = improve(child)
        prev = best["ms"]
        consider(st, ms)
        if best["ms"] < prev:
            stagn = 0
        else:
            stagn += 1
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            wi = max(range(len(pop)), key=lambda k: pop[k][0])
            if ms <= pop[wi][0]:
                pop[wi] = (ms, o)
        if stagn > 300:
            stagn = 0
            pop.sort(key=lambda x: x[0])
            keep = pop[: max(2, len(pop) // 3)]
            pop = keep
            while len(pop) < P and not timeout():
                pr = rules[rng.randrange(len(rules))]
                o = gen_order(pr, rng.choice([1.0, 2.0, 4.0]))
                o, st, ms = improve(o)
                consider(st, ms)
                pop.append((ms, o))

    # exact / anytime branch-and-bound phase over canonical SGS orders
    if best["ms"] is not None and best["ms"] > LB:
        deadline = t0 + total_budget
        if time.perf_counter() < deadline:
            try:
                bms, bst, _done = _bnb(n, dur, rel, preds, succs, req, cap, H,
                                       rank, topo, tail, indeg,
                                       best["ms"], best["st"], deadline)
                if bst is not None and bms < best["ms"]:
                    if _validate(bst, n, dur, rel, preds, req, cap):
                        best["ms"] = bms
                        best["st"] = bst[:]
            except Exception:
                pass

    st = best["st"]
    if st is None or not _validate(st, n, dur, rel, preds, req, cap):
        st = [0] * n
        t = 0
        for j in topo:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

