                    break
        return t

    def dfs(k, s_last, r_last, cur_ms):
        if inc["stop"]:
            return
        if k == n:
            if cur_ms < inc["ms"]:
                inc["ms"] = cur_ms
                inc["st"] = st[:]
                if cur_ms <= LB:
                    inc["stop"] = True
                    inc["lbhit"] = True
            return
        inc["cnt"] += 1
        if (inc["cnt"] & 127) == 0 and time.perf_counter() > deadline:
            inc["stop"] = True
            return
        ub = inc["ms"] - 1
        if cur_ms > ub:
            return
        for j in topo:
            if placed[j]:
                continue
            t = rel[j]
            if s_last > t:
                t = s_last
            for p in preds[j]:
                if placed[p]:
                    f = st[p] + dur[p]
                else:
                    f = esd[p] + dur[p]
                if f > t:
                    t = f
            esd[j] = t
            if t + tail[j] > ub:
                return
        for r in range(R):
            E = remE[r]
            if E > 0:
                if ub <= s_last:
                    return
                free = cap[r] * (ub - s_last) - sum(usage[r][s_last:ub])
                if free < E:
                    return
        cands = []
        for j in range(n):
            if placed[j] or deg[j] != 0:
                continue
            t = place_time(j)
            if t < s_last or (t == s_last and rank[j] < r_last):
                continue
            if t + tail[j] > ub:
                continue
            cands.append((t + tail[j], t, -dur[j], j))
        cands.sort()
        for _, t, _, j in cands:
            if inc["stop"]:
                return
            if t + tail[j] > inc["ms"] - 1:
                continue
            d = dur[j]
            rq = req[j]
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] += u
                    remE[r] -= u * d
            st[j] = t
            placed[j] = True
            for s in succs[j]:
                deg[s] -= 1
            nm = cur_ms if cur_ms > t + d else t + d
            dfs(k + 1, t, rank[j], nm)
            for s in succs[j]:
                deg[s] += 1
            placed[j] = False
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] -= u
                    remE[r] += u * d

    dfs(0, 0, -1, 0)
    proven = (not inc["stop"]) or inc["lbhit"]
    return inc["ms"], inc["st"], proven


def solve(state, params):
    t0 = time.perf_counter()
    GA1_END = 0.5
    BNB_END = 0.85
    TOTAL_END = 1.15
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]

    n = len(jobs)
    ids = [str(jb.get("id")) for jb in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i

    dur = []
    rel = []
    preds = []
    req = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        pl = []
        seen0 = set()
        for p in (jb.get("after") or []):
            ps = str(p)
            if ps not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], ps))
            pi = idx[ps]
            if pi not in seen0:
                seen0.add(pi)
                pl.append(pi)
        preds.append(pl)
        rq = []
        for rn, u in (jb.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append((ridx[rn], u))
        req.append(rq)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if deg[j] > 0]
        return _infeasible(state, "precedence cycle among: " + ", ".join(rem[:8]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k

    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(es[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        if cap[r] <= 0:
            continue
        users = []
        for j in range(n):
            if dur[j] > 0:
                for rr, u in req[j]:
                    if rr == r:
                        users.append((j, u))
        if not users:
            continue
        thr = sorted(set(es[j] for j, _ in users))
        for th in thr:
            E = 0
            mt = None
            for j, u in users:
                if es[j] >= th:
                    E += u * dur[j]
                    q = tail[j] - dur[j]
                    if mt is None or q < mt:
                        mt = q
            if mt is None:
                mt = 0
            lbv = th + (E + cap[r] - 1) // cap[r] + mt
            if lbv > LB:
                LB = lbv

    H = max(rel) + sum(dur) + max(dur) + 5

    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= (1 << s) | desc[s]
        desc[j] = m
    nsucc = [bin(desc[j]).count("1") for j in range(n)]
    grpw = [dur[j] + sum(dur[s] for s in succs[j]) for j in range(n)]
    work = [dur[j] * (1 + sum(u for _, u in req[j])) for j in range(n)]
    predset = [set(preds[j]) for j in range(n)]

    rng = random.Random(12345)

    def elapsed():
        return time.perf_counter() - t0

    def gen_order(prio, noise):
        d = indeg[:]
        elig = [j for j in range(n) if d[j] == 0]
        out = []
        while elig:
            if noise <= 0:
                bi = 0
                bv = None
                for k, j in enumerate(elig):
                    v = (prio[j], tail[j], -j)
                    if bv is None or v > bv:
                        bv = v
                        bi = k
            else:
                mn = min(prio[j] for j in elig)
                ws = [(prio[j] - mn + 1.0) ** noise for j in elig]
                tot = sum(ws)
                x = rng.random() * tot
                bi = len(elig) - 1
                acc = 0.0
                for k, w in enumerate(ws):
                    acc += w
                    if x <= acc:
                        bi = k
                        break
            j = elig.pop(bi)
            out.append(j)
            for s in succs[j]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    def improve(order):
        st, ms = _sgs(order, n, dur, rel, preds, req, cap, H)
        for _ in range(3):
            bs = _bwd(st, ms, n, dur, rel, succs, req, cap, H, rank)
            if bs is None:
                break
            o2 = sorted(range(n), key=lambda j: (bs[j], rank[j]))
            st2, ms2 = _sgs(o2, n, dur, rel, preds, req, cap, H)
            if ms2 < ms:
                order, st, ms = o2, st2, ms2
            else:
                if ms2 == ms:
                    order, st = o2, st2
                break
        order = sorted(range(n), key=lambda j: (st[j], rank[j]))
        return order, st, ms

    best = {"ms": None, "st": None, "order": None}

    def consider(st, ms, order):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]
            best["order"] = list(order)
            return True
        return False

    pop = []
    seen = set()
    rules = [
        tail,
        [-es[j] for j in range(n)],
        nsucc,
        grpw,
        [tail[j] * 100 + nsucc[j] for j in range(n)],
        [tail[j] - es[j] for j in range(n)],
        work,
        dur,
        [-rel[j] for j in range(n)],
    ]
    for pr in rules:
        o = gen_order(pr, 0)
        o, st, ms = improve(o)
        consider(st, ms, o)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))
        if best["ms"] <= LB or elapsed() > GA1_END:
            break

    P = 30
    tries = 0
    while len(pop) < P and best["ms"] > LB and elapsed() < GA1_END and tries < 200:
        tries += 1
        pr = rules[rng.randrange(len(rules))]
        o = gen_order(pr, rng.choice([1.0, 2.0, 3.0]))
        o, st, ms = improve(o)
        consider(st, ms, o)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))

    def window(lst, j):
        lo = 0
        hi = len(lst)
        for k, x in enumerate(lst):
            if x in predset[j]:
                lo = k + 1
        for k in range(len(lst) - 1, -1, -1):
            if j in predset[lst[k]]:
                hi = k
        if lo > hi:
            lo = hi
        return lo, hi

    def insert_to_pop(ms, o):
        key = tuple(o)
        if key in seen:
            return
        seen.add(key)
        if len(pop) < P:
            pop.append((ms, o))
            return
        wi = max(range(len(pop)), key=lambda k: pop[k][0])
        if ms <= pop[wi][0]:
            pop[wi] = (ms, o)

    def local_search(deadline):
        # insertion moves on the incumbent activity list
        base = best["order"]
        if base is None or n < 3:
            return
        for _ in range(min(2 * n, 60)):
            if time.perf_counter() - t0 > deadline or best["ms"] <= LB:
                return
            lst = list(best["order"])
            i = rng.randrange(n)
            j = lst.pop(i)
            lo, hi = window(lst, j)
            lst.insert(rng.randint(lo, hi), j)
            o, st, ms = improve(lst)
            if consider(st, ms, o):
                insert_to_pop(ms, o)

    def run_ga(deadline, stop_stagn):
        stagn = 0
        it = 0
        while best["ms"] > LB and elapsed() < deadline and len(pop) >= 2:
            it += 1

            def tour():
                a = pop[rng.randrange(len(pop))]
                b = pop[rng.randrange(len(pop))]
                return a if a[0] <= b[0] else b
            m = tour()[1]
            f = tour()[1]
            q = rng.randrange(1, n) if n > 1 else 1
            head = m[:q]
            hs = set(head)
            child = head + [j for j in f if j not in hs]
            nm = rng.randrange(0, 3)
            for _ in range(nm):
                if n < 2:
                    break
                i = rng.randrange(n - 1)
                a, b = child[i], child[i + 1]
                if a not in predset[b]:
                    child[i], child[i + 1] = b, a
            if rng.random() < 0.3 and n > 2:
                i = rng.randrange(n)
                j = child.pop(i)
                lo, hi = window(child, j)
                child.insert(rng.randint(lo, hi), j)
            if rng.random() < 0.15 and n > 3:
                # precedence-safe non-adjacent swap
                i = rng.randrange(n)
                k = rng.randrange(n)
                if i > k:
                    i, k = k, i
                if k > i:
                    a, b = child[i], child[k]
                    ok = True
                    for x in range(i + 1, k + 1):
                        if a in predset[child[x]]:
                            ok = False
                            break
                    if ok:
                        for x in range(i, k):
                            if child[x] in predset[b]:
                                ok = False
                                break
                    if ok:
                        child[i], child[k] = b, a
            o, st, ms = improve(child)
            if consider(st, ms, o):
                stagn = 0
            else:
                stagn += 1
            insert_to_pop(ms, o)
            if it % 150 == 0:
                local_search(deadline)
            if stop_stagn is not None and stagn > stop_stagn:
                return
            if stagn > 300:
                stagn = 0
                local_search(deadline)
                pop.sort(key=lambda x: x[0])
                keep = pop[: max(2, len(pop) // 3)]
                del pop[:]
                pop.extend(keep)
                while len(pop) < P and elapsed() < deadline:
                    pr = rules[rng.randrange(len(rules))]
                    o = gen_order(pr, rng.choice([1.0, 2.0, 4.0]))
                    o, st, ms = improve(o)
                    consider(st, ms, o)
                    pop.append((ms, o))

    # Phase 1: GA (stops early on stagnation to hand time to B&B)
    run_ga(GA1_END, 700)

    # Phase 2: branch and bound seeded with GA incumbent
    proven = best["ms"] is not None and best["ms"] <= LB
    if not proven and best["ms"] is not None and elapsed() < BNB_END:
        try:
            bms, bst, done = _bnb(n, dur, rel, preds, succs, req, cap, H,
                                  rank, topo, tail, indeg,
                                  best["ms"], best["st"], t0 + BNB_END, LB)
            if bst is not None and bms < best["ms"] and _validate(bst, n, dur, rel, preds, req, cap):
                o = sorted(range(n), key=lambda j: (bst[j], rank[j]))
                o2, st2, ms2 = improve(o)
                if ms2 < bms and _validate(st2, n, dur, rel, preds, req, cap):
                    best["ms"], best["st"], best["order"] = ms2, st2[:], o2
                else:
                    best["ms"], best["st"], best["order"] = bms, bst[:], o
                insert_to_pop(best["ms"], best["order"])
            if done:
                proven = True
        except Exception:
            pass

    # Phase 3: GA resumes with B&B result in population
    if not proven:
        try:
            run_ga(TOTAL_END, None)
        except Exception:
            pass

    st = best["st"]
    if st is None or not _validate(st, n, dur, rel, preds, req, cap):
        st = [0] * n
        t = 0
        for j in topo:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

import time
import random
import heapq


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    def fail(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    rnames = list(resources.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    R = len(rnames)

    dur = []
    rel = []
    preds = []
    reqs = []
    reqd = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        ps = []
        seen = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in idx:
                return fail("job %s references unknown job %s" % (ids[i], p))
            pi = idx[p]
            if pi not in seen:
                seen.add(pi)
                ps.append(pi)
        preds.append(ps)
        rq = []
        dense = [0] * R
        for r, q in (jb.get("requires") or {}).items():
            if r not in ridx:
                return fail("job %s references unknown resource %s" % (ids[i], r))
            q = int(q)
            ri = ridx[r]
            if q > cap[ri]:
                return fail("job %s needs %d of %s, capacity %d" % (ids[i], q, r, cap[ri]))
            if q > 0:
                rq.append((ri, q))
                dense[ri] += q
        reqs.append(rq)
        reqd.append(dense)

    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    indeg = [len(preds[j]) for j in range(n)]
    q0 = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q0:
        j = q0.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q0.append(s)
    if len(topo) < n:
        cyc = [ids[j] for j in range(n) if indeg[j] > 0][:5]
        return fail("precedence cycle among " + ", ".join(cyc))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    # heads / tails / lower bound
    head = [0] * n
    for j in topo:
        h = rel[j]
        for p in preds[j]:
            v = head[p] + dur[p]
            if v > h:
                h = v
        head[j] = h
    tail = [0] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            v = dur[s] + tail[s]
            if v > t:
                t = v
        tail[j] = t
    LB = max(head[j] + dur[j] + tail[j] for j in range(n))
    for r in range(R):
        if cap[r] <= 0:
            continue
        en = 0
        mr = None
        for j in range(n):
            if dur[j] > 0 and reqd[j][r] > 0:
                en += reqd[j][r] * dur[j]
                if mr is None or head[j] < mr:
                    mr = head[j]
        if mr is not None:
            LB = max(LB, mr + (en + cap[r] - 1) // cap[r])

    def fit(prof, rq, t, d, limit):
        while True:
            if t + d > limit:
                return -1
            ok = True
            u = t + d - 1
            while u >= t:
                bad = False
                for ri, q in rq:
                    if prof[ri][u] + q > cap[ri]:
                        bad = True
                        break
                if bad:
                    t = u + 1
                    ok = False
                    break
                u -= 1
            if ok:
                return t

    H0 = max(rel) + sum(dur) + 2

    def sgs(order):
        prof = [[0] * H0 for _ in range(R)]
        st = [0] * n
        mk = 0
        for j in order:
            t = rel[j]
            for p in preds[j]:
                f = st[p] + dur[p]
                if f > t:
                    t = f
            d = dur[j]
            rq = reqs[j]
            if d > 0 and rq:
                t = fit(prof, rq, t, d, H0)
                for u in range(t, t + d):
                    for ri, q in rq:
                        prof[ri][u] += q
            st[j] = t
            if t + d > mk:
                mk = t + d
        return st, mk

    def gen_order(prio):
        ind = [len(preds[j]) for j in range(n)]
        hp = [(prio[j], j) for j in range(n) if ind[j] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, j = heapq.heappop(hp)
            out.append(j)
            for s in succs[j]:
                ind[s] -= 1
                if ind[s] == 0:
                    heapq.heappush(hp, (prio[s], s))
        return out

    best_mk = None
    best_st = None
    rules = [
        [(-(dur[j] + tail[j]), head[j]) for j in range(n)],
        [(head[j], -(dur[j] + tail[j])) for j in range(n)],
        [(LB - tail[j] - dur[j], head[j]) for j in range(n)],
        [(-sum(reqd[j]) * dur[j], -tail[j]) for j in range(n)],
    ]
    for pr in rules:
        st, mk = sgs(gen_order(pr))
        if best_mk is None or mk < best_mk:
            best_mk, best_st = mk, st
    rng = random.Random(12345)
    it = 0
    while best_mk > LB and time.perf_counter() - t0 < 0.15 and it < 300:
        it += 1
        pr = [(-(dur[j] + tail[j]) * rng.uniform(0.6, 1.4) + head[j] * rng.uniform(0.0, 0.5), j) for j in range(n)]
        st, mk = sgs(gen_order(pr))
        if mk < best_mk:
            best_mk, best_st = mk, st

    # ---- CP: schedule-or-postpone with timetable + energetic propagation ----
    deadline = t0 + 1.15
    best = [best_mk, best_st[:]]
    abort = [False]
    cnt = [0]
    fixed = [-1] * n
    lb = rel[:]
    prof = [[0] * (best_mk + 2) for _ in range(R)]

    def energy_ok(est, T):
        for r in range(R):
            items = []
            for j in range(n):
                if fixed[j] < 0 and dur[j] > 0 and reqd[j][r] > 0:
                    items.append((T - tail[j], est[j], reqd[j][r] * dur[j]))
            if len(items) < 2:
                continue
            pr = prof[r]
            c = cap[r]
            F = [0] * (T + 1)
            acc = 0
            for u in range(T):
                acc += c - pr[u]
                F[u + 1] = acc
            items.sort()
            for a in set(it_[1] for it_ in items):
                E = 0
                Fa = F[a]
                for l, e, w in items:
                    if e >= a:
                        E += w
                        if E > F[l] - Fa:
                            return False
        return True

    def dfs(depth):
        if abort[0]:
            return
        cnt[0] += 1
        if (cnt[0] & 31) == 0 and time.perf_counter() > deadline:
            abort[0] = True
            return
        if depth > 650:
            return
        T = best[0] - 1
        if T < LB:
            return
        est = [0] * n
        elig = [False] * n
        anyun = False
        for j in topo:
            if fixed[j] >= 0:
                est[j] = fixed[j]
                continue
            anyun = True
            e = lb[j]
            el = True
            for p in preds[j]:
                if fixed[p] >= 0:
                    f = fixed[p] + dur[p]
                else:
                    el = False
                    f = est[p] + dur[p]
                if f > e:
                    e = f
            if e + dur[j] + tail[j] > T:
                return
            if el:
                if dur[j] > 0 and reqs[j]:
                    e = fit(prof, reqs[j], e, dur[j], T)
                    if e < 0 or e + dur[j] + tail[j] > T:
                        return
                elig[j] = True
            est[j] = e
        if not anyun:
            mk = max(fixed[j] + dur[j] for j in range(n))
            if mk < best[0]:
                best[0] = mk
                best[1] = fixed[:]
            return
        if not energy_ok(est, T):
            return
        j = -1
        bk = None
        for k in range(n):
            if fixed[k] < 0 and elig[k]:
                key = (est[k], -(dur[k] + tail[k]), -dur[k])
                if bk is None or key < bk:
                    bk = key
                    j = k
        t = est[j]
        d = dur[j]
        rq = reqs[j]
        fixed[j] = t
        if d > 0:
            for u in range(t, t + d):
                for ri, q in rq:
                    prof[ri][u] += q
        dfs(depth + 1)
        if d > 0:
            for u in range(t, t + d):
                for ri, q in rq:
                    prof[ri][u] -= q
        fixed[j] = -1
        if abort[0]:
            return
        if d == 0 or not rq:
            return
        cand = None
        for k in range(n):
            if k == j or not reqs[k] or dur[k] <= 0:
                continue
            if fixed[k] >= 0:
                f = fixed[k] + dur[k]
                if f > t and (cand is None or f < cand):
                    cand = f
            else:
                f = t + dur[k]
                if cand is None or f < cand:
                    cand = f
        if cand is None:
            return
        old = lb[j]
        lb[j] = cand
        dfs(depth + 1)
        lb[j] = old

    if best[0] > LB:
        try:
            dfs(0)
        except RecursionError:
            pass

    st = best[1]
    # final safety validation; fall back to SGS incumbent if anything is off
    def valid(s):
        if any(s[j] is None or s[j] < rel[j] for j in range(n)):
            return False
        for j in range(n):
            for p in preds[j]:
                if s[j] < s[p] + dur[p]:
                    return False
        H = max(s[j] + dur[j] for j in range(n)) + 1
        use = [[0] * H for _ in range(R)]
        for j in range(n):
            for u in range(s[j], s[j] + dur[j]):
                for ri, q in reqs[j]:
                    use[ri][u] += q
                    if use[ri][u] > cap[ri]:
                        return False
        return True

    if not valid(st):
        st = best_st
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

import time, random, heapq, math

def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    reason = None
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idset:
                reason = "job %s references unknown job %s" % (j.get("id"), p); break
        if reason: break
        for r, u in (j.get("requires") or {}).items():
            if r not in res:
                reason = "job %s references unknown resource %s" % (j.get("id"), r); break
            if int(u) > int(res[r]):
                reason = "job %s requires %s units of %s > capacity %s" % (j.get("id"), u, r, res[r]); break
        if reason: break
    if reason is None:
        idx = {}
        for i, s in enumerate(ids): idx[s] = i
        n = len(jobs)
        succ = [[] for _ in range(n)]
        indeg = [0] * n
        for i, j in enumerate(jobs):
            for p in set(str(x) for x in (j.get("after") or [])):
                succ[idx[p]].append(i); indeg[i] += 1
        q = [i for i in range(n) if indeg[i] == 0]
        seen = 0
        while q:
            v = q.pop(); seen += 1
            for w in succ[v]:
                indeg[w] -= 1
                if indeg[w] == 0: q.append(w)
        if seen < n:
            cyc = [ids[i] for i in range(n) if indeg[i] > 0]
            reason = "precedence cycle among " + ", ".join(cyc[:6])
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        state["infeasible"] = True
    else:
        state["infeasible"] = False
    return state

def solve(state, params):
    T0 = time.perf_counter()
    BUDGET = 1.1
    inp = state["input"]
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(res.keys())
    rix = {r: i for i, r in enumerate(rnames)}
    cap = [int(res[r]) for r in rnames]
    R = len(rnames)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids): idx[s] = i
    dur = [max(0, int(j.get("duration", 0))) for j in jobs]
    rel = [max(0, int(j.get("release", 0))) for j in jobs]
    req = []
    reqv = [[0] * R for _ in range(n)]
    for i, j in enumerate(jobs):
        lst = []
        if dur[i] > 0:
            for r, u in (j.get("requires") or {}).items():
                if int(u) > 0:
                    lst.append((rix[r], int(u)))
                    reqv[i][rix[r]] += int(u)
        req.append(lst)
    preds = [sorted(set(idx[str(p)] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        v = q.pop(); topo.append(v)
        for w in succs[v]:
            indeg[w] -= 1
            if indeg[w] == 0: q.append(w)
    head = [0] * n
    for v in topo:
        h = rel[v]
        for p in preds[v]: h = max(h, head[p] + dur[p])
        head[v] = h
    tail = [0] * n
    for v in reversed(topo):
        t = 0
        for w in succs[v]: t = max(t, tail[w])
        tail[v] = t + dur[v]
    nsucc = [0] * n
    for v in reversed(topo):
        nsucc[v] = len(succs[v]) + sum(nsucc[w] for w in succs[v])
    anc = [0] * n
    for v in topo:
        a = 0
        for p in preds[v]: a |= anc[p] | (1 << p)
        anc[v] = a

    # ---------------- lower bound ----------------
    LB = max(head[v] + tail[v] for v in range(n))
    qt = [tail[v] - dur[v] for v in range(n)]

    def thr_bound(S, weight, divisor):
        best = 0
        for h in set(head[v] for v in S):
            sub = [v for v in S if head[v] >= h]
            e = sum(weight[v] for v in sub)
            val = h + (e + divisor - 1) // divisor + min(qt[v] for v in sub)
            if val > best: best = val
        for qq in set(qt[v] for v in S):
            sub = [v for v in S if qt[v] >= qq]
            e = sum(weight[v] for v in sub)
            val = min(head[v] for v in sub) + (e + divisor - 1) // divisor + qq
            if val > best: best = val
        return best

    for r in range(R):
        S = [v for v in range(n) if reqv[v][r] > 0 and dur[v] > 0]
        if S:
            w = [reqv[v][r] * dur[v] for v in range(n)]
            LB = max(LB, thr_bound(S, w, cap[r]))
    pos = [v for v in range(n) if dur[v] > 0]

    def conf(i, j):
        if (anc[j] >> i) & 1 or (anc[i] >> j) & 1: return True
        ri = reqv[i]; rj = reqv[j]
        for r in range(R):
            if ri[r] + rj[r] > cap[r]: return True
        return False

    cand = sorted(pos, key=lambda v: -dur[v])
    cl_seen = set()
    for s in pos:
        cl = [s]
        for c in cand:
            if c == s: continue
            ok = True
            for x in cl:
                if not conf(c, x): ok = False; break
            if ok: cl.append(c)
        sig = tuple(sorted(cl))
        if len(cl) < 2 or sig in cl_seen: continue
        cl_seen.add(sig)
        LB = max(LB, thr_bound(cl, dur, 1))

    H = max(rel) + sum(dur) + max(head[v] + tail[v] for v in range(n)) + 20
    zeros = [0] * n

    def sgs(pr, ps, rl, key):
        usage = [[0] * H for _ in range(R)]
        st = [0] * n
        fin = [0] * n
        cnt = [len(pr[i]) for i in range(n)]
        hp = [(key[i], i) for i in range(n) if cnt[i] == 0]
        heapq.heapify(hp)
        ms = 0
        while hp:
            _, j = heapq.heappop(hp)
            e = rl[j]
            for p in pr[j]:
                if fin[p] > e: e = fin[p]
            d = dur[j]; rq = req[j]
            if d > 0 and rq:
                t = e
                while True:
                    ok = True
                    for tt in range(t + d - 1, t - 1, -1):
                        for (r, u) in rq:
                            if usage[r][tt] + u > cap[r]:
                                ok = False; break
                        if not ok: break
                    if ok: break
                    t = tt + 1
                for tt in range(t, t + d):
                    for (r, u) in rq:
                        usage[r][tt] += u
                e = t
            st[j] = e; fin[j] = e + d
            if fin[j] > ms: ms = fin[j]
            for w in ps[j]:
                cnt[w] -= 1
                if cnt[w] == 0: heapq.heappush(hp, (key[w], w))
        return st, ms

    def fbi(key):
        st, ms = sgs(preds, succs, rel, key)
        best = (ms, st)
        for _ in range(5):
            bkey = [-(st[i] + dur[i]) + 1e-6 * i for i in range(n)]
            bs, bms = sgs(succs, preds, zeros, bkey)
            fkey = [(bms - bs[i] - dur[i]) + 1e-6 * st[i] for i in range(n)]
            st, ms = sgs(preds, succs, rel, fkey)
            if ms < best[0]:
                best = (ms, st)
            else:
                break
        return best

    def evaluate(order):
        key = [0] * n
        for p, j in enumerate(order): key[j] = p
        ms, st = fbi(key)
        no = sorted(range(n), key=lambda i: (st[i], key[i]))
        return (ms, no, st)

    rnd = random.Random(12345)
    P = 30
    pop = []
    seen = set()
    bestr = [None]

    def insert(r):
        if bestr[0] is None or r[0] < bestr[0][0]:
            bestr[0] = r
        sig = tuple(r[2])
        if sig in seen: return False
        if len(pop) < P:
            pop.append(r); seen.add(sig); return True
        w = 0
        for i in range(1, len(pop)):
            if pop[i][0] > pop[w][0]: w = i
        if r[0] <= pop[w][0]:
            seen.discard(tuple(pop[w][2]))
            pop[w] = r; seen.add(sig); return True
        return False

    rules = [
        [-tail[i] for i in range(n)],
        [head[i] - tail[i] * 1.0 for i in range(n)],
        [head[i] for i in range(n)],
        [-nsucc[i] - tail[i] * 0.01 for i in range(n)],
        [-tail[i] + head[i] * 0.5 for i in range(n)],
        [-(dur[i] * sum(u for _, u in req[i])) for i in range(n)],
    ]
    for k in rules:
        kk = [k[i] + 1e-6 * i for i in range(n)]
        insert(evaluate(sorted(range(n), key=lambda i: kk[i])))
        if bestr[0][0] <= LB: break
    span = max(1, max(tail) + max(head))
    tries = 0
    while bestr[0][0] > LB and len(pop) < P and tries < 3 * P and time.perf_counter() - T0 < 0.3 * BUDGET:
        tries += 1
        if rnd.random() < 0.8:
            base = rules[rnd.randrange(len(rules))]
            sc = rnd.choice([0.1, 0.3, 1.0, 3.0]) * span
            kk = [base[i] + rnd.random() * sc for i in range(n)]
        else:
            kk = [rnd.random() for _ in range(n)]
        insert(evaluate(sorted(range(n), key=lambda i: kk[i])))

    def mutate(order, strength):
        if n < 2: return order
        for _ in range(strength):
            if rnd.random() < 0.5:
                i = rnd.randrange(n - 1)
                order[i], order[i + 1] = order[i + 1], order[i]
            else:
                i = rnd.randrange(n); j = rnd.randrange(n)
                x = order.pop(i); order.insert(j, x)
        return order

    def cx(a, b):
        q1 = rnd.randint(0, n); q2 = rnd.randint(0, n)
        if q1 > q2: q1, q2 = q2, q1
        child = a[:q1]; inn = set(child)
        for x in b:
            if len(child) >= q2: break
            if x not in inn: child.append(x); inn.add(x)
        for x in a:
            if x not in inn: child.append(x); inn.add(x)
        return child

    def tourn():
        a = pop[rnd.randrange(len(pop))]; b = pop[rnd.randrange(len(pop))]
        return a if a[0] <= b[0] else b

    stag = 0
    lastbest = bestr[0][0]
    while bestr[0][0] > LB and time.perf_counter() - T0 < BUDGET and n >= 2:
        if rnd.random() < 0.85 and len(pop) >= 2:
            child = cx(tourn()[1], tourn()[1])
            if rnd.random() < 0.6:
                mutate(child, rnd.randint(1, 2))
        else:
            child = mutate(list(tourn()[1]), rnd.randint(1, 4))
        insert(evaluate(child))
        if bestr[0][0] < lastbest:
            lastbest = bestr[0][0]; stag = 0
        else:
            stag += 1
        if stag > 150:
            stag = 0
            pop.sort(key=lambda r: r[0])
            keep = pop[: max(2, len(pop) // 2)]
            pop[:] = keep
            seen.clear()
            for r in pop: seen.add(tuple(r[2]))
            k = 0
            while len(pop) < P and k < P and time.perf_counter() - T0 < BUDGET:
                k += 1
                insert(evaluate(mutate(list(bestr[0][1]), rnd.randint(2, max(3, n // 4)))))
    beststart = bestr[0][2]
    state["output"] = {"status": "ok", "start": {ids[i]: int(beststart[i]) for i in range(n)}}
    state["lb"] = LB
    state["ms"] = bestr[0][0]
    return state

import time
import random
import heapq


def _validate(inp):
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    for j in jobs:
        for p in (j.get("after") or []):
            if str(p) not in idset:
                return "job %s references unknown job %s" % (j.get("id"), p)
        for r, u in (j.get("requires") or {}).items():
            if r not in resources:
                return "job %s references unknown resource %s" % (j.get("id"), r)
            if u > resources[r]:
                return "job %s needs %s units of %s > capacity %s" % (j.get("id"), u, r, resources[r])
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    n = len(ids)
    indeg = [0] * n
    succ = [set() for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            pi = idx[str(p)]
            if i not in succ[pi]:
                succ[pi].add(i)
                indeg[i] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    cnt = 0
    while q:
        x = q.pop()
        cnt += 1
        for y in succ[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                q.append(y)
    if cnt < n:
        return "precedence cycle detected"
    return None


def _check(n, d, rel, preds, req, caps, start):
    for i in range(n):
        if start[i] < rel[i]:
            return False
        for p in preds[i]:
            if start[i] < start[p] + d[p]:
                return False
    H = max([start[i] + d[i] for i in range(n)] + [0]) + 1
    for r in range(len(caps)):
        use = [0] * H
        for i in range(n):
            u = req[i][r]
            if u > 0 and d[i] > 0:
                for t in range(start[i], start[i] + d[i]):
                    use[t] += u
                    if use[t] > caps[r]:
                        return False
    return True


def _sgs(n, d, rel, preds, succ, req, caps, order_key):
    # serial SGS, precedence-feasible order by key (smaller first)
    R = len(caps)
    indeg = [len(preds[i]) for i in range(n)]
    heap = [(order_key[i], i) for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    usage = [dict() for _ in range(R)]
    start = [0] * n
    while heap:
        _, i = heapq.heappop(heap)
        t = rel[i]
        for p in preds[i]:
            v = start[p] + d[p]
            if v > t:
                t = v
        if d[i] > 0:
            ok = False
            while not ok:
                ok = True
                for tt in range(t, t + d[i]):
                    for r in range(R):
                        if req[i][r] and usage[r].get(tt, 0) + req[i][r] > caps[r]:
                            ok = False
                            break
                    if not ok:
                        t = tt + 1
                        break
            for tt in range(t, t + d[i]):
                for r in range(R):
                    if req[i][r]:
                        usage[r][tt] = usage[r].get(tt, 0) + req[i][r]
        start[i] = t
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0:
                heapq.heappush(heap, (order_key[s], s))
    return start


def solve(state, params):
    t0 = time.perf_counter()
    inp = state["input"]
    reason = _validate(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    caps = [int(resources[r]) for r in rnames]
    R = len(caps)
    ids = [str(j.get("id")) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    n = len(ids)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    d = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    preds = [[] for _ in range(n)]
    succ = [[] for _ in range(n)]
    bset = [set() for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            pi = idx[str(p)]
            if i not in bset[pi]:
                bset[pi].add(i)
                succ[pi].append(i)
                preds[i].append(pi)
    req = [[0] * R for _ in range(n)]
    for i, j in enumerate(jobs):
        for r, u in (j.get("requires") or {}).items():
            req[i][rnames.index(r)] = int(u)
    active_jobs = [i for i in range(n) if d[i] > 0 and any(req[i][r] > 0 for r in range(R))]

    def compute(extra):
        indeg = [0] * n
        for i in range(n):
            for j in succ[i]:
                indeg[j] += 1
            for j in extra[i]:
                indeg[j] += 1
        q = [i for i in range(n) if indeg[i] == 0]
        order = []
        while q:
            x = q.pop()
            order.append(x)
            for y in succ[x]:
                indeg[y] -= 1
                if indeg[y] == 0:
                    q.append(y)
            for y in extra[x]:
                indeg[y] -= 1
                if indeg[y] == 0:
                    q.append(y)
        if len(order) < n:
            return None
        est = rel[:]
        for x in order:
            f = est[x] + d[x]
            for y in succ[x]:
                if f > est[y]:
                    est[y] = f
            for y in extra[x]:
                if f > est[y]:
                    est[y] = f
        tail = d[:]
        for x in reversed(order):
            m = 0
            for y in succ[x]:
                if tail[y] > m:
                    m = tail[y]
            for y in extra[x]:
                if tail[y] > m:
                    m = tail[y]
            tail[x] = d[x] + m
        return est, tail

    def find_conflict(est):
        if not active_jobs:
            return None
        H = max(est[i] + d[i] for i in active_jobs) + 1
        best_t = None
        best_rs = None
        for r in range(R):
            use = [0] * H
            for i in active_jobs:
                u = req[i][r]
                if u:
                    for t in range(est[i], est[i] + d[i]):
                        use[t] += u
            c = caps[r]
            for t in range(H):
                if use[t] > c:
                    if best_t is None or t < best_t:
                        best_t = t
                        best_rs = [r]
                    elif t == best_t:
                        best_rs.append(r)
                    break
        if best_t is None:
            return None
        t = best_t
        S = [i for i in active_jobs if est[i] <= t < est[i] + d[i]
             and any(req[i][r] > 0 for r in best_rs)]
        return S

    def flatten(extra, rng, noise):
        while True:
            res = compute(extra)
            if res is None:
                return None
            est, tail = res
            S = find_conflict(est)
            if S is None:
                return est
            best = None
            bp = None
            for a in S:
                fa = est[a] + d[a]
                for b in S:
                    if a == b:
                        continue
                    val = fa + tail[b]
                    cost = fa - est[b]
                    key = val + cost * 0.01
                    if noise > 0:
                        key = key * (1.0 + noise * rng.random())
                    if best is None or key < best:
                        best = key
                        bp = (a, b)
            a, b = bp
            extra[a].add(b)

    def mk(est):
        return max(est[i] + d[i] for i in range(n))

    # lower bound
    base = compute([set() for _ in range(n)])
    est0, tail0 = base
    lb = max(est0[i] + tail0[i] for i in range(n))
    for r in range(R):
        e = sum(d[i] * req[i][r] for i in range(n))
        if e > 0:
            mr = min(est0[i] for i in range(n) if req[i][r] > 0 and d[i] > 0)
            lb = max(lb, mr + -(-e // caps[r]))

    rng = random.Random(12345)
    best_start = None
    best_ms = None

    def consider(st):
        nonlocal best_start, best_ms
        if st is None:
            return
        if not _check(n, d, rel, preds, req, caps, st):
            return
        m = mk(st)
        if best_ms is None or m < best_ms:
            best_ms = m
            best_start = list(st)

    # safety seed: serial SGS with critical-path priority
    consider(_sgs(n, d, rel, preds, succ, req, caps, [(-tail0[i] - est0[i], i) for i in range(n)]))
    consider(_sgs(n, d, rel, preds, succ, req, caps, [(est0[i], -tail0[i], i) for i in range(n)]))

    budget = 1.15
    if best_ms is not None and best_ms <= lb:
        budget = 0.0

    cur_extra = [set() for _ in range(n)]
    est = flatten(cur_extra, rng, 0.0)
    if est is not None:
        consider(est)
        cur_ms = mk(est)
    else:
        cur_extra = [set() for _ in range(n)]
        cur_ms = None
    best_extra = [set(s) for s in cur_extra]
    best_flat_ms = cur_ms
    stagn = 0
    it = 0
    while time.perf_counter() - t0 < budget and best_ms is not None and best_ms > lb:
        it += 1
        if cur_ms is None or stagn > 60:
            if rng.random() < 0.3 or best_flat_ms is None:
                cur_extra = [set() for _ in range(n)]
            else:
                cur_extra = [set(s) for s in best_extra]
            stagn = 0
        new_extra = [set(s) for s in cur_extra]
        res = compute(new_extra)
        if res is None:
            new_extra = [set() for _ in range(n)]
        else:
            e, tl = res
            m = max(e[i] + d[i] for i in range(n))
            pc = 0.1 + 0.3 * rng.random()
            pn = pc * 0.3
            for a in range(n):
                rem = []
                for b in new_extra[a]:
                    crit = (e[a] + tl[a] >= m) and (e[b] + tl[b] >= m) and (e[a] + d[a] >= e[b])
                    if rng.random() < (pc if crit else pn):
                        rem.append(b)
                for b in rem:
                    new_extra[a].discard(b)
        noise = rng.choice([0.0, 0.02, 0.05, 0.1, 0.2])
        st = flatten(new_extra, rng, noise)
        if st is None:
            stagn += 1
            continue
        m = mk(st)
        consider(st)
        # left-shift decode of the found schedule
        consider(_sgs(n, d, rel, preds, succ, req, caps, [(st[i], i) for i in range(n)]))
        if cur_ms is None or m <= cur_ms:
            if cur_ms is not None and m < cur_ms:
                stagn = 0
            else:
                stagn += 1
            cur_extra = new_extra
            cur_ms = m
            if best_flat_ms is None or m < best_flat_ms:
                best_flat_ms = m
                best_extra = [set(s) for s in new_extra]
        else:
            stagn += 1

    if best_start is None:
        best_start = _sgs(n, d, rel, preds, succ, req, caps, [(i,) for i in range(n)])
    state["output"] = {"status": "ok", "start": {ids[i]: int(best_start[i]) for i in range(n)}}
    return state

import time
import random


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    state["feasible"] = False
    return state


def _place(j, st, usage, dur, rel, preds, req, cap):
    t = rel[j]
    for p in preds[j]:
        f = st[p] + dur[p]
        if f > t:
            t = f
    d = dur[j]
    rq = req[j]
    if d > 0 and rq:
        while True:
            moved = False
            for r, u in rq:
                ur = usage[r]
                lim = cap[r] - u
                for s in range(t, t + d):
                    if ur[s] > lim:
                        t = s + 1
                        moved = True
                        break
                if moved:
                    break
            if not moved:
                break
    return t


def _commit(j, t, usage, dur, req, sign):
    d = dur[j]
    if d > 0:
        for r, u in req[j]:
            ur = usage[r]
            v = u * sign
            for s in range(t, t + d):
                ur[s] += v


def _sgs(order, n, dur, rel, preds, req, cap, H):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    start = [0] * n
    ms = 0
    for j in order:
        t = _place(j, start, usage, dur, rel, preds, req, cap)
        _commit(j, t, usage, dur, req, 1)
        start[j] = t
        if t + dur[j] > ms:
            ms = t + dur[j]
    return start, ms


def _bwd(start, ms, n, dur, rel, succs, req, cap, H, rank):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
    bs = [0] * n
    for j in order:
        lf = ms
        for s in succs[j]:
            if bs[s] < lf:
                lf = bs[s]
        d = dur[j]
        t = lf - d
        rq = req[j]
        if d > 0 and rq:
            while True:
                if t < 0:
                    return None
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t + d - 1, t - 1, -1):
                        if ur[s] > lim:
                            t = s - d
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        if t < 0:
            return None
        bs[j] = t
    return bs


def _improve(order, P):
    n = P["n"]
    dur = P["dur"]
    rel = P["rel"]
    preds = P["preds"]
    succs = P["succs"]
    req = P["req"]
    cap = P["cap"]
    H = P["H"]
    rank = P["rank"]
    st, ms = _sgs(order, n, dur, rel, preds, req, cap, H)
    for _ in range(3):
        bs = _bwd(st, ms, n, dur, rel, succs, req, cap, H, rank)
        if bs is None:
            break
        o2 = sorted(range(n), key=lambda j: (bs[j], rank[j]))
        st2, ms2 = _sgs(o2, n, dur, rel, preds, req, cap, H)
        if ms2 < ms:
            order, st, ms = o2, st2, ms2
        else:
            if ms2 == ms:
                order, st = o2, st2
            break
    order = sorted(range(n), key=lambda j: (st[j], rank[j]))
    return order, st, ms


def _validate(starts, n, dur, rel, preds, req, cap):
    if starts is None or len(starts) != n:
        return False
    for j in range(n):
        if starts[j] < rel[j]:
            return False
        for p in preds[j]:
            if starts[j] < starts[p] + dur[p]:
                return False
    events = {}
    for j in range(n):
        if dur[j] > 0:
            for t in range(starts[j], starts[j] + dur[j]):
                lst = events.get(t)
                if lst is None:
                    lst = [0] * len(cap)
                    events[t] = lst
                for r, u in req[j]:
                    lst[r] += u
    for t in events:
        lst = events[t]
        for r in range(len(cap)):
            if lst[r] > cap[r]:
                return False
    return True


def prepare(state, params):
    state["feasible"] = False
    state["small"] = False
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]
    n = len(jobs)
    ids = [str(jb.get("id")) for jb in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    dur = []
    rel = []
    preds = []
    req = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        pl = []
        seen = set()
        for p in (jb.get("after") or []):
            ps = str(p)
            if ps not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], ps))
            pi = idx[ps]
            if pi not in seen:
                seen.add(pi)
                pl.append(pi)
        preds.append(pl)
        rq = []
        for rn, u in (jb.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append([ridx[rn], u])
        req.append(rq)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if deg[j] > 0]
        return _infeasible(state, "precedence cycle among: " + ", ".join(rem[:8]))
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k
    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(es[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        if cap[r] <= 0:
            continue
        users = [j for j in range(n) if dur[j] > 0 and any(rr == r for rr, _ in req[j])]
        if not users:
            continue
        thr = sorted(set(es[j] for j in users))
        for th in thr:
            E = 0
            for j in users:
                if es[j] >= th:
                    for rr, u in req[j]:
                        if rr == r:
                            E += u * dur[j]
            lbv = th + (E + cap[r] - 1) // cap[r]
            if lbv > LB:
                LB = lbv
    H = max(rel) + sum(dur) + max(dur) + 5
    state["prep"] = {"n": n, "ids": ids, "dur": dur, "rel": rel, "preds": preds,
                     "succs": succs, "req": req, "cap": cap, "H": H, "rank": rank,
                     "topo": topo, "tail": tail, "indeg": indeg, "es": es, "LB": LB}
    state["best_ms"] = None
    state["best_st"] = None
    state["proven"] = False
    state["feasible"] = True
    state["small"] = n <= 16
    return state


def ga_phase(state, params):
    t0 = time.perf_counter()
    budget = 0.45
    P = state["prep"]
    n = P["n"]
    dur = P["dur"]
    rel = P["rel"]
    preds = P["preds"]
    succs = P["succs"]
    req = P["req"]
    tail = P["tail"]
    indeg = P["indeg"]
    es = P["es"]
    LB = P["LB"]
    topo = P["topo"]

    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= (1 << s) | desc[s]
        desc[j] = m
    nsucc = [bin(desc[j]).count("1") for j in range(n)]
    grpw = [dur[j] + sum(dur[s] for s in succs[j]) for j in range(n)]
    work = [dur[j] * (1 + sum(u for _, u in req[j])) for j in range(n)]
    rng = random.Random(12345)

    def gen_order(prio, noise):
        d = indeg[:]
        elig = [j for j in range(n) if d[j] == 0]
        out = []
        while elig:
            if noise <= 0:
                bi = 0
                bv = None
                for k, j in enumerate(elig):
                    v = (prio[j], tail[j], -j)
                    if bv is None or v > bv:
                        bv = v
                        bi = k
            else:
                mn = min(prio[j] for j in elig)
                ws = [(prio[j] - mn + 1.0) ** noise for j in elig]
                tot = sum(ws)
                x = rng.random() * tot
                bi = len(elig) - 1
                acc = 0.0
                for k, w in enumerate(ws):
                    acc += w
                    if x <= acc:
                        bi = k
                        break
            j = elig.pop(bi)
            out.append(j)
            for s in succs[j]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    best = {"ms": None, "st": None}

    def consider(st, ms):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]

    def timeout():
        return time.perf_counter() - t0 > budget

    pop = []
    seen = set()
    rules = [
        tail,
        [-es[j] for j in range(n)],
        nsucc,
        grpw,
        [tail[j] * 100 + nsucc[j] for j in range(n)],
        [tail[j] - es[j] for j in range(n)],
        work,
        dur,
    ]
    for pr in rules:
        o = gen_order(pr, 0)
        o, st, ms = _improve(o, P)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))
        if best["ms"] <= LB or timeout():
            break

    PS = 30
    tries = 0
    while len(pop) < PS and best["ms"] > LB and not timeout() and tries < 200:
        tries += 1
        pr = rules[rng.randrange(len(rules))]
        o = gen_order(pr, rng.choice([1.0, 2.0, 3.0]))
        o, st, ms = _improve(o, P)
        consider(st, ms)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))

    predset = [set(preds[j]) for j in range(n)]
    stagn = 0
    while best["ms"] > LB and not timeout() and len(pop) >= 2:
        a1 = pop[rng.randrange(len(pop))]
        b1 = pop[rng.randrange(len(pop))]
        m = (a1 if a1[0] <= b1[0] else b1)[1]
        a2 = pop[rng.randrange(len(pop))]
        b2 = pop[rng.randrange(len(pop))]
        f = (a2 if a2[0] <= b2[0] else b2)[1]
        q = rng.randrange(1, n) if n > 1 else 1
        head = m[:q]
        hs = set(head)
        child = head + [j for j in f if j not in hs]
        nm = rng.randrange(0, 3)
        for _ in range(nm):
            if n < 2:
                break
            i = rng.randrange(n - 1)
            a, b = child[i], child[i + 1]
            if a not in predset[b]:
                child[i], child[i + 1] = b, a
        if rng.random() < 0.3 and n > 2:
            i = rng.randrange(n)
            j = child[i]
            child.pop(i)
            lo = 0
            hi = len(child)
            for k, x in enumerate(child):
                if x in predset[j]:
                    lo = k + 1
            for k in range(len(child) - 1, -1, -1):
                if j in predset[child[k]]:
                    hi = k
            if lo > hi:
                lo = hi
            child.insert(rng.randint(lo, hi), j)
        o, st, ms = _improve(child, P)
        prev = best["ms"]
        consider(st, ms)
        if best["ms"] < prev:
            stagn = 0
        else:
            stagn += 1
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            wi = max(range(len(pop)), key=lambda k: pop[k][0])
            if ms <= pop[wi][0]:
                pop[wi] = (ms, o)
        if stagn > 300:
            stagn = 0
            pop.sort(key=lambda x: x[0])
            pop = pop[: max(2, len(pop) // 3)]
            while len(pop) < PS and not timeout():
                pr = rules[rng.randrange(len(rules))]
                o = gen_order(pr, rng.choice([1.0, 2.0, 4.0]))
                o, st, ms = _improve(o, P)
                consider(st, ms)
                pop.append((ms, o))

    state["best_ms"] = best["ms"]
    state["best_st"] = best["st"]
    state["proven"] = best["ms"] is not None and best["ms"] <= LB
    return state


def _bnb(n, dur, rel, preds, succs, req, cap, H, rank, topo, tail, indeg,
         best_ms, best_st, deadline):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    st = [0] * n
    placed = [False] * n
    deg = indeg[:]
    remE = [0] * R
    for j in range(n):
        if dur[j] > 0:
            for r, u in req[j]:
                remE[r] += u * dur[j]
    esd = [0] * n
    inc = {"ms": best_ms, "st": best_st[:] if best_st else None,
           "cnt": 0, "stop": False}

    def dfs(k, s_last, r_last, cur_ms):
        if inc["stop"]:
            return
        if k == n:
            if cur_ms < inc["ms"]:
                inc["ms"] = cur_ms
                inc["st"] = st[:]
            return
        inc["cnt"] += 1
        if (inc["cnt"] & 127) == 0 and time.perf_counter() > deadline:
            inc["stop"] = True
            return
        ub = inc["ms"] - 1
        if cur_ms > ub:
            return
        for j in topo:
            if placed[j]:
                continue
            t = rel[j]
            if s_last > t:
                t = s_last
            for p in preds[j]:
                if placed[p]:
                    f = st[p] + dur[p]
                else:
                    f = esd[p] + dur[p]
                if f > t:
                    t = f
            esd[j] = t
            if t + tail[j] > ub:
                return
        for r in range(R):
            E = remE[r]
            if E > 0:
                if ub <= s_last:
                    return
                free = cap[r] * (ub - s_last) - sum(usage[r][s_last:ub])
                if free < E:
                    return
        cands = []
        for j in range(n):
            if placed[j] or deg[j] != 0:
                continue
            t = _place(j, st, usage, dur, rel, preds, req, cap)
            if t < s_last or (t == s_last and rank[j] < r_last):
                continue
            if t + tail[j] > ub:
                continue
            cands.append((t + tail[j], t, -dur[j], j))
        cands.sort()
        for _, t, _, j in cands:
            if inc["stop"]:
                return
            if t + tail[j] > inc["ms"] - 1:
                continue
            d = dur[j]
            _commit(j, t, usage, dur, req, 1)
            if d > 0:
                for r, u in req[j]:
                    remE[r] -= u * d
            st[j] = t
            placed[j] = True
            for s in succs[j]:
                deg[s] -= 1
            nm = cur_ms if cur_ms > t + d else t + d
            dfs(k + 1, t, rank[j], nm)
            for s in succs[j]:
                deg[s] += 1
            placed[j] = False
            _commit(j, t, usage, dur, req, -1)
            if d > 0:
                for r, u in req[j]:
                    remE[r] += u * d

    dfs(0, 0, -1, 0)
    return inc["ms"], inc["st"], (not inc["stop"])


def bnb_phase(state, params):
    t0 = time.perf_counter()
    if state.get("proven") or state.get("best_st") is None:
        return state
    P = state["prep"]
    n = P["n"]
    try:
        bms, bst, done = _bnb(n, P["dur"], P["rel"], P["preds"], P["succs"], P["req"],
                              P["cap"], P["H"], P["rank"], P["topo"], P["tail"],
                              P["indeg"], state["best_ms"], state["best_st"], t0 + 0.45)
        if bst is not None and bms < state["best_ms"]:
            if _validate(bst, n, P["dur"], P["rel"], P["preds"], P["req"], P["cap"]):
                state["best_ms"] = bms
                state["best_st"] = list(bst)
        if done:
            state["proven"] = True
    except Exception:
        pass
    return state


def lns_phase(state, params):
    t0 = time.perf_counter()
    if state.get("proven") or state.get("best_st") is None:
        return state
    budget = 0.15 if state.get("small") else 0.6
    deadline = t0 + budget
    P = state["prep"]
    n = P["n"]
    if n < 3:
        return state
    dur = P["dur"]
    rel = P["rel"]
    preds = P["preds"]
    succs = P["succs"]
    req = P["req"]
    cap = P["cap"]
    H = P["H"]
    rank = P["rank"]
    tail = P["tail"]
    LB = P["LB"]
    R = len(cap)
    rng = random.Random(777)
    try:
        best_ms = state["best_ms"]
        best_st = list(state["best_st"])
        cur_order = sorted(range(n), key=lambda j: (best_st[j], rank[j]))
        cst, cur_ms = _sgs(cur_order, n, dur, rel, preds, req, cap, H)
        if cur_ms < best_ms and _validate(cst, n, dur, rel, preds, req, cap):
            best_ms = cur_ms
            best_st = cst[:]
        stagn = 0
        while time.perf_counter() < deadline and best_ms > LB:
            k = min(n, rng.choice([4, 5, 5, 6, 6, 7]))
            a = rng.randrange(0, n - k + 1)
            pre = cur_order[:a]
            W = cur_order[a:a + k]
            S = cur_order[a + k:]
            usage = [[0] * H for _ in range(R)]
            stt = [0] * n
            pre_ms = 0
            for j in pre:
                t = _place(j, stt, usage, dur, rel, preds, req, cap)
                _commit(j, t, usage, dur, req, 1)
                stt[j] = t
                if t + dur[j] > pre_ms:
                    pre_ms = t + dur[j]
            inW = set(W)
            wdeg = {}
            for j in W:
                wdeg[j] = sum(1 for p in preds[j] if p in inW)
            placedW = {j: False for j in W}
            path = []
            res = {"lim": cur_ms, "perm": None, "ms": None, "eq": None,
                   "leaves": 0, "nodes": 0, "stop": False}

            def leaf(curmax):
                u2 = [row[:] for row in usage]
                ms = curmax
                lim = res["lim"]
                for j in S:
                    t = _place(j, stt, u2, dur, rel, preds, req, cap)
                    if t + tail[j] > lim:
                        return None
                    _commit(j, t, u2, dur, req, 1)
                    stt[j] = t
                    if t + dur[j] > ms:
                        ms = t + dur[j]
                if ms > lim:
                    return None
                return ms

            def dfs(depth, curmax):
                if res["stop"]:
                    return
                if depth == k:
                    res["leaves"] += 1
                    ms = leaf(curmax)
                    if ms is not None:
                        if ms < cur_ms:
                            res["ms"] = ms
                            res["perm"] = path[:]
                            res["lim"] = ms - 1
                        elif res["eq"] is None and path != W:
                            res["eq"] = path[:]
                    if res["leaves"] >= 40:
                        res["stop"] = True
                    return
                res["nodes"] += 1
                if res["nodes"] > 400:
                    res["stop"] = True
                    return
                if (res["nodes"] & 31) == 0 and time.perf_counter() > deadline:
                    res["stop"] = True
                    return
                cands = []
                for j in W:
                    if placedW[j] or wdeg[j] != 0:
                        continue
                    t = _place(j, stt, usage, dur, rel, preds, req, cap)
                    if t + tail[j] > res["lim"]:
                        continue
                    cands.append((t, t + tail[j], j))
                cands.sort()
                for t, _, j in cands:
                    if res["stop"]:
                        return
                    if t + tail[j] > res["lim"]:
                        continue
                    _commit(j, t, usage, dur, req, 1)
                    stt[j] = t
                    placedW[j] = True
                    path.append(j)
                    for s in succs[j]:
                        if s in wdeg:
                            wdeg[s] -= 1
                    fin = t + dur[j]
                    dfs(depth + 1, curmax if curmax > fin else fin)
                    for s in succs[j]:
                        if s in wdeg:
                            wdeg[s] += 1
                    path.pop()
                    placedW[j] = False
                    _commit(j, t, usage, dur, req, -1)

            dfs(0, pre_ms)
            if res["perm"] is not None:
                new_order = pre + res["perm"] + S
                o, st, ms = _improve(new_order, P)
                if ms <= res["ms"]:
                    cur_order, cur_ms = o, ms
                else:
                    cur_order = new_order
                    st, ms = _sgs(new_order, n, dur, rel, preds, req, cap, H)
                    cur_ms = ms
                if ms < best_ms and _validate(st, n, dur, rel, preds, req, cap):
                    best_ms = ms
                    best_st = st[:]
                stagn = 0
            else:
                stagn += 1
                if res["eq"] is not None and rng.random() < 0.5:
                    cur_order = pre + res["eq"] + S
                if stagn > 4 * n:
                    stagn = 0
                    bo = sorted(range(n), key=lambda j: (best_st[j], rank[j]))
                    for _ in range(max(2, n // 5)):
                        i = rng.randrange(n - 1)
                        x, y = bo[i], bo[i + 1]
                        if x not in preds[y]:
                            bo[i], bo[i + 1] = y, x
                    o, st, ms = _improve(bo, P)
                    cur_order, cur_ms = o, ms
                    if ms < best_ms and _validate(st, n, dur, rel, preds, req, cap):
                        best_ms = ms
                        best_st = st[:]
        if best_ms < state["best_ms"] and _validate(best_st, n, dur, rel, preds, req, cap):
            state["best_ms"] = best_ms
            state["best_st"] = best_st
    except Exception:
        pass
    return state


def finalize(state, params):
    P = state["prep"]
    n = P["n"]
    dur = P["dur"]
    rel = P["rel"]
    preds = P["preds"]
    st = state.get("best_st")
    if st is None or not _validate(st, n, dur, rel, preds, P["req"], P["cap"]):
        st = [0] * n
        t = 0
        for j in P["topo"]:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
    ids = P["ids"]
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

import heapq, math, random, time
from collections import deque


def _validate(inp):
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    ids = [j["id"] for j in jobs]
    idset = set(ids)
    for j in jobs:
        for p in j.get("after", []) or []:
            if p not in idset:
                return "job %s references unknown job %s" % (j["id"], p)
        for r, u in (j.get("requires", {}) or {}).items():
            if r not in res:
                return "job %s references unknown resource %s" % (j["id"], r)
            if u > res[r]:
                return "job %s needs %s units of %s > capacity %s" % (j["id"], u, r, res[r])
    idx = {}
    for i, x in enumerate(ids):
        idx[x] = i
    n = len(jobs)
    indeg = [0] * n
    succ = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in set(j.get("after", []) or []):
            succ[idx[p]].append(i)
            indeg[i] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    cnt = 0
    while q:
        u = q.popleft()
        cnt += 1
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    if cnt < n:
        return "precedence cycle detected"
    return None


def solve(state, params):
    t0 = time.perf_counter()
    budget = 1.05
    inp = state["input"]
    reason = _validate(inp)
    if reason:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    jobs = inp.get("jobs", []) or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list((inp.get("resources", {}) or {}).keys())
    R = len(rnames)
    rix = {r: i for i, r in enumerate(rnames)}
    cap = [int(inp["resources"][r]) for r in rnames]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    dur = [int(j.get("duration", 0)) for j in jobs]
    rel = [int(j.get("release", 0)) for j in jobs]
    preds = [sorted(set(idx[p] for p in (j.get("after", []) or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    reqs = []
    for j in jobs:
        lst = []
        for r, u in (j.get("requires", {}) or {}).items():
            u = int(u)
            if u > 0:
                lst.append((rix[r], u))
        reqs.append(lst)
    # topo order
    indeg = [len(preds[i]) for i in range(n)]
    q = deque(i for i in range(n) if indeg[i] == 0)
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    # CPM
    ES = [0] * n
    for u in topo:
        e = rel[u]
        for p in preds[u]:
            e = max(e, ES[p] + dur[p])
        ES[u] = e
    cpm = max(ES[i] + dur[i] for i in range(n))
    LB = cpm
    for r in range(R):
        en = sum(dur[i] * u for i in range(n) for (rr, u) in reqs[i] if rr == r)
        if en > 0:
            mr = min(rel[i] for i in range(n) for (rr, u) in reqs[i] if rr == r and dur[i] > 0)
            LB = max(LB, mr + (en + cap[r] - 1) // cap[r])
    maxd = max(dur) if dur else 0
    H = max(rel) + sum(dur) + maxd + 2

    def tail_ls(T):
        LS = [0] * n
        for u in reversed(topo):
            lf = T
            for s in succs[u]:
                lf = min(lf, LS[s])
            LS[u] = lf - dur[u]
        return LS

    def order_from(prio):
        deg = [len(preds[i]) for i in range(n)]
        h = [(prio[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, u = heapq.heappop(h)
            out.append(u)
            for v in succs[u]:
                deg[v] -= 1
                if deg[v] == 0:
                    heapq.heappush(h, (prio[v], v))
        return out

    def sgs(order):
        usage = [[0] * H for _ in range(R)]
        st = [0] * n
        for u in order:
            e = rel[u]
            for p in preds[u]:
                f = st[p] + dur[p]
                if f > e:
                    e = f
            d = dur[u]
            rq = reqs[u]
            if d > 0 and rq:
                t = e
                while True:
                    ok = True
                    for (r, a) in rq:
                        ur = usage[r]
                        c = cap[r] - a
                        for x in range(t + d - 1, t - 1, -1):
                            if ur[x] > c:
                                ok = False
                                t = x + 1
                                break
                        if not ok:
                            break
                    if ok:
                        break
                for (r, a) in rq:
                    ur = usage[r]
                    for x in range(t, t + d):
                        ur[x] += a
                e = t
            st[u] = e
        return st

    def mk(st):
        return max(st[i] + dur[i] for i in range(n))

    def improve(st):
        # forward-backward justification: order by finish desc -> backward pass, then forward by backward start
        best = st
        bm = mk(st)
        for _ in range(3):
            fin = [-(best[i] + dur[i]) for i in range(n)]
            # backward SGS (reverse network, ignoring releases) to get order
            bord = []
            deg = [len(succs[i]) for i in range(n)]
            h = [(fin[i], i) for i in range(n) if deg[i] == 0]
            heapq.heapify(h)
            while h:
                _, u = heapq.heappop(h)
                bord.append(u)
                for v in preds[u]:
                    deg[v] -= 1
                    if deg[v] == 0:
                        heapq.heappush(h, (fin[v], v))
            usage = [[0] * H for _ in range(R)]
            bst = [0] * n  # time from end
            for u in bord:
                e = 0
                for s in succs[u]:
                    f = bst[s] + dur[s]
                    if f > e:
                        e = f
                d = dur[u]
                if d > 0 and reqs[u]:
                    t = e
                    while True:
                        ok = True
                        for (r, a) in reqs[u]:
                            ur = usage[r]
                            c = cap[r] - a
                            for x in range(t + d - 1, t - 1, -1):
                                if ur[x] > c:
                                    ok = False
                                    t = x + 1
                                    break
                            if not ok:
                                break
                        if ok:
                            break
                    for (r, a) in reqs[u]:
                        for x in range(t, t + d):
                            usage[r][x] += a
                    e = t
                bst[u] = e
            # forward start priority = -(bst+dur) (later finish-from-end = earlier start)
            prio = [-(bst[i] + dur[i]) for i in range(n)]
            ns = sgs(order_from([(prio[i], best[i]) for i in range(n)]))
            m = mk(ns)
            if m < bm:
                best, bm = ns, m
            else:
                break
        return best

    best = None
    bestm = None

    def consider(st):
        nonlocal best, bestm
        st = improve(st)
        m = mk(st)
        if bestm is None or m < bestm:
            best, bestm = st, m

    LS0 = tail_ls(cpm)
    nsucc = [0] * n
    for u in reversed(topo):
        s = set()
        for v in succs[u]:
            s.add(v)
        nsucc[u] = len(s) + sum(nsucc[v] for v in succs[u])
    rules = [
        [(LS0[i], ES[i]) for i in range(n)],
        [(ES[i], LS0[i]) for i in range(n)],
        [(LS0[i] - ES[i], -dur[i]) for i in range(n)],
        [(-nsucc[i], LS0[i]) for i in range(n)],
        [(rel[i], LS0[i]) for i in range(n)],
    ]
    for pr in rules:
        consider(sgs(order_from(pr)))

    rng = random.Random(12345)
    # Lagrangian price coordination
    lam = [[0.0] * H for _ in range(R)]
    step = 1.0
    it = 0
    stall = 0
    lastm = bestm
    while bestm > LB and time.perf_counter() - t0 < budget:
        it += 1
        T = max(LB, bestm - 1)
        LS = tail_ls(T)
        # job cost prefix sums
        rs = [0] * n
        usage = [[0] * H for _ in range(R)]
        for u in topo:
            e = rel[u]
            for p in preds[u]:
                f = rs[p] + dur[p]
                if f > e:
                    e = f
            d = dur[u]
            hi = max(e, LS[u])
            if d == 0 or not reqs[u]:
                s = e
            else:
                hi = min(hi, H - d - 1)
                if hi < e:
                    hi = e
                c = [0.0] * (hi + d + 1)
                for (r, a) in reqs[u]:
                    lr = lam[r]
                    w = a / cap[r]
                    for x in range(e, hi + d):
                        c[x] += w * lr[x]
                pre = [0.0] * (hi + d + 2)
                acc = 0.0
                for x in range(e, hi + d):
                    acc += c[x]
                    pre[x + 1] = acc
                bs = e
                bv = None
                noise = 0.02 * rng.random()
                for s0 in range(e, hi + 1):
                    v = pre[s0 + d] - pre[s0] + (0.001 + noise) * (s0 - e)
                    if bv is None or v < bv - 1e-12:
                        bv = v
                        bs = s0
                s = bs
                for (r, a) in reqs[u]:
                    ur = usage[r]
                    for x in range(s, s + d):
                        ur[x] += a
            rs[u] = s
        # decode
        pr = [(rs[i] + 0.3 * rng.random(), LS[i]) for i in range(n)]
        consider(sgs(order_from(pr)))
        # subgradient update
        over = 0
        for r in range(R):
            ur = usage[r]
            lr = lam[r]
            c = cap[r]
            for x in range(H):
                g = ur[x] - c
                if g > 0:
                    over += g
                    lr[x] += step * g / c
                elif lr[x] > 0:
                    lr[x] = max(0.0, lr[x] + step * 0.25 * g / c)
        if bestm < lastm:
            lastm = bestm
            stall = 0
        else:
            stall += 1
        if over == 0:
            step *= 0.9
        if stall > 30:
            stall = 0
            step = 0.5 + rng.random()
            for r in range(R):
                lr = lam[r]
                for x in range(H):
                    lr[x] *= rng.random()
        if it % 7 == 0:
            # occasional perturbed incumbent restart
            pr = [(best[i] + rng.random() * 2.0, LS[i]) for i in range(n)]
            consider(sgs(order_from(pr)))

    # final safety check
    st = best
    ok = True
    for i in range(n):
        if st[i] < rel[i]:
            ok = False
        for p in preds[i]:
            if st[i] < st[p] + dur[p]:
                ok = False
    if not ok:
        st = sgs(order_from([(ES[i], i) for i in range(n)]))
    state["output"] = {"status": "ok", "start": {jobs[i]["id"]: int(st[i]) for i in range(n)}}
    return state

import time
import random
import math


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def _sgs(order, n, dur, rel, preds, req, cap, H):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    start = [0] * n
    ms = 0
    for j in order:
        t = rel[j]
        for p in preds[j]:
            f = start[p] + dur[p]
            if f > t:
                t = f
        d = dur[j]
        rq = req[j]
        if d > 0 and rq:
            while True:
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t, t + d):
                        if ur[s] > lim:
                            t = s + 1
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        start[j] = t
        if t + d > ms:
            ms = t + d
    return start, ms


def _bwd(start, ms, n, dur, rel, succs, req, cap, H, rank):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    order = sorted(range(n), key=lambda j: (-(start[j] + dur[j]), -rank[j]))
    bs = [0] * n
    for j in order:
        lf = ms
        for s in succs[j]:
            if bs[s] < lf:
                lf = bs[s]
        d = dur[j]
        t = lf - d
        rq = req[j]
        if d > 0 and rq:
            while True:
                if t < 0:
                    return None
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t + d - 1, t - 1, -1):
                        if ur[s] > lim:
                            t = s - d
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
            for r, u in rq:
                ur = usage[r]
                for s in range(t, t + d):
                    ur[s] += u
        if t < 0:
            return None
        bs[j] = t
    return bs


def _validate(starts, n, dur, rel, preds, req, cap):
    if starts is None or len(starts) != n:
        return False
    for j in range(n):
        if starts[j] < rel[j]:
            return False
        for p in preds[j]:
            if starts[j] < starts[p] + dur[p]:
                return False
    events = {}
    for j in range(n):
        if dur[j] > 0:
            for t in range(starts[j], starts[j] + dur[j]):
                lst = events.get(t)
                if lst is None:
                    lst = [0] * len(cap)
                    events[t] = lst
                for r, u in req[j]:
                    lst[r] += u
    for t in events:
        lst = events[t]
        for r in range(len(cap)):
            if lst[r] > cap[r]:
                return False
    return True


def _bnb(n, dur, rel, preds, succs, req, cap, H, rank, topo, tail, indeg,
         best_ms, best_st, deadline, LB):
    R = len(cap)
    usage = [[0] * H for _ in range(R)]
    st = [0] * n
    placed = [False] * n
    deg = indeg[:]
    remE = [0] * R
    for j in range(n):
        if dur[j] > 0:
            for r, u in req[j]:
                remE[r] += u * dur[j]
    esd = [0] * n
    inc = {"ms": best_ms, "st": best_st[:] if best_st else None,
           "cnt": 0, "stop": False, "lbhit": False}

    def place_time(j):
        t = rel[j]
        for p in preds[j]:
            f = st[p] + dur[p]
            if f > t:
                t = f
        d = dur[j]
        rq = req[j]
        if d > 0 and rq:
            while True:
                moved = False
                for r, u in rq:
                    ur = usage[r]
                    lim = cap[r] - u
                    for s in range(t, t + d):
                        if ur[s] > lim:
                            t = s + 1
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    break
        return t

    def dfs(k, s_last, r_last, cur_ms):
        if inc["stop"]:
            return
        if k == n:
            if cur_ms < inc["ms"]:
                inc["ms"] = cur_ms
                inc["st"] = st[:]
                if cur_ms <= LB:
                    inc["stop"] = True
                    inc["lbhit"] = True
            return
        inc["cnt"] += 1
        if (inc["cnt"] & 127) == 0 and time.perf_counter() > deadline:
            inc["stop"] = True
            return
        ub = inc["ms"] - 1
        if cur_ms > ub:
            return
        for j in topo:
            if placed[j]:
                continue
            t = rel[j]
            if s_last > t:
                t = s_last
            for p in preds[j]:
                if placed[p]:
                    f = st[p] + dur[p]
                else:
                    f = esd[p] + dur[p]
                if f > t:
                    t = f
            esd[j] = t
            if t + tail[j] > ub:
                return
        for r in range(R):
            E = remE[r]
            if E > 0:
                if ub <= s_last:
                    return
                free = cap[r] * (ub - s_last) - sum(usage[r][s_last:ub])
                if free < E:
                    return
        cands = []
        for j in range(n):
            if placed[j] or deg[j] != 0:
                continue
            t = place_time(j)
            if t < s_last or (t == s_last and rank[j] < r_last):
                continue
            if t + tail[j] > ub:
                continue
            cands.append((t + tail[j], t, -dur[j], j))
        cands.sort()
        for _, t, _, j in cands:
            if inc["stop"]:
                return
            if t + tail[j] > inc["ms"] - 1:
                continue
            d = dur[j]
            rq = req[j]
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] += u
                    remE[r] -= u * d
            st[j] = t
            placed[j] = True
            for s in succs[j]:
                deg[s] -= 1
            nm = cur_ms if cur_ms > t + d else t + d
            dfs(k + 1, t, rank[j], nm)
            for s in succs[j]:
                deg[s] += 1
            placed[j] = False
            if d > 0:
                for r, u in rq:
                    ur = usage[r]
                    for s in range(t, t + d):
                        ur[s] -= u
                    remE[r] += u * d

    dfs(0, 0, -1, 0)
    proven = (not inc["stop"]) or inc["lbhit"]
    return inc["ms"], inc["st"], proven


def solve(state, params):
    t0 = time.perf_counter()
    GA1_END = 0.42
    BNB_END = 0.58
    TOTAL_END = 1.15
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [int(resources[r]) for r in rnames]

    n = len(jobs)
    ids = [str(jb.get("id")) for jb in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i

    dur = []
    rel = []
    preds = []
    req = []
    for i, jb in enumerate(jobs):
        dur.append(max(0, int(jb.get("duration", 0) or 0)))
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        pl = []
        seen0 = set()
        for p in (jb.get("after") or []):
            ps = str(p)
            if ps not in idx:
                return _infeasible(state, "job %s references unknown job %s" % (ids[i], ps))
            pi = idx[ps]
            if pi not in seen0:
                seen0.add(pi)
                pl.append(pi)
        preds.append(pl)
        rq = []
        for rn, u in (jb.get("requires") or {}).items():
            if rn not in ridx:
                return _infeasible(state, "job %s references unknown resource %s" % (ids[i], rn))
            u = int(u)
            if u > cap[ridx[rn]]:
                return _infeasible(state, "job %s needs %d of %s, capacity %d" % (ids[i], u, rn, cap[ridx[rn]]))
            if u > 0:
                rq.append((ridx[rn], u))
        req.append(rq)

    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    stack = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            deg[s] -= 1
            if deg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        rem = [ids[j] for j in range(n) if deg[j] > 0]
        return _infeasible(state, "precedence cycle among: " + ", ".join(rem[:8]))

    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state

    rank = [0] * n
    for k, j in enumerate(topo):
        rank[j] = k

    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + dur[p] > t:
                t = es[p] + dur[p]
        es[j] = t
    tail = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            if tail[s] > m:
                m = tail[s]
        tail[j] = dur[j] + m
    LB = max(es[j] + tail[j] for j in range(n))
    for r in range(len(cap)):
        if cap[r] <= 0:
            continue
        users = []
        for j in range(n):
            if dur[j] > 0:
                for rr, u in req[j]:
                    if rr == r:
                        users.append((j, u))
        if not users:
            continue
        thr = sorted(set(es[j] for j, _ in users))
        for th in thr:
            E = 0
            mt = None
            for j, u in users:
                if es[j] >= th:
                    E += u * dur[j]
                    q = tail[j] - dur[j]
                    if mt is None or q < mt:
                        mt = q
            if mt is None:
                mt = 0
            lbv = th + (E + cap[r] - 1) // cap[r] + mt
            if lbv > LB:
                LB = lbv

    H = max(rel) + sum(dur) + max(dur) + 5
    R = len(cap)

    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= (1 << s) | desc[s]
        desc[j] = m
    nsucc = [bin(desc[j]).count("1") for j in range(n)]
    grpw = [dur[j] + sum(dur[s] for s in succs[j]) for j in range(n)]
    work = [dur[j] * (1 + sum(u for _, u in req[j])) for j in range(n)]
    predset = [set(preds[j]) for j in range(n)]

    rng = random.Random(12345)

    def elapsed():
        return time.perf_counter() - t0

    def gen_order(prio, noise):
        d = indeg[:]
        elig = [j for j in range(n) if d[j] == 0]
        out = []
        while elig:
            if noise <= 0:
                bi = 0
                bv = None
                for k, j in enumerate(elig):
                    v = (prio[j], tail[j], -j)
                    if bv is None or v > bv:
                        bv = v
                        bi = k
            else:
                mn = min(prio[j] for j in elig)
                ws = [(prio[j] - mn + 1.0) ** noise for j in elig]
                tot = sum(ws)
                x = rng.random() * tot
                bi = len(elig) - 1
                acc = 0.0
                for k, w in enumerate(ws):
                    acc += w
                    if x <= acc:
                        bi = k
                        break
            j = elig.pop(bi)
            out.append(j)
            for s in succs[j]:
                d[s] -= 1
                if d[s] == 0:
                    elig.append(s)
        return out

    def improve(order):
        st, ms = _sgs(order, n, dur, rel, preds, req, cap, H)
        for _ in range(3):
            bs = _bwd(st, ms, n, dur, rel, succs, req, cap, H, rank)
            if bs is None:
                break
            o2 = sorted(range(n), key=lambda j: (bs[j], rank[j]))
            st2, ms2 = _sgs(o2, n, dur, rel, preds, req, cap, H)
            if ms2 < ms:
                order, st, ms = o2, st2, ms2
            else:
                if ms2 == ms:
                    order, st = o2, st2
                break
        order = sorted(range(n), key=lambda j: (st[j], rank[j]))
        return order, st, ms

    best = {"ms": None, "st": None, "order": None}

    def consider(st, ms, order):
        if best["ms"] is None or ms < best["ms"]:
            best["ms"] = ms
            best["st"] = st[:]
            best["order"] = list(order)
            return True
        return False

    pop = []
    seen = set()
    rules = [
        tail,
        [-es[j] for j in range(n)],
        nsucc,
        grpw,
        [tail[j] * 100 + nsucc[j] for j in range(n)],
        [tail[j] - es[j] for j in range(n)],
        work,
        dur,
        [-rel[j] for j in range(n)],
    ]
    for pr in rules:
        o = gen_order(pr, 0)
        o, st, ms = improve(o)
        consider(st, ms, o)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))
        if best["ms"] <= LB or elapsed() > GA1_END:
            break

    P = 30
    tries = 0
    while len(pop) < P and best["ms"] > LB and elapsed() < GA1_END and tries < 200:
        tries += 1
        pr = rules[rng.randrange(len(rules))]
        o = gen_order(pr, rng.choice([1.0, 2.0, 3.0]))
        o, st, ms = improve(o)
        consider(st, ms, o)
        key = tuple(o)
        if key not in seen:
            seen.add(key)
            pop.append((ms, o))

    def window(lst, j):
        lo = 0
        hi = len(lst)
        for k, x in enumerate(lst):
            if x in predset[j]:
                lo = k + 1
        for k in range(len(lst) - 1, -1, -1):
            if j in predset[lst[k]]:
                hi = k
        if lo > hi:
            lo = hi
        return lo, hi

    def insert_to_pop(ms, o):
        key = tuple(o)
        if key in seen:
            return
        seen.add(key)
        if len(pop) < P:
            pop.append((ms, o))
            return
        wi = max(range(len(pop)), key=lambda k: pop[k][0])
        if ms <= pop[wi][0]:
            pop[wi] = (ms, o)

    def local_search(deadline):
        base = best["order"]
        if base is None or n < 3:
            return
        for _ in range(min(2 * n, 60)):
            if time.perf_counter() - t0 > deadline or best["ms"] <= LB:
                return
            lst = list(best["order"])
            i = rng.randrange(n)
            j = lst.pop(i)
            lo, hi = window(lst, j)
            lst.insert(rng.randint(lo, hi), j)
            o, st, ms = improve(lst)
            if consider(st, ms, o):
                insert_to_pop(ms, o)

    def run_ga(deadline, stop_stagn):
        stagn = 0
        it = 0
        while best["ms"] > LB and elapsed() < deadline and len(pop) >= 2:
            it += 1

            def tour():
                a = pop[rng.randrange(len(pop))]
                b = pop[rng.randrange(len(pop))]
                return a if a[0] <= b[0] else b
            m = tour()[1]
            f = tour()[1]
            q = rng.randrange(1, n) if n > 1 else 1
            head = m[:q]
            hs = set(head)
            child = head + [j for j in f if j not in hs]
            nm = rng.randrange(0, 3)
            for _ in range(nm):
                if n < 2:
                    break
                i = rng.randrange(n - 1)
                a, b = child[i], child[i + 1]
                if a not in predset[b]:
                    child[i], child[i + 1] = b, a
            if rng.random() < 0.3 and n > 2:
                i = rng.randrange(n)
                j = child.pop(i)
                lo, hi = window(child, j)
                child.insert(rng.randint(lo, hi), j)
            o, st, ms = improve(child)
            if consider(st, ms, o):
                stagn = 0
            else:
                stagn += 1
            insert_to_pop(ms, o)
            if it % 150 == 0:
                local_search(deadline)
            if stop_stagn is not None and stagn > stop_stagn:
                return
            if stagn > 300:
                stagn = 0
                local_search(deadline)
                pop.sort(key=lambda x: x[0])
                keep = pop[: max(2, len(pop) // 3)]
                del pop[:]
                pop.extend(keep)
                while len(pop) < P and elapsed() < deadline:
                    pr = rules[rng.randrange(len(rules))]
                    o = gen_order(pr, rng.choice([1.0, 2.0, 4.0]))
                    o, st, ms = improve(o)
                    consider(st, ms, o)
                    pop.append((ms, o))

    # ---------- exact-window LNS ----------
    def lns_window(order, p, k, limit, cur_ms, deadline):
        usage = [[0] * H for _ in range(R)]
        st = [0] * n

        def ptime(j):
            t = rel[j]
            for q in preds[j]:
                f = st[q] + dur[q]
                if f > t:
                    t = f
            d = dur[j]
            rq = req[j]
            if d > 0 and rq:
                while True:
                    moved = False
                    for r, u in rq:
                        ur = usage[r]
                        lim = cap[r] - u
                        for s in range(t, t + d):
                            if ur[s] > lim:
                                t = s + 1
                                moved = True
                                break
                        if moved:
                            break
                    if not moved:
                        break
            return t

        def put(j, t, sgn):
            d = dur[j]
            if d > 0:
                for r, u in req[j]:
                    ur = usage[r]
                    v = u * sgn
                    for s in range(t, t + d):
                        ur[s] += v

        pre_ms = 0
        for j in order[:p]:
            t = ptime(j)
            put(j, t, 1)
            st[j] = t
            if t + dur[j] > pre_ms:
                pre_ms = t + dur[j]
        seg = order[p:p + k]
        suf = order[p + k:]
        kk = len(seg)
        segpos = {}
        for i, j in enumerate(seg):
            segpos[j] = i
        spreds = [[segpos[q] for q in preds[j] if q in segpos] for j in seg]
        used = [False] * kk
        seq = []
        orig = list(seg)
        res = {"thr": cur_ms, "bms": cur_ms, "best": None, "eq": None,
               "eqc": 0, "nodes": 0, "cut": False}

        def leaf(cm):
            thr = res["thr"]
            ms = cm
            if ms > thr:
                return
            done = []
            ok = True
            for j in suf:
                t = ptime(j)
                if t + tail[j] > thr:
                    ok = False
                    break
                put(j, t, 1)
                st[j] = t
                done.append(j)
                if t + dur[j] > ms:
                    ms = t + dur[j]
            for j in done:
                put(j, st[j], -1)
            if not ok or ms > thr:
                return
            if ms < res["bms"]:
                res["bms"] = ms
                res["best"] = list(seq)
                res["thr"] = ms - 1
            elif ms == cur_ms and res["best"] is None and seq != orig:
                res["eqc"] += 1
                if rng.randrange(res["eqc"]) == 0:
                    res["eq"] = list(seq)

        def dfs(s_last, r_last, cm):
            if res["cut"]:
                return
            if res["nodes"] >= limit:
                res["cut"] = True
                return
            res["nodes"] += 1
            if (res["nodes"] & 31) == 0 and time.perf_counter() > deadline:
                res["cut"] = True
                return
            if len(seq) == kk:
                leaf(cm)
                return
            thr = res["thr"]
            if cm > thr:
                return
            cands = []
            for i in range(kk):
                if used[i]:
                    continue
                ok = True
                for q in spreds[i]:
                    if not used[q]:
                        ok = False
                        break
                if not ok:
                    continue
                j = seg[i]
                t = ptime(j)
                t2 = t if t > s_last else s_last
                if t2 + tail[j] > thr:
                    return
                if t < s_last or (t == s_last and rank[j] < r_last):
                    continue
                cands.append((t + tail[j], t, -dur[j], i))
            cands.sort()
            for _, t, _, i in cands:
                if res["cut"]:
                    return
                j = seg[i]
                if t + tail[j] > res["thr"]:
                    continue
                used[i] = True
                st[j] = t
                put(j, t, 1)
                seq.append(j)
                e = t + dur[j]
                dfs(t, rank[j], cm if cm > e else e)
                seq.pop()
                put(j, t, -1)
                used[i] = False

        dfs(-1, -1, pre_ms)
        pre = list(order[:p])
        if res["best"] is not None:
            return "imp", pre + res["best"] + list(suf), res["bms"], res["cut"]
        if res["eq"] is not None:
            return "eq", pre + res["eq"] + list(suf), cur_ms, res["cut"]
        return "none", None, cur_ms, res["cut"]

    def run_lns(deadline):
        if best["order"] is None or n < 3:
            return
        cur = list(best["order"])
        cur_ms = _sgs(cur, n, dur, rel, preds, req, cap, H)[1]
        k = min(n, 6)
        fails = 0
        limit = 700
        while best["ms"] > LB and elapsed() < deadline:
            kk = min(k, n)
            p = rng.randrange(0, n - kk + 1)
            kind, o, ms, cut = lns_window(cur, p, kk, limit, cur_ms, t0 + deadline)
            if kind == "imp":
                o2, st2, ms2 = improve(o)
                if ms2 <= ms:
                    o, ms = o2, ms2
                    stx = st2
                else:
                    stx = _sgs(o, n, dur, rel, preds, req, cap, H)[0]
                    o = sorted(range(n), key=lambda j: (stx[j], rank[j]))
                    stx, ms = _sgs(o, n, dur, rel, preds, req, cap, H)
                if consider(stx, ms, o):
                    insert_to_pop(ms, o)
                cur = list(o)
                cur_ms = _sgs(cur, n, dur, rel, preds, req, cap, H)[1]
                fails = 0
            else:
                fails += 1
                if kind == "eq" and rng.random() < 0.6:
                    cur = o
                    cur_ms = ms
                if cut:
                    if k > 4:
                        k -= 1
                elif fails % max(4, n // 2) == 0 and k < min(n, 10):
                    k += 1
            if fails > 3 * n + 20:
                fails = 0
                if pop and rng.random() < 0.6:
                    pop.sort(key=lambda x: x[0])
                    cand = pop[rng.randrange(max(1, len(pop) // 3))][1]
                    cur = list(cand)
                else:
                    cur = list(best["order"])
                    # perturb by random insertions
                    for _ in range(3):
                        i = rng.randrange(n)
                        j = cur.pop(i)
                        lo, hi = window(cur, j)
                        cur.insert(rng.randint(lo, hi), j)
                o2, st2, ms2 = improve(cur)
                consider(st2, ms2, o2)
                cur = list(o2)
                cur_ms = _sgs(cur, n, dur, rel, preds, req, cap, H)[1]

    # Phase 1: GA
    run_ga(GA1_END, 600)

    # Phase 2: global branch and bound
    proven = best["ms"] is not None and best["ms"] <= LB
    if not proven and best["ms"] is not None and elapsed() < BNB_END:
        try:
            bms, bst, done = _bnb(n, dur, rel, preds, succs, req, cap, H,
                                  rank, topo, tail, indeg,
                                  best["ms"], best["st"], t0 + BNB_END, LB)
            if bst is not None and bms < best["ms"] and _validate(bst, n, dur, rel, preds, req, cap):
                o = sorted(range(n), key=lambda j: (bst[j], rank[j]))
                o2, st2, ms2 = improve(o)
                if ms2 < bms and _validate(st2, n, dur, rel, preds, req, cap):
                    best["ms"], best["st"], best["order"] = ms2, st2[:], o2
                else:
                    best["ms"], best["st"], best["order"] = bms, bst[:], o
                insert_to_pop(best["ms"], best["order"])
            if done:
                proven = True
        except Exception:
            pass

    # Phase 3: exact-window LNS
    if not proven:
        try:
            run_lns(TOTAL_END)
        except Exception:
            pass

    st = best["st"]
    if st is None or not _validate(st, n, dur, rel, preds, req, cap):
        st = [0] * n
        t = 0
        for j in topo:
            s = max(t, rel[j])
            for p in preds[j]:
                s = max(s, st[p] + dur[p])
            st[j] = s
            t = s + dur[j]
    state["output"] = {"status": "ok", "start": {ids[j]: int(st[j]) for j in range(n)}}
    return state

import heapq
import random
import time


def validate(state, params):
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    ids = [str(j.get("id")) for j in jobs]
    idset = set(ids)
    reason = None
    for j in jobs:
        jid = str(j.get("id"))
        for p in (j.get("after") or []):
            if str(p) not in idset:
                reason = "job %s references unknown job %s" % (jid, p)
                break
        if reason:
            break
        for rname, u in (j.get("requires") or {}).items():
            if rname not in res:
                reason = "job %s references unknown resource %s" % (jid, rname)
                break
            if u > res[rname]:
                reason = "job %s needs %s units of %s (capacity %s)" % (jid, u, rname, res[rname])
                break
        if reason:
            break
    if reason is None:
        preds = {}
        for j in jobs:
            preds.setdefault(str(j.get("id")), set()).update(str(p) for p in (j.get("after") or []))
        indeg = {i: len(preds[i]) for i in preds}
        succ = {i: [] for i in preds}
        for i in preds:
            for p in preds[i]:
                succ[p].append(i)
        stack = [i for i in preds if indeg[i] == 0]
        seen = 0
        while stack:
            x = stack.pop()
            seen += 1
            for s in succ[x]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    stack.append(s)
        if seen < len(preds):
            cyc = sorted(i for i in preds if indeg[i] > 0)[:5]
            reason = "precedence cycle among " + ", ".join(cyc)
    if reason is not None:
        state["feasible"] = False
        state["output"] = {"status": "infeasible", "reason": reason}
    else:
        state["feasible"] = True
    return state


def _check(starts, d, rel, preds, req, cap):
    n = len(d)
    if len(starts) != n:
        return False
    for j in range(n):
        s = starts[j]
        if not isinstance(s, int) or s < rel[j]:
            return False
        for p in preds[j]:
            if s < starts[p] + d[p]:
                return False
    events = {}
    for j in range(n):
        if d[j] > 0 and req[j]:
            events.setdefault(starts[j], []).append((j, 1))
            events.setdefault(starts[j] + d[j], []).append((j, -1))
    use = [0] * len(cap)
    for t in sorted(events):
        for j, sg in events[t]:
            if sg < 0:
                for k, u in req[j]:
                    use[k] -= u
        for j, sg in events[t]:
            if sg > 0:
                for k, u in req[j]:
                    use[k] += u
        for k in range(len(cap)):
            if use[k] > cap[k]:
                return False
    return True


def solve(state, params):
    T0 = time.perf_counter()
    inp = state["input"]
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "start": {}}
        return state
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cap = [res[r] for r in rnames]
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, x in enumerate(ids):
        jidx[x] = i
    d = [int(j.get("duration", 0) or 0) for j in jobs]
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    preds = []
    for j in jobs:
        ps = sorted(set(jidx[str(p)] for p in (j.get("after") or [])))
        preds.append(ps)
    req = []
    for j in jobs:
        lst = []
        for rname, u in (j.get("requires") or {}).items():
            if u and u > 0:
                lst.append((ridx[rname], u))
        req.append(lst)
    succs = [[] for _ in range(n)]
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
    indeg = [len(preds[j]) for j in range(n)]
    topo = []
    st = [j for j in range(n) if indeg[j] == 0]
    while st:
        x = st.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                st.append(s)
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + d[p])
        es[j] = e
    q = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m = max(m, q[s])
        q[j] = d[j] + m
    LB = max(es[j] + q[j] for j in range(n))
    for k in range(len(cap)):
        if cap[k] > 0:
            en = sum(d[j] * u for j in range(n) for kk, u in req[j] if kk == k)
            mr = min(rel)
            LB = max(LB, mr + (en + cap[k] - 1) // cap[k])
    free = [d[j] == 0 or not req[j] for j in range(n)]
    H = max(rel) + sum(d) + 2
    out_starts = None

    # ---------- fallback: strictly serial ----------
    def serial():
        s = [0] * n
        t = 0
        for j in topo:
            st_ = max(t, rel[j])
            for p in preds[j]:
                st_ = max(st_, s[p] + d[p])
            s[j] = st_
            t = st_ + d[j]
        return s

    best = serial()
    best_ms = max(best[j] + d[j] for j in range(n))

    # ---------- SGS sampling for an upper bound ----------
    def sgs(order):
        usage = [[0] * H for _ in cap]
        s = [0] * n
        for j in order:
            t = rel[j]
            for p in preds[j]:
                t = max(t, s[p] + d[p])
            if not free[j]:
                dj = d[j]
                rq = req[j]
                ok = False
                while not ok:
                    ok = True
                    for tau in range(t, t + dj):
                        for k, u in rq:
                            if usage[k][tau] + u > cap[k]:
                                ok = False
                                break
                        if not ok:
                            t = tau + 1
                            break
                for tau in range(t, t + dj):
                    for k, u in rq:
                        usage[k][tau] += u
            s[j] = t
        return s

    tot_succ = [0] * n
    for j in reversed(topo):
        acc = set()
        for s_ in succs[j]:
            acc.add(s_)
        stack = list(succs[j])
        while stack:
            x = stack.pop()
            for y in succs[x]:
                if y not in acc:
                    acc.add(y)
                    stack.append(y)
        tot_succ[j] = len(acc)
    rules = [
        [-q[j] for j in range(n)],
        [es[j] - q[j] for j in range(n)],
        [-tot_succ[j] for j in range(n)],
        [es[j] for j in range(n)],
        [-(d[j] + sum(d[s_] for s_ in succs[j])) for j in range(n)],
        [rel[j] - q[j] for j in range(n)],
    ]
    rng = random.Random(12345)

    def gen(prio, noise):
        indg = [len(preds[j]) for j in range(n)]
        elig = [j for j in range(n) if indg[j] == 0]
        order = []
        while elig:
            if noise > 0:
                bj = min(elig, key=lambda x: prio[x] + rng.random() * noise)
            else:
                bj = min(elig, key=lambda x: (prio[x], x))
            elig.remove(bj)
            order.append(bj)
            for s_ in succs[bj]:
                indg[s_] -= 1
                if indg[s_] == 0:
                    elig.append(s_)
        return order

    def consider(s):
        nonlocal best, best_ms
        ms = max(s[j] + d[j] for j in range(n))
        if ms < best_ms and _check(s, d, rel, preds, req, cap):
            best, best_ms = s, ms

    for pr in rules:
        consider(sgs(gen(pr, 0)))
    it = 0
    span = max(1, max(q) + 1)
    while best_ms > LB and time.perf_counter() - T0 < 0.3:
        pr = rules[it % len(rules)]
        consider(sgs(gen(pr, span * (0.3 + 0.7 * rng.random()))))
        it += 1

    # ---------- event-time A* ----------
    if best_ms > LB:
        predmask = [0] * n
        for j in range(n):
            for p in preds[j]:
                predmask[j] |= 1 << p
        full = (1 << n) - 1
        nres = len(cap)
        records = []  # (parent, assignments)

        def closure(t, mask, running):
            # running: dict job->end (end>t); start free eligible jobs eagerly
            asg = []
            changed = True
            while changed:
                changed = False
                runmask = 0
                for jj in running:
                    runmask |= 1 << jj
                for j in range(n):
                    if (mask >> j) & 1 or not free[j] or rel[j] > t:
                        continue
                    pm = predmask[j]
                    if (mask & pm) == pm and (runmask & pm) == 0:
                        mask |= 1 << j
                        asg.append((j, t))
                        if d[j] > 0:
                            running[j] = t + d[j]
                            runmask |= 1 << j
                        changed = True
            return mask, asg

        def heur(t, mask, running):
            e = [0] * n
            f = t
            for jj, en in running.items():
                f = max(f, en + q[jj] - d[jj])
            energy = [0] * nres
            for jj, en in running.items():
                for k, u in req[jj]:
                    energy[k] += (en - t) * u
            for j in topo:
                if (mask >> j) & 1:
                    continue
                v = rel[j] if rel[j] > t else t
                for p in preds[j]:
                    if (mask >> p) & 1:
                        en = running.get(p)
                        if en is not None and en > v:
                            v = en
                    else:
                        w = e[p] + d[p]
                        if w > v:
                            v = w
                e[j] = v
                if v + q[j] > f:
                    f = v + q[j]
                for k, u in req[j]:
                    energy[k] += d[j] * u
            for k in range(nres):
                if cap[k] > 0 and energy[k] > 0:
                    v = t + (energy[k] + cap[k] - 1) // cap[k]
                    if v > f:
                        f = v
            return f

        heap = []
        closed = set()
        cnt = 0
        run0 = {}
        t0 = min(rel)
        m0, a0 = closure(t0, 0, run0)
        records.append((-1, a0))
        h0 = heur(t0, m0, run0)
        if h0 < best_ms:
            heapq.heappush(heap, (h0, -bin(m0).count("1"), -t0, cnt, t0, m0,
                                  tuple(sorted(run0.items())), -1, 0))
        deadline = T0 + 1.15
        found = None
        while heap:
            cnt += 1
            if (cnt & 255) == 0 and (time.perf_counter() > deadline or len(closed) > 400000):
                break
            f, _a, _b, _c, t, mask, runt, last, rid = heapq.heappop(heap)
            if f >= best_ms:
                break
            if mask == full:
                found = rid
                break
            key = (t, mask, runt, last)
            if key in closed:
                continue
            closed.add(key)
            running = dict(runt)
            use = [0] * nres
            runmask = 0
            for jj in running:
                runmask |= 1 << jj
                for k, u in req[jj]:
                    use[k] += u
            # start one more job at t (index > last)
            for j in range(last + 1, n):
                if (mask >> j) & 1 or rel[j] > t:
                    continue
                pm = predmask[j]
                if (mask & pm) != pm or (runmask & pm) != 0:
                    continue
                okr = True
                for k, u in req[j]:
                    if use[k] + u > cap[k]:
                        okr = False
                        break
                if not okr:
                    continue
                nr = dict(running)
                nr[j] = t + d[j]
                nm = mask | (1 << j)
                if nm == full:
                    nf = max(nr.values()) if nr else t
                    nf = max(nf, t)
                else:
                    nf = heur(t, nm, nr)
                if nf < best_ms:
                    records.append((rid, [(j, t)]))
                    cnt += 1
                    heapq.heappush(heap, (nf, -bin(nm).count("1"), -t, cnt, t, nm,
                                          tuple(sorted(nr.items())), j, len(records) - 1))
            # advance to next event
            nt = None
            for en in running.values():
                if en > t and (nt is None or en < nt):
                    nt = en
            for j in range(n):
                if not (mask >> j) & 1 and rel[j] > t and (nt is None or rel[j] < nt):
                    nt = rel[j]
            if nt is not None:
                nr = {jj: en for jj, en in running.items() if en > nt}
                nm, asg = closure(nt, mask, nr)
                if nm == full:
                    ends = [en for en in nr.values()]
                    nf = max(ends) if ends else nt
                    nf = max(nf, nt)
                else:
                    nf = heur(nt, nm, nr)
                if nf < best_ms:
                    records.append((rid, asg))
                    cnt += 1
                    heapq.heappush(heap, (nf, -bin(nm).count("1"), -nt, cnt, nt, nm,
                                          tuple(sorted(nr.items())), -1, len(records) - 1))
        if found is not None:
            s = [None] * n
            r_ = found
            while r_ >= 0:
                par, asg = records[r_]
                for j, tt in asg:
                    s[j] = tt
                r_ = par
            if all(x is not None for x in s):
                consider(s)

    if not _check(best, d, rel, preds, req, cap):
        best = serial()
    out_starts = {}
    for j in range(n):
        out_starts[ids[j]] = int(best[j])
    state["output"] = {"status": "ok", "start": out_starts}
    return state
